    steps = "S\tHunter\t\tcompletewith=next\nI\t\tStand still for 0.5 seconds before Auto Shot.\nS\t\t\t\nA\t\t92460\t\nS\t\t\t\nT\t\t92460\t\nA\t\t92461\t\nS\t\t\t\nA\t\t92462\t\nS\t\t\t\nI\t\tKill eight Juvenile Vuldren and eight Pesky Cirrusflies around the grove for {q92461} and {q92462}.\nC\t\t92461\t\t\nC\t\t92462\t\t\nS\t\t\t\nT\t\t92461\t\nS\t\t\t\nI\t\tReach level 2 on Juvenile Vuldren and Pesky Cirrusflies in the grove before the next pickups.\nX\t\t\t2\t\t\t\nS\tWarrior\t\t\nA\t\t92532\t\nS\tSkyborne Shaman\t\t\nA\t\t92484\t\nS\tSkyborne Shaman\t\t\nT\t\t92484\t\nS\tSkyborne Shaman\t\t\nG\t\tZephras Isle\t42.77\t23.58\t\t\t\nI\t\tAt Windshaper Boro, learn Rockbiter Weapon I.\nV\t\ttrainer\t\nS\tRogue\t\t\nA\t\t92483\t\nS\tSkyborne Hunter\t\t\nA\t\t92482\t\nS\tSkyborne Hunter\t\t\nT\t\t92482\t\nS\tHunter\t\t\nG\t\tZephras Isle\t42.46\t23.67\t\t\t\nI\t\tLearn Track Beasts from Tai'ree Farsight.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nI\t\tRead the Folded Parchment, then accept {q92485}.\nA\t\t92485\t\nS\tSkyborne Druid\t\t\nT\t\t92485\t\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t41.71\t23.36\t\t\t\nI\t\tAt Xyton Silverwind, learn Mark of the Wild I and available early spells.\nV\t\ttrainer\t\nS\t\t\t\nA\t\t93552\t\nS\t\t\tcompletewith=next\nG\t\tZephras Isle\t46.59\t17.83\t20\t0\t\nG\t\tZephras Isle\t48.13\t29.3\t\t\t\nI\t\tCollect fifteen Windstone Clusters from Raw Windstones during the northern quests and Cirrusfly Queen quest for {q93552}.\nC\t\t93552\t\t\nS\t\t\t\nT\t\t92462\t\nA\t\t92463\t\nS\t\t\t\nA\t\t94414\t\nS\t\t\t\nI\t\tAsk Halaan Hawk Eye to show you the anchor for {q94414}.\nC\t\t94414\t\t\nS\t\t\t\nT\t\t94414\t\nS\t\t\t\nA\t\t92474\t\nS\tWarrior\t\t\nI\t\tClimb the Thendal Village watchtower to Blademaster Ren, then turn in {q92532}.\nT\t\t92532\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t43.65\t24.17\t\t\t\nI\t\tAt Blademaster Ren, learn Battle Shout I.\nV\t\ttrainer\t\nS\tRogue\t\t\nI\t\tMeet Akeri Duskblade inside the watchtower, then turn in {q92483}.\nT\t\t92483\t\nS\tRogue\t\t\nG\t\tZephras Isle\t43.73\t24.3\t\t\t\nI\t\tAt Akeri Duskblade, learn Stealth I.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tClimb the watchtower, jump from the top and use Walk on Air to slow your fall for {q92474}.\nC\t\t92474\t\t\nS\t\t\t\nA\t\t92598\t\nS\t\t\t\nT\t\t92474\t\nS\t\t\t\nA\t\t92464\t\nS\t\t\t\nT\t\t92464\t\nS\t\t\t\nA\t\t92465\t\nS\t\t\t\nI\t\tUse Skysight at the Elemental Convergence for {q92598}.\nC\t\t92598\t\t\nS\t\t\t\nI\t\tKill six Roiling Winds and seven Al'Aketh Converts on the northern slopes for {q92465}.\nC\t\t92465\t\t\nS\t\t\t\nT\t\t92465\t\nS\t\t\t\nI\t\tReach level 3 on Roiling Winds and Converts on the northern slopes before taking the return message.\nX\t\t\t3\t\t\t\nS\t\t\t\nA\t\t92469\t\nS\t\t\t\nI\t\tKill the Cirrusfly Queen east of the grove for {q92463}.\nC\t\t92463\t\t\nS\t\t\t\nT\t\t92463\t\nS\t\t\t\nI\t\tTurn in {q93552}. Choose a free Herbalism, Mining or Skinning book; use it when eligible to learn your chosen profession.\nT\t\t93552\t\nS\t\t\t\nT\t\t92598\t\nS\t\t\t\nT\t\t92469\t\nS\tSkyborne Shaman\t\t\nA\t\t92466\t\nS\tSkyborne Shaman\t\t\nI\t\tCollect a Signet of Akir from the Al'Aketh Converts around the northern standing stones for {q92466}.\nC\t\t92466\t\t\nS\tSkyborne Shaman\t\t\nT\t\t92466\t\nA\t\t92467\t\nS\tSkyborne Shaman\t\t\nG\t\tZephras Isle\t47.5\t25.3\t\t\t\nI\t\tTake the uphill pass northeast of the grove to the Rise of Spirits.\nS\tSkyborne Shaman\t\t\nI\t\tFollow the path east to the Rise of Spirits. Drink the Earth Sapta at the sacred rock, then turn in {q92467} to the Minor Manifestation of Earth.\nU\t\t6635\t\nT\t\t92467\t\nS\tSkyborne Shaman\t\t\nA\t\t92468\t\nS\tSkyborne Shaman\t\t\nI\t\tReturn to Windshaper Boro, then turn in {q92468}. Receive your Earth Totem and learn Stoneskin Totem I; keep the totem in your bags.\nT\t\t92468\t\nS\t\t\t\nI\t\tReach level 4 on level 3-4 wildlife along the western grove path before the western quests.\nX\t\t\t4\t\t\t\nS\tShaman\t\t\nG\t\tZephras Isle\t42.77\t23.58\t\t\t\nI\t\tAt Windshaper Boro, learn Earth Shock I.\nV\t\ttrainer\t\nS\t\t\t\nA\t\t92471\t\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t41.71\t23.36\t\t\t\nI\t\tLearn Moonfire I, Rejuvenation I, Wrath and Healing Touch at Xyton Silverwind.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t42.46\t23.67\t\t\t\nI\t\tAt Tai'ree Farsight, learn Aspect of the Monkey and Serpent Sting I.\nV\t\ttrainer\t\nS\t\t\t\nT\t\t92471\t\nA\t\t92470\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t43.65\t24.17\t\t\t\nI\t\tAt Blademaster Ren, learn Charge I and Rend I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t43.73\t24.3\t\t\t\nI\t\tAt Akeri Duskblade, learn Pick Pocket and Backstab I.\nV\t\ttrainer\t\nS\t\t\t\nA\t\t92473\t\nS\t\t\t\nI\t\tCollect six claws from Scrawny Ursera along the western path for {q92473}.\nC\t\t92473\t\t\nS\t\t\t\nG\t\tZephras Isle\t38.3\t27.3\t\t\t\nI\t\tFollow the hillside path to Thendal Cave's entrance.\nS\t\t\t\nI\t\tKill eight Ursera Scavengers, then clear through the cave to Urs'anah and take her head for {q92470}.\nC\t\t92470\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to your initial Thendal Grove binding if ready; otherwise leave the cave by its entrance and follow the western path back to the village.\nH\t\tHearth to Thendal Grove\nS\t\t\t\nT\t\t92473\t\nS\t\t\t\nT\t\t92470\t\nA\t\t96638\t\nA\t\t92472\t\nS\t\t\t\nA\t\t92544\t\nS\t\t\t\nI\t\tKill six Al'Aketh Brutes and four Neophytes. Clear around Malduko Cloudcrush, then defeat him for {q92544}.\nC\t\t92544\t\t\nS\t\t\t\nT\t\t92544\t\nS\t\t\t\nI\t\tFollow the road south to Shen'dar Village.\nS\t\t\t\nT\t\t96638\t\nA\t\t96101\t\nS\t\t\t\nI\t\tType /sit beside Raan Wildwind's campfire and wait until Boosted Rest appears for {q96101}.\nC\t\t96101\t\t\nS\t\t\t\nT\t\t96101\t\nA\t\t96646\t\nS\t\t\t\nT\t\t92472\t\nS\t\t\t\nA\t\t92514\t\nS\t\t\t\nI\t\tEnter the inn by its ramp. Speak with Coriella Calmbreeze for {q92514}, then bind and sell junk. Restock food and drinks as needed for faster health and mana recovery.\nB\t\tSet your hearthstone to Shen'dar Village\nC\t\t92514\t2\t\nS\t\t\t\nI\t\tSpeak with Illaya Amberwind for {q92514}.\nC\t\t92514\t1\t\nS\t\t\t\nT\t\t92514\t\nS\t\t\t\nA\t\t92517\t\nS\t\t\t\nA\t\t92595\t\nS\t\t\t\nI\t\tSit with your faction representative and hear the introduction for {q92595}.\nC\t\t92595\t\t\nS\t\t\t\nT\t\t92595\t\nS\t\t\t\nI\t\tReach level 5 before fighting Prideclaw; finish on Scrawny Ursera or Al'Aketh Neophytes along the western path if needed.\nX\t\t\t5\t\t\t\nS\t\t\t\nA\t\t94411\t\nS\t\t\t\nI\t\tTrain your chosen primary professions in Shen'dar Village, including any gathering profession not already learned from your starter book or a trainer. Engineering follows at the Strange Hermit during the later Shadowgale Forest visit.\nV\t\tvendor\t\nS\t\t\t\nG\t\tZephras Isle\t43.11\t46.27\t\t\t\nI\t\tLearn Apprentice First Aid from Naleeia Tattermend.\nS\t\t\t\nA\t\t93318\t\nS\t\t\t\nG\t\tZephras Isle\t45.05\t48.39\t\t\t\nI\t\tLearn Apprentice Fishing from Fenn Fairweather.\nS\t\t\t\nG\t\tZephras Isle\t45.05\t48.39\t\t\t\nI\t\tBuy a Fishing Pole from Fenn Fairweather; equip it when fishing.\nK\t\t6256\t1\t\t\nS\t\t\t\nA\t\t92516\t\nA\t\t93319\t\nS\t\t\t\nA\t\t92515\t\nS\t\t\t\nA\t\t93951\t\nS\t\t\t\nG\t\tZephras Isle\t43.85\t43.89\t\t\t\nI\t\tLearn Apprentice Cooking from Zerril Softbreeze.\nS\t\t\t\nT\t\t96646\t\nA\t\t92553\t\nS\t\t\t\nG\t\tZephras Isle\t43.85\t43.89\t\t\t\nI\t\tBuy Flint and Tinder from Zerril Softbreeze; keep it for crafting campfire kits.\nK\t\t4471\t1\t\t\nS\t\t\t\nG\t\tZephras Isle\t43.85\t43.89\t\t\t\nI\t\tBuy one Simple Wood from Zerril Softbreeze for your first campfire kit.\nK\t\t4470\t1\t\t\nS\t\t\tcompletewith=next\nI\t\tCollect three Small Eggs from the nesting birds and eight Strider Meat from Galestriders north of the nests.\nK\t\t6889\t3\t\t\nK\t\t5469\t8\t\t\nS\t\t\t\nI\t\tCollect ten Prideclaw Pelts from the western highlands for {q92515}.\nC\t\t92515\t\t\nS\t\t\t\nT\t\t92515\t\nS\t\t\t\nI\t\tReach level 6 on nearby Prideclaws before the hippogryph grounds and bandit camp.\nX\t\t\t6\t\t\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t43.96\t45.32\t\t\t\nI\t\tAt Corsan Earthrazer, learn Parry and Thunder Clap I.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tZephras Isle\t43.42\t45.01\t\t\t\nI\t\tAt Aarnor Galestrike, learn Earthbind Totem and Healing Wave II.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t44.85\t43.93\t\t\t\nI\t\tAt Naeluna Swiftmend, learn Wrath II and Thorns I, plus available healing ranks.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t45.26\t44.24\t\t\t\nI\t\tAt Elayaa Easewind, learn Arcane Shot I and Hunter's Mark I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t43.05\t43.28\t\t\t\nI\t\tAt Miriaan Mistblade, learn Gouge I and Sinister Strike II.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tKill six High Order Apprentices in the highlands for {q94411}.\nC\t\t94411\t\t\nS\t\t\t\nG\t\tZephras Isle\t48.8\t36.5\t\t\t\nI\t\tKill ten Highlands Bandits and collect ten Pilfered Windstones at the northern camp. Enter the hideout behind the waterfall and clear to Badwind Bennic; defeat him for {q93319} and {q92517}.\nC\t\t93319\t\t\nC\t\t92517\t\t\nS\t\t\t\nI\t\tKill eight Hippogryph Youths and six Protectors, collecting eight Hippogryph Down feathers around the nesting grounds. Clear around a Matriarch and defeat her for {q92516} and {q93951}.\nC\t\t92516\t\t\nC\t\t93951\t\t\nS\t\t\t\nI\t\tGo to Vulgara's approach and form a party; clear a retreat before engaging.\nS\t\t\t\nI\t\tDefeat Vulgara and take her head for {q93318}.\nC\t\t93318\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the village if ready; otherwise follow the road back.\nH\t\tHearth to Shen'dar Village\nS\t\t\t\nT\t\t92553\t\nS\t\t\t\nT\t\t94411\t\nS\tSkyborne Druid\t\t\nI\t\tEquip the Idol of Shifting Tides from Illaya's quest reward.\nS\t\t\t\nT\t\t93319\t\nT\t\t92516\t\nS\t\t\t\nT\t\t93951\t\nS\t\t\t\nT\t\t93318\t\nS\t\t\t\nT\t\t92517\t\nA\t\t93036\t\nS\t\t\t\nT\t\t93036\t\nS\t\t\t\nI\t\tAccept {q92529} and ask Sania for the Mark of Akir disguise before leaving.\nA\t\t92529\t\nS\t\t\t\nT\t\t92529\t\nA\t\t92528\t\nS\t\t\t\nI\t\tUnder the Mark of Akir disguise, listen to the High Missionary and investigate Falaath Village for {q92528}.\nC\t\t92528\t\t\nS\t\t\t\nT\t\t92528\t\nS\t\t\t\nI\t\tReach level 7 before the highland camps; finish on isolated highland birds or bandits if needed.\nX\t\t\t7\t\t\t\nS\t\t\t\nA\t\t92550\t\nA\t\t93926\t\nS\t\t\t\nA\t\t92551\t\nS\t\t\t\nI\t\tRecover ten Stolen Supply Packs while killing six Stormcallers and four Living Lightning around Falaath. Clear to Commander Cyclas, defeat him and take his head for {q92550} and {q92551}.\nC\t\t92550\t\t\nC\t\t92551\t\t\nS\t\t\t\nT\t\t93926\t\nA\t\t93927\t\nS\t\t\t\nG\t\tZephras Isle\t42.37\t62.07\t\t\t\nI\t\tRead the Bloody Note at the Western Watch.\nS\t\t\t\nI\t\tDefeat Skypriest Aanders, then collect Raani's Lucky Feather and the Shadowsong Family Signet beside him for {q93927}.\nC\t\t93927\t\t\nS\t\t\t\nG\t\tZephras Isle\t41.13\t64.07\t\t\t\nI\t\tCollect Raani's Lucky Feather.\nS\t\t\t\nG\t\tZephras Isle\t40.98\t64.09\t\t\t\nI\t\tCollect the Shadowsong Family Signet.\nS\t\t\tcompletewith=next\nI\t\tHearth to the village if ready; otherwise take the road back.\nH\t\tHearth to Shen'dar Village\nS\t\t\t\nT\t\t92551\t\nS\t\t\t\nT\t\t92550\t\nT\t\t93927\t\nS\t\t\t\nA\t\t92579\t\nS\t\t\t\nA\t\t93948\t\nS\t\t\t\nI\t\tReach level 8 on level 7-8 cultists around the cleared Falaath outskirts before heading south.\nX\t\t\t8\t\t\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t43.96\t45.32\t\t\t\nI\t\tAt Corsan Earthrazer, learn Hamstring I and Heroic Strike II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tZephras Isle\t43.42\t45.01\t\t\t\nI\t\tAt Aarnor Galestrike, learn Earth Shock II, Lightning Bolt II, Lightning Shield I, Rockbiter Weapon II and Stoneclaw Totem I.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t44.85\t43.93\t\t\t\nI\t\tLearn Entangling Roots I and Healing Touch II from Naeluna Swiftmend.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t45.26\t44.24\t\t\t\nI\t\tAt Elayaa Easewind, learn Concussive Shot, Parry and Raptor Strike II.\nV\t\ttrainer\t\nS\tSkyborne Hunter\t\tcompletewith=next\nG\t\tZephras Isle\t45.26\t44.24\t\t\t\nI\t\tIf already level 10, accept {q94007} from Elayaa Easewind before leaving Shen'dar; skip otherwise.\nA\t\t94007\t\nS\tRogue\t\t\nG\t\tZephras Isle\t43.05\t43.28\t\t\t\nI\t\tAt Miriaan Mistblade, learn Evasion and Eviscerate II.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tFollow the main road south to Valanaar.\nS\t\t\t\nT\t\t93948\t\nS\t\t\t\nT\t\t92579\t\nS\t\t\t\nA\t\t93949\t\nS\t\t\t\nI\t\tKill Skyhoppers around Valanaar until eight Enchanted Skyhoppers are defeated for {q93949}.\nC\t\t93949\t\t\nS\t\t\t\nT\t\t93949\t\nS\t\t\t\nA\t\t92700\t\nS\t\t\t\nT\t\t92700\t\nA\t\t92708\t\nS\t\t\t\nI\t\tHear your faction leader's account for {q92708}.\nC\t\t92708\t\t\nS\t\t\t\nT\t\t92708\t\nA\t\t93735\t\nS\t\t\t\nA\t\t93736\t\nS\t\t\t\nT\t\t93735\t\nA\t\t93737\t\nS\t\t\t\nG\t\tZephras Isle\t59.01\t72.93\t\t\t\nI\t\tSpeak with Riaani and hear his instructions before searching for the construct parts.\nS\t\t\t\nA\t\t93317\t\nS\t\t\t\nG\t\tZephras Isle\t61.64\t73.26\t\t\t\nI\t\tBind with Donaal Downbreeze at the inn; sell and restock.\nB\t\tSet your hearthstone to Valanaar\nS\t\t\t\nA\t\t92679\t\nS\t\t\t\nI\t\tHear Alvarion's request for {q92679}.\nC\t\t92679\t2\t\nS\t\t\t\nI\t\tCollect six Windsong Crawler Meat from the rivers west of Valanaar for {q93317}.\nC\t\t93317\t\t\nS\t\t\t\nI\t\tFollow the road west to Aamelia in the orchard.\nS\t\t\t\nT\t\t92679\t\nA\t\t92682\t\nA\t\t92683\t\nA\t\t92684\t\nS\t\t\t\nI\t\tAround the orchard, collect ten Ripe Stormapples, kill five Hungry Bandits and collect seven Tenderloins from Ornery Galestriders. Use the Flutterfly Swatter on Flutterflies before combat and collect five Flutterfly Dust from the ground for {q92682}, {q92683}, and {q92684}.\nC\t\t92682\t\t\nC\t\t92683\t\t\nC\t\t92684\t\t\nS\t\t\t\nA\t\t92698\t\nS\t\t\t\nT\t\t92698\t\nT\t\t92682\t\nT\t\t92683\t\nT\t\t92684\t\nA\t\t92685\t\nS\t\t\t\nG\t\tZephras Isle\t43.27\t74.95\t\t\t\nI\t\tFollow the western path onto the Bandit Highwaymen's ridge and collect seven Bloodstained Masks for {q92685}.\nC\t\t92685\t\t\nS\t\t\t\nG\t\tZephras Isle\t43.3\t74.5\t\t\t\nI\t\tSearch the Construct Parts on the ridge for the Air Construct Core.\nS\t\t\t\nI\t\tReturn down the same ridge path to Aamelia, then turn in {q92685}.\nT\t\t92685\t\nS\t\t\t\nI\t\tReach level 9 on level 8-9 galestriders or bandits before defending the orchard.\nX\t\t\t9\t\t\t\nS\t\t\t\nA\t\t92693\t\nS\t\t\t\nI\t\tSpeak with Aamelia to begin her defense, then protect her through the waves for {q92693}.\nC\t\t92693\t\t\nS\t\t\t\nT\t\t92693\t\nA\t\t92703\t\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: CRAB_SEASON\nS\t\t\t\nI\t\tGuide migration: Collect six Windsong Crawler Meat from the rivers west of Valanaar for {q93317}.\nC\t\t93317\t\t\nS\t\t\t\nI\t\t-- MIGRATION END: CRAB_SEASON\nS\t\t\t\nG\t\tZephras Isle\t51.4\t68.9\t\t\t\nI\t\tFollow the river northeast to the Shriekling Den entrance.\nS\t\t\t\nG\t\tZephras Isle\t51.4\t67.5\t\t\t\nI\t\tSearch the Construct Parts inside the cave for Crystallized Lightning, then leave by the entrance.\nS\t\t\t\nG\t\tZephras Isle\t52.9\t51.7\t\t\t\nI\t\tFollow the river north to Windsong Lake and dive for the Enchanted Gyrozephyr among the Construct Parts on the lakebed.\nS\t\t\t\nI\t\tRecover the Air Construct Core, Crystallized Lightning and Enchanted Gyrozephyr for {q93737}.\nC\t\t93737\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Valanaar if ready; otherwise surface and follow the river south to the Valanaar road.\nH\t\tHearth to Valanaar\nS\t\t\t\nT\t\t92703\t\nS\t\t\t\nT\t\t93317\t\nS\t\t\t\nT\t\t93737\t\nA\t\t93738\t\nS\t\t\t\nT\t\t93738\t\nA\t\t93746\t\nS\t\t\t\nI\t\tSpeak with Belathaan Brightwish along the shrine road and resolve the confrontation for {q93746}.\nC\t\t93746\t\t\nS\t\t\t\nT\t\t93746\t\nA\t\t93740\t\nA\t\t92871\t\nS\t\t\t\nT\t\t92871\t\nS\t\t\t\nA\t\t93320\t\nS\t\t\t\nI\t\tReach level 10 on isolated level 9-10 cultists along the Valanaar approach before the class unlocks and tower circuit.\nX\t\t\t10\t\t\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t57.88\t77.04\t\t\t\nI\t\tAt Zelena Favorbreeze's Auction House, buy a useful weapon of a type you already know. Keep a usable one-handed weapon and shield ready; reserve money for training.\nV\t\tvendor\t\nS\tWarrior\t\t\nI\t\tAccept {q94003}; keep it for the Shrine of Akir assault.\nA\t\t94003\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t59.86\t72.82\t\t\t\nI\t\tAt Seena Skybreaker, learn Bloodrage and Rend II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tZephras Isle\t58.33\t78.44\t\t\t\nI\t\tAt Sessaria Skystride, learn Flame Shock I, Flametongue Weapon I and Strength of Earth Totem I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t59.56\t73.14\t\t\t\nI\t\tAt Eltheen Nightbreeze, learn Dual Wield, Sap I, Slice and Dice I and Sprint I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t57.88\t77.04\t\t\t\nI\t\tAt Zelena Favorbreeze's Auction House, buy a usable weapon upgrade and an off-hand dagger; equip both weapons after learning Dual Wield.\nV\t\tvendor\t\nS\tSkyborne Hunter\t\tcompletewith=next\nG\t\tZephras Isle\t59.61\t72.65\t\t\t\nI\t\tTurn in {q94007} to Quel'ana Quickgale if carrying Elayaa's referral.\nT\t\t94007\t\nS\tSkyborne Hunter\t\t\nA\t\t94978\t\nS\tSkyborne Hunter\t\t\nI\t\tUse the Taming Rod on an isolated Windsong Crawler for {q94978}, then return to Quel'ana Quickgale.\nC\t\t94978\t\t\nS\tSkyborne Hunter\t\t\nT\t\t94978\t\nA\t\t94979\t\nS\tSkyborne Hunter\t\t\nI\t\tUse the Taming Rod on an isolated Ornery Galestrider for {q94979}, then return to Quel'ana Quickgale.\nC\t\t94979\t\t\nS\tSkyborne Hunter\t\t\nT\t\t94979\t\nA\t\t94013\t\nS\tSkyborne Hunter\t\t\nI\t\tUse the Taming Rod on an isolated Vuldren Alpha for {q94013}, then return to Quel'ana Quickgale.\nC\t\t94013\t\t\nS\tSkyborne Hunter\t\t\nT\t\t94013\t\nA\t\t94050\t\nS\tHunter\t\t\nG\t\tZephras Isle\t59.61\t72.65\t\t\t\nI\t\tAt Quel'ana Quickgale, learn Aspect of the Hawk, Serpent Sting II and Track Humanoids.\nV\t\ttrainer\t\nS\tSkyborne Hunter\t\t\nI\t\tTurn in {q94050} and learn Beast Training, Call Pet, Dismiss Pet, Feed Pet and Revive Pet from Quel'dora Quickgale.\nT\t\t94050\t\nS\tHunter\t\t\nG\t\tZephras Isle\t59.62\t72.59\t\t\t\nI\t\tAt Quel'dora Quickgale, learn Growl II, Great Stamina I, Natural Armor I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t45.04\t77.09\t\t\t\nI\t\tTame a Vuldren Alpha as your permanent pet. Feed it suitable food and use Bite II until learned for Beast Training.\nS\tHunter\t\t\nI\t\tTeach your pet the available Growl, stamina and armor ranks through Beast Training; enable Bite and Growl for solo work.\nS\tSkyborne Druid\t\t\nA\t\t94006\t\nS\tSkyborne Druid\t\t\nT\t\t94006\t\nA\t\t94638\t\nS\tSkyborne Druid\t\t\nI\t\tDefeat Ur'endra on the western slope for {q94638}.\nC\t\t94638\t\t\nS\tSkyborne Druid\t\t\nI\t\tTurn in {q94638} and learn Bear Form.\nT\t\t94638\t\nS\tSkyborne Druid\t\tcompletewith=next\nI\t\tHearth to Valanaar if ready; otherwise return along the road.\nH\t\tHearth to Valanaar\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t64.01\t75.1\t\t\t\nI\t\tAt Lotheluum Starbreeze, learn Demoralizing Roar I, Mark of the Wild II, Moonfire II, Rejuvenation II and Nature's Grasp I.\nV\t\ttrainer\t\nS\tSkyborne Shaman\t\t\nA\t\t97243\t\nS\tSkyborne Shaman\t\t\nI\t\tFollow the lowland paths to Olariaan Swiftburn at the Shrine of Flames. Turn in {q97243}, then accept {q97244}.\nT\t\t97243\t\nA\t\t97244\t\nS\t\t\t\nA\t\t94484\t\nS\t\t\t\nA\t\t94896\t\nA\t\t94897\t\nS\t\t\t\nT\t\t93320\t\nA\t\t92642\t\nA\t\t92645\t\nS\t\t\t\nI\t\tKill four Al'Aketh Healers and eight Brawlers in the Gustberry Lowlands, collecting ten Windstone Charms from the cultists for {q92642} and {q93740}. Pull away from the road patrols.\nC\t\t92642\t\t\nC\t\t93740\t\t\nS\tSkyborne Shaman\t\t\nI\t\tKill Skypriest Faladiel in the Gustberry Lowlands and collect his heart for {q97244}.\nC\t\t97244\t\t\nS\t\t\t\nI\t\tClear the guards around Commander Belguilos, then defeat him for {q92645}.\nC\t\t92645\t\t\nS\t\t\t\nT\t\t92642\t\nT\t\t92645\t\nA\t\t92880\t\nS\t\t\t\nT\t\t92880\t\nA\t\t92881\t\nS\t\t\t\nT\t\t92881\t\nA\t\t92643\t\nS\t\t\t\nA\t\t98512\t\nS\t\t\t\nI\t\tKill ten Al'Aketh Assassins along the western approach for {q98512}.\nC\t\t98512\t\t\nS\t\t\t\nT\t\t98512\t\nS\t\t\t\nI\t\tFind the fallen turncoat and investigate the body; hear the nearby account for {q92643}.\nC\t\t92643\t\t\nS\t\t\t\nT\t\t92643\t\nA\t\t92644\t\nS\t\t\t\nT\t\t92644\t\nA\t\t94568\t\nS\t\t\t\nI\t\tListen to Talaanis explain the plans for {q94568}.\nC\t\t94568\t\t\nS\t\t\t\nT\t\t94568\t\nA\t\t92640\t\nS\t\t\t\nI\t\tSpeak with Valennia and the faction leaders to prepare the counterattack for {q92640}.\nC\t\t92640\t\t\nS\t\t\t\nT\t\t92640\t\nA\t\t93065\t\nS\t\t\t\nI\t\tReach level 11 before the forest quests; finish on isolated level 10-11 cultists around the cleared lowland camps if needed.\nX\t\t\t11\t\t\t\nS\tSkyborne Shaman\t\t\nT\t\t97244\t\nA\t\t97245\t\nS\tSkyborne Shaman\t\t\nI\t\tReturn along the road toward Shen'dar Highlands. Knock on Kuramaa's Stump, defeat Kuramaa and collect the mask for {q97245}.\nC\t\t97245\t\t\nS\tSkyborne Shaman\t\t\nT\t\t97245\t\nA\t\t97257\t\nS\tSkyborne Shaman\t\t\nI\t\tFollow Olariaan's instructions at the Brazier of Offering and use the supplied torch when prompted to capture the Eternal Flame for {q97257}.\nC\t\t97257\t1\t\nS\tSkyborne Shaman\t\t\nI\t\tCarry the lit torch directly to Valanaar before its timer expires and light the Brazier of Eternal Flame for {q97257}.\nU\t\t277329\t\nC\t\t97257\t2\t\nS\tSkyborne Shaman\t\t\nI\t\tTurn in {q97257} to Sessaria Skystride to receive your Fire Totem and learn Searing Totem I; keep the totem in your bags.\nT\t\t97257\t\nS\t\t\t\nI\t\tTake the road north into Shadowgale Forest.\nS\t\t\t\nT\t\t94484\t\nA\t\t94485\t\nA\t\t94486\t\nA\t\t94487\t\nS\t\t\t\nA\t\t93165\t\nS\t\t\t\nI\t\tCollect eight Tears of the Lady moss along the forest rocks for {q94485}.\nC\t\t94485\t\t\nS\t\t\t\nI\t\tCollect twenty Binding Feathers from Shadowgale Shrieklings for {q94486}.\nC\t\t94486\t\t\nS\t\t\t\nA\t\t93159\t\nS\t\t\t\nI\t\tSpeak with the Strange Hermit for {q93159}.\nC\t\t93159\t\t\nS\t\t\t\nT\t\t93159\t\nA\t\t93160\t\nA\t\t93172\t\nS\t\t\t\nI\t\tCollect eight Shadowgale Acorns around the forest floor for {q93160}.\nC\t\t93160\t\t\nS\t\t\t\nI\t\tDefeat ten Wind Hollows in the forest, collecting ten Wind Hollow Essences for {q93172} and {q93736}.\nC\t\t93172\t\t\nC\t\t93736\t\t\nS\t\t\t\nI\t\tCollect eight Abandoned Belongings around Ban'aethal for {q94896}.\nC\t\t94896\t\t\nS\t\t\t\nI\t\tDefeat Resaan Nimbuswalker and recover the heirloom for {q94897}.\nC\t\t94897\t\t\nS\t\t\t\nT\t\t93160\t\nT\t\t93172\t\nS\t\t\t\nI\t\tCollect ten Bloody Heirlooms and five Cultist Ears from Al'Aketh Stormchasers and Footsoldiers at the northern camps for {q94487} and {q93165}.\nC\t\t94487\t\t\nC\t\t93165\t\t\nS\t\t\t\nT\t\t94485\t\nT\t\t94486\t\nT\t\t94487\t\nA\t\t94488\t\nA\t\t94489\t\nS\t\t\t\nT\t\t93165\t\nS\t\t\t\nI\t\tDefeat Commander Haalien at the northern camp for {q94488}; loot and keep his Ripped Missive if available.\nC\t\t94488\t\t\nS\t\t\t\nG\t\tZephras Isle\t64.48\t34.74\t\t\t\nI\t\tEnter Nightfang Den by its path. Click each of the seven injured druids to heal them, then speak with Jorel Windsinger inside for {q94489}.\nC\t\t94489\t\t\nS\t\t\t\nT\t\t94488\t\nT\t\t94489\t\nS\t\t\tcompletewith=next\nI\t\tRead a personally found Ripped Missive, then accept {q94490}.\nU\t\t265476\t\nA\t\t94490\t\nS\t\t\t\nG\t\tZephras Isle\t61.76\t39.14\t\t\t\nT\t\t94490\t\nS\t\t\tcompletewith=next\nG\t\tZephras Isle\t61.76\t39.14\t\t\t\nA\t\t94491\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Valanaar if ready; otherwise leave the den by its entrance and take the road south.\nH\t\tHearth to Valanaar\nS\t\t\t\nT\t\t94896\t\nT\t\t94897\t\nS\t\t\t\nT\t\t93736\t\nS\t\t\t\nG\t\tZephras Isle\t64.01\t75.1\t\t\t\nT\t\t94491\t\nS\t\t\t\nI\t\tReach level 12 on Shadowgale Shrieklings, Wind Hollows or the cleared cultist camps before the shrine assault.\nX\t\t\t12\t\t\t\nS\tShaman\t\t\nG\t\tZephras Isle\t58.33\t78.44\t\t\t\nI\t\tAt Sessaria Skystride, learn Ancestral Spirit I, Fire Nova I, Healing Wave III and Purge I.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nG\t\tZephras Isle\t64.01\t75.1\t\t\t\nI\t\tLearn Enrage, Regrowth I and Revive I from Lotheluum Starbreeze.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t59.86\t72.82\t\t\t\nI\t\tAt Seena Skybreaker, learn Battle Shout II, Overpower I and Shield Bash I. Keep a one-handed weapon and shield ready for Shield Bash interrupts.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t59.56\t73.14\t\t\t\nI\t\tAt Eltheen Nightbreeze, learn Kick I, Parry and Backstab II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t59.61\t72.65\t\t\t\nI\t\tAt Quel'ana Quickgale, learn Arcane Shot II, Distracting Shot I, Mend Pet I and Wing Clip I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t59.62\t72.59\t\t\t\nI\t\tAt Quel'dora Quickgale, learn Great Stamina II, Natural Armor II. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\t\t\t\nT\t\t93065\t\nA\t\t92947\t\nS\t\t\t\nI\t\tClear seven Guardians, seven Spiritcallers and seven Blademasters at the Shrine of Akir, then report to Hyusaa for {q92947}.\nC\t\t92947\t\t\nS\tWarrior\t\t\nI\t\tDuring the shrine assault, defeat Zaal Stormshield on the western side and recover the Skybreaker Bulwark for {q94003}.\nC\t\t94003\t\t\nS\t\t\t\nT\t\t92947\t\nA\t\t93958\t\nS\t\t\t\nT\t\t93958\t\nS\t\t\t\nA\t\t92646\t\nS\t\t\t\nI\t\tTake the portal to the Rohashi Spires. Join the faction leaders and follow the confrontation through to its conclusion for {q92646}.\nC\t\t92646\t\t\nS\t\t\t\nI\t\tReturn to Valanaar with the leaders.\nS\t\t\t\nT\t\t93740\t\nT\t\t92646\t\nA\t\t93836\t\nS\t\t\t\nT\t\t93836\t\nA\t\t93090\t\nS\tWarrior\t\t\nI\t\tTurn in {q94003} to Seena Skybreaker. Learn Defensive Stance, Taunt and Sunder Armor I.\nT\t\t94003\t\nS\t\t\t\nI\t\tReach level 14 before leaving the island. If needed, hunt Al'Aketh Guardians along the cleared shrine approach, then return by the main road to Valanaar.\nX\t\t\t14\t\t\t\nS\tWarrior\t\t\nG\t\tZephras Isle\t59.86\t72.82\t\t\t\nI\t\tAt Seena Skybreaker, learn Demoralizing Shout I, Revenge I and Tactical Mastery.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tZephras Isle\t58.33\t78.44\t\t\t\nI\t\tAt Sessaria Skystride, learn Earth Shock III, Lightning Bolt III and Stoneskin Totem II.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tZephras Isle\t59.56\t73.14\t\t\t\nI\t\tAt Eltheen Nightbreeze, learn Garrote I, Expose Armor I and Sinister Strike III.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tZephras Isle\t59.61\t72.65\t\t\t\nI\t\tAt Quel'ana Quickgale, learn Eagle Eye, Eyes of the Beast and Scare Beast I.\nV\t\ttrainer\t\nS\t\t\t\nT\t\t93090\t\nA\t\t95349\t\nS\t\t\t\nG\t\tZephras Isle\t57.9\t80.9\t\t\t\nI\t\tBoard the western skycutter for Mulgore.\nS\t\t\t\nT\t\t95349\t\nS\t\t\t\nA\t\t95350\t\nS\tSkyborne Druid\t\t\nA\t\t94911\t\nS\tSkyborne Druid\t\t\nA\t\t6126\t\nS\t\t\t\nI\t\tFollow the path east down from Skywatcher Plateau to its foot at 39.7,16.9, then take the road to Thunder Bluff and use a lift to the city.\nS\tWarrior\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one- and two-handed Maces, Staves or Guns.\nV\t\ttrainer\t\nS\tHunter\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: Staves or Guns.\nV\t\ttrainer\t\nS\tRogue\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one-handed Maces or Guns.\nV\t\ttrainer\t\nS\tShaman\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: two-handed Maces.\nV\t\ttrainer\t\nS\tDruid\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one- and two-handed Maces.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tThunder Bluff\t40.41\t51.77\t\t\t\nI\t\tAt Auctioneer Stampi, buy a usable ranged weapon and its ammunition, or a thrown weapon, for pulling enemies into cleared ground.\nV\t\tvendor\t\nS\tSkyborne Druid\t\t\nI\t\tBuy five Earthroot at the Thunder Bluff Auction House before leaving the city.\nV\t\tvendor\t\nS\tSkyborne Druid\t\t\nT\t\t94911\t\nS\tSkyborne Druid\t\t\nG\t\tThunder Bluff\t76.48\t27.22\t\t\t\nI\t\tAt Turak Runetotem, learn Bash I, Healing Touch III, Thorns II and Wrath III. Learn any earlier useful ranks still available.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nA\t\t94913\t\nS\tSkyborne Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid\t\t\nT\t\t94913\t\nS\tSkyborne Druid\t\t\nT\t\t6126\t\nA\t\t6127\t\nS\tSkyborne Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tSkyborne Druid\t\t\nI\t\tTake the lift down and follow the roads east through Mulgore to the Barrens, then north toward the Crossroads. Stay on the road past the southern wildlife.\nS\tSkyborne Druid\t\t\nG\t\tThe Barrens\t51.5\t30.34\t\t\t\nI\t\tTake the wind rider point on arrival.\nP\t\tThe Crossroads\t\nS\tSkyborne Druid\t\t\nI\t\tFollow the winding path up Dreadmist Peak and fill the Empty Dreadmist Sampler at the summit pool for {q6127}. Pull cultists into cleared ground.\nU\t\t15842\t\nC\t\t6127\t\t\nS\tSkyborne Druid\t\t\nT\t\t6127\t\nA\t\t6128\t\nS\tSkyborne Druid\t\t\nI\t\tCollect five Kodo Horns from Lost Barrens Kodos on the northern grassland for {q6128}.\nC\t\t6128\t\t\nS\tSkyborne Druid\t\t\nT\t\t6128\t\nA\t\t6129\t\nS\tSkyborne Druid\t\t\nI\t\tUse the Curative Animal Salve on ten Sickly Gazelles in the northern Barrens for {q6129}.\nU\t\t15826\t\nC\t\t6129\t\t\nS\tSkyborne Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid\t\t\nT\t\t6129\t\nA\t\t6130\t\nS\tSkyborne Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the flight to Thunder Bluff.\nS\tSkyborne Druid\t\t\nI\t\tTurn in {q6130} and learn Cure Poison.\nT\t\t6130\t\nS\t\t\t\nG\t\tThunder Bluff\t47.0\t49.83\t\t\t\nI\t\tTake the wind rider point.\nP\t\tThunder Bluff\t\nS\t\t\t\nI\t\tFly to Orgrimmar for the Warchief audience.\nF\t\tOrgrimmar\t\nS\t\t\t\nT\t\t95350\t\nS\t\t\t\nA\t\t5726\t\nS\t\t\t\nG\t\tOrgrimmar\t54.1\t68.41\t\t\t\nI\t\tBind with Innkeeper Gryshka for the Skull Rock return.\nB\t\tSet your hearthstone to Orgrimmar\nS\tWarrior/Hunter\t\tcompletewith=next\nG\t\tOrgrimmar\t81.7\t19.55\t\t\t\nI\t\tAt Sayoc, learn missing skills for weapons you plan to use: one- and two-handed Axes, Bows, Daggers, Thrown or Fist Weapons.\nV\t\ttrainer\t\nS\tRogue\t\tcompletewith=next\nG\t\tOrgrimmar\t81.7\t19.55\t\t\t\nI\t\tAt Sayoc, learn missing skills for weapons you plan to use: one-handed Axes, Bows, Thrown or Fist Weapons.\nV\t\ttrainer\t\nS\tShaman\t\tcompletewith=next\nG\t\tOrgrimmar\t81.7\t19.55\t\t\t\nI\t\tAt Sayoc, learn missing skills for weapons you plan to use: one- and two-handed Axes, Daggers or Fist Weapons.\nV\t\ttrainer\t\nS\tDruid\t\tcompletewith=next\nG\t\tOrgrimmar\t81.7\t19.55\t\t\t\nI\t\tAt Sayoc, learn missing skills for weapons you plan to use: Daggers or Fist Weapons.\nV\t\ttrainer\t\nS\tWarrior/Hunter\t\tcompletewith=next\nG\t\tOrgrimmar\t81.53\t19.63\t\t\t\nI\t\tAt Hanashi, learn missing skills for weapons you plan to use: Staves.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tLeave Orgrimmar by the main gate, then take the northeast coast path to Skull Rock.\nS\t\t\t\nI\t\tClear Burning Blade cultists and collect a Lieutenant's Insignia for {q5726}; pull out of the cave and avoid the deeper rare.\nC\t\t5726\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Orgrimmar if ready; otherwise return by the road.\nH\t\tHearth to Orgrimmar\nS\t\t\t\nT\t\t5726\t\nA\t\t5727\t\nS\t\t\t\nI\t\tQuestion Neeru Fireblade in the Cleft of Shadow for {q5727}.\nC\t\t5727\t\t\nS\t\t\t\nT\t\t5727\t\nA\t\t5728\t\nS\t\t\t\nI\t\tRepair and restock. Keep Hidden Enemies for Ragefire Chasm; continue with the Barrens route from Orgrimmar.\nV\t\tvendor\t" },
  { name = "11-19 The Barrens (Horde)", title = "11-19 The Barrens", group = "Bethink's Guide 1-20", faction = "Horde", lo = 11, hi = 19, next = "19-21 Silverpine Forest (Horde)", defaultFor = "Orc/Troll/Tauren/Undead", cond = "Horde", bethink = true,
    about = "Crossroads and Ratchet circuits, Ragefire Chasm at 15 and Wailing Caverns at 19. Ends in Orgrimmar for the Undercity zeppelin.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 11 or above. Carry Hidden Enemies; take Conscript of the Horde while passing Razor Hill if arriving from Mulgore or Tirisfal Glades.\nX\t\t\t11\t\t\t\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t34.18\t84.58\t\t\t\nI\t\tTrain Journeyman First Aid with Arnok (50 skill); skip if not ready.\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t57.4\t53.96\t\t\t\nI\t\tTrain Journeyman Cooking with Zamja (50 skill); skip if not ready.\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t69.8\t29.21\t\t\t\nI\t\tTrain Journeyman Fishing with Lumak (50 skill); skip if not ready.\nS\t\t\t\nI\t\tFollow the Durotar road south to Razor Hill, then west across the bridge into the Barrens.\nS\tTauren/Undead\t\t\nI\t\tAccept {q840} from Takrin Pathseeker before crossing into the Barrens.\nA\t\t840\t\nS\t\t\t\nT\t\t840\t\nA\t\t842\t\nS\tOrc Warrior/Troll Warrior/Tauren Warrior\t\t\nT\t\t1505\t\nA\t\t1498\t\nS\tOrc Warrior/Troll Warrior/Tauren Warrior\t\t\nG\t\tDurotar\t42.12\t26.66\t\t\t\nI\t\tCross back into Durotar, follow the road north past Razor Hill and enter Thunder Ridge by its northern approach.\nS\tOrc Warrior/Troll Warrior/Tauren Warrior\t\t\nI\t\tCollect five Singed Scales from Thunder Lizards and Lightning Hides for {q1498}; pull them onto cleared ground.\nC\t\t1498\t\t\nS\tOrc Warrior/Troll Warrior/Tauren Warrior\t\t\nI\t\tLeave by the northern approach and follow the roads past Razor Hill and across the bridge to Uzzek, then turn in {q1498}. Learn Defensive Stance, Taunt and Sunder Armor I.\nT\t\t1498\t\nS\tOrc Shaman/Troll Shaman\t\t\nI\t\tTurn in {q1522} to Kranal Fiss with Searn's message.\nT\t\t1522\t\nS\tTauren Shaman\t\t\nI\t\tTurn in {q1523} to Kranal Fiss with Xanis's message.\nT\t\t1523\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nA\t\t1524\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nG\t\tDurotar\t36.0\t57.0\t\t\t\nI\t\tCross the bridge into Durotar and follow the mountain trail up to Telf Joolam.\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nT\t\t1524\t\nA\t\t1525\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nG\t\tDurotar\t54.42\t42.59\t\t\t\nI\t\tReturn by the hill trail to Razor Hill. Take the eastern exit, then follow the upper ledge north to Dustwind Cave.\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nI\t\tEnter Dustwind Cave and collect a Reagent Pouch from Burning Blade Cultists. Leave by the cleared entrance.\nK\t\t6652\t1\t\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nI\t\tReturn across the bridge and collect one Fire Tar from the Razormane Water Seekers on the eastern plains.\nK\t\t5026\t1\t\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nG\t\tDurotar\t36.0\t57.0\t\t\t\nI\t\tReturn across the bridge and climb the same trail to Telf Joolam.\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nT\t\t1525\t\nA\t\t1526\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nI\t\tDrink the Fire Sapta at the shrine. Defeat the level-12 Minor Manifestation of Fire and loot its Glowing Ember for {q1526}.\nU\t\t6636\t\nC\t\t1526\t\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nI\t\tPlace the ember in the Brazier of the Dormant Flame, then turn in {q1526}.\nT\t\t1526\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nA\t\t1527\t\nS\tOrc Shaman/Troll Shaman/Tauren Shaman\t\t\nI\t\tDescend by the trail and return across the bridge to Kranal Fiss, then turn in {q1527}. Receive your Fire Totem and learn Searing Totem I; keep the totem in your bags.\nT\t\t1527\t\nS\t\t\t\nI\t\tFollow the road southwest to the Crossroads.\nS\t\t\t\nG\t\tThe Barrens\t51.99\t29.89\t\t\t\nI\t\tBind with Boorand; repair and restock.\nB\t\tSet your hearthstone to The Crossroads\nS\t\t\t\nA\t\t869\t\nS\t\t\t\nT\t\t842\t\nA\t\t844\t\nS\t\t\t\nA\t\t870\t\nS\t\t\t\nA\t\t871\t\nA\t\t5041\t\nS\t\t\t\nG\t\tThe Barrens\t51.5\t30.34\t\t\t\nI\t\tTake the flight point.\nP\t\tThe Crossroads\t\nS\t\t\t\nA\t\t848\t\nA\t\t1492\t\nS\t\t\t\nI\t\tCollect seven Plainstrider Beaks and twelve Raptor Heads from isolated level 11-12 plainstriders and Sunscale Lashtails around the Crossroads for {q844} and {q869}. Avoid centaur packs.\nC\t\t844\t\t\nC\t\t869\t\t\nS\t\t\t\nT\t\t869\t\nA\t\t3281\t\nS\t\t\t\nT\t\t844\t\nA\t\t845\t\nS\t\t\t\nI\t\tReach level 12 before the northern camps. If short, hunt isolated plainstriders outside the Crossroads.\nX\t\t\t12\t\t\t\nS\t\t\t\nI\t\tFly for training, keeping the Crossroads bound.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Shadow Bolt III, Health Funnel and Curse of Weakness II; learn Imp Phase Shift. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Battle Shout II, Overpower I and Shield Bash I. Keep a one-handed weapon and shield ready for Shield Bash interrupts.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Ancestral Spirit I, Fire Nova I, Healing Wave III and Purge I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Kick I, Parry and Backstab II.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Inner Fire I, Power Word: Fortitude II and Power Word: Shield II.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Fireball III, Conjure Food II and Slow Fall. Keep a few Light Feathers for Slow Fall.\nV\t\ttrainer\t\nS\tTauren Druid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tTauren Druid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Enrage, Regrowth I and Revive I.\nV\t\ttrainer\t\nS\tTauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Arcane Shot II, Distracting Shot I, Mend Pet I and Wing Clip I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Great Stamina II, Natural Armor II. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t45.12\t63.89\t20\t0\t\nG\t\tThunder Bluff\t47.0\t49.83\t\t\t\nI\t\tHearth to the Crossroads if ready; otherwise fly.\nH\t\tHearth to The Crossroads\nF\t\tThe Crossroads\t\nS\t\t\t\nI\t\tCollect four Zhevra Hooves from the open northern grassland for {q845}.\nC\t\t845\t\t\nS\t\t\t\nI\t\tKill eight Razormane Water Seekers, eight Thornweavers and three Hunters at the western Thorn Hill camps for {q871}. Pull casters into cleared ground.\nC\t\t871\t\t\nS\t\t\t\nI\t\tContinue east to the camp guarded by Geomancers and Defenders; recover a Crossroads Supply Crate for {q5041}.\nC\t\t5041\t\t\nS\t\t\t\nT\t\t845\t\nA\t\t903\t\nS\t\t\t\nT\t\t871\t\nT\t\t5041\t\nA\t\t872\t\nS\t\t\t\nA\t\t855\t\nA\t\t850\t\nS\t\t\t\nI\t\tInvestigate the bubbling water at the Forgotten Pools for {q870}; clear the bank before swimming.\nC\t\t870\t\t\nS\t\t\t\nI\t\tGather four Fungal Spores around the pool banks for {q848}.\nC\t\t848\t\t\nS\t\t\t\nI\t\tCollect fifteen Centaur Bracers around the Forgotten Pools and Barak's camp, stopping runners for {q855}.\nC\t\t855\t\t\nS\t\t\t\nI\t\tClear the guards around Barak Kodobane and take his head for {q850}.\nC\t\t850\t\t\nS\t\t\t\nT\t\t850\t\nT\t\t855\t\nA\t\t851\t\nS\t\t\t\nI\t\tCollect seven Prowler Claws from isolated Savannah Prowlers on the northern grassland for {q903}.\nC\t\t903\t\t\nS\t\t\t\nI\t\tKill eight Razormane Geomancers and eight Defenders, then clear to Kreenig Snarlsnout and take his tusk for {q872}.\nC\t\t872\t\t\nS\t\t\t\nT\t\t848\t\nS\t\t\t\nT\t\t872\t\nS\t\t\t\nT\t\t903\t\nA\t\t881\t\nS\t\t\t\nT\t\t870\t\nA\t\t877\t\nS\t\t\t\nI\t\tFollow the road southeast to Ratchet.\nS\t\t\t\nT\t\t1492\t\nS\t\t\t\nG\t\tThe Barrens\t63.08\t37.16\t\t\t\nI\t\tTake the flight point.\nP\t\tRatchet\t\nS\t\t\t\nI\t\tReach level 13 before the southern pirate camps; finish on isolated northern Barrens wildlife if needed.\nX\t\t\t13\t\t\t\nS\t\t\t\nA\t\t887\t\nS\t\t\t\nA\t\t895\t\nS\t\t\t\nA\t\t865\t\nS\t\t\t\nI\t\tKill twelve Southsea Brigands and six Cannoneers on the northern pirate shore for {q887}. Pull into cleared ground.\nC\t\t887\t\t\nS\t\t\t\nT\t\t887\t\nA\t\t890\t\nS\t\t\t\nT\t\t890\t\nA\t\t892\t\nS\t\t\t\nT\t\t892\t\nA\t\t888\t\nS\t\t\t\nI\t\tCollect the Telescopic Lens and Shipment of Boots from the southern pirate camps for {q888}.\nC\t\t888\t\t\nS\t\t\t\nI\t\tClear Baron Longshore and his guards; take his head for {q895}.\nC\t\t895\t\t\nS\t\t\t\nT\t\t888\t\nT\t\t895\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise return by the road.\nH\t\tHearth to The Crossroads\nS\t\t\t\nI\t\tReach level 14 before the stronger southern raptors. Finish on isolated northern prowlers if needed.\nX\t\t\t14\t\t\t\nS\t\t\t\nI\t\tFly for training.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Corruption II, Drain Life and Curse of Recklessness; learn Imp Blood Pact II and Fire Shield I. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Demoralizing Shout I, Revenge I and Tactical Mastery.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Earth Shock III, Lightning Bolt III and Stoneskin Totem II.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Garrote I, Expose Armor I and Sinister Strike III.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Cure Disease, Psychic Scream I, Renew II and Smite III.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tLeave Orgrimmar by the main gate and take the Tirisfal zeppelin; enter Undercity by its main lifts for training.\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Blessing of Wisdom I and Holy Light III.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tLeave Undercity by the main lifts and take the Orgrimmar zeppelin back before continuing.\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Arcane Intellect II, Frostbolt III, Fire Blast II and Arcane Explosion I.\nV\t\ttrainer\t\nS\tTauren Druid\t\t\nI\t\tFly to Thunder Bluff for Druid training and Lessons Anew.\nF\t\tThunder Bluff\t\nS\tTauren Druid\t\t\nI\t\tBuy five Earthroot at the Thunder Bluff Auction House.\nV\t\tvendor\t\nS\tTauren Druid\t\t\nG\t\tThunder Bluff\t76.48\t27.22\t\t\t\nI\t\tAt Turak Runetotem, learn Bash I, Healing Touch III, Thorns II and Wrath III.\nV\t\ttrainer\t\nS\tTauren Druid\t\t\nA\t\t6126\t\nS\tTauren Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tTauren Druid\t\t\nT\t\t6126\t\nA\t\t6127\t\nS\tTauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tTauren Druid\t\tcompletewith=next\nG\t\tThunder Bluff\t47.0\t49.83\t\t\t\nI\t\tHearth to the Crossroads if ready; otherwise fly to the Crossroads.\nH\t\tHearth to The Crossroads\nF\t\tThe Crossroads\t\nS\tTauren Druid\t\t\nI\t\tFollow the winding path up Dreadmist Peak and fill the Empty Dreadmist Sampler at the summit pool for {q6127}. Pull cultists into cleared ground.\nU\t\t15842\t\nC\t\t6127\t\t\nS\tTauren Druid\t\t\nT\t\t6127\t\nA\t\t6128\t\nS\tTauren Druid\t\t\nI\t\tCollect five Kodo Horns from Lost Barrens Kodos on the northern grassland for {q6128}.\nC\t\t6128\t\t\nS\tTauren Druid\t\t\nT\t\t6128\t\nA\t\t6129\t\nS\tTauren Druid\t\t\nI\t\tUse the Curative Animal Salve on ten Sickly Gazelles in the northern Barrens for {q6129}.\nU\t\t15826\t\nC\t\t6129\t\t\nS\tTauren Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tTauren Druid\t\t\nT\t\t6129\t\nA\t\t6130\t\nS\tTauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the flight to Thunder Bluff.\nS\tTauren Druid\t\t\nI\t\tTurn in {q6130} and learn Cure Poison.\nT\t\t6130\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Eagle Eye, Eyes of the Beast and Scare Beast I.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t45.12\t63.89\t20\t0\t\nG\t\tThunder Bluff\t47.0\t49.83\t\t\t\nI\t\tHearth to the Crossroads if ready; otherwise fly.\nH\t\tHearth to The Crossroads\nF\t\tThe Crossroads\t\nS\t\t\t\nA\t\t867\t\nS\t\t\t\nI\t\tCollect eight Witchwing Talons from Witchwing Harpies and Roguefeathers at the outer northwestern camps for {q867}. Pull into open ground and stop runners.\nC\t\t867\t\t\nS\t\t\t\nI\t\tClear the bones north of the Crossroads, use the Horn of Echeyakee, then defeat Echeyakee and take his hide for {q881}.\nC\t\t881\t\t\nS\t\t\t\nT\t\t867\t\nA\t\t875\t\nS\t\t\t\nT\t\t881\t\nA\t\t905\t\nS\t\t\t\nI\t\tAt the Stagnant Oasis, use the Dried Seeds at the Bubbling Fissure after clearing the water for {q877}.\nC\t\t877\t\t\nS\t\t\t\nI\t\tKill centaur around the oasis until Verog appears; defeat him and take his head for {q851}.\nC\t\t851\t\t\nS\t\t\t\nI\t\tCollect Sunscale Feathers from the raptors, then use them on the Blue, Yellow and Red nests for {q905}.\nC\t\t905\t\t\nS\t\t\t\nI\t\tRecover the Stolen Silver from the southern raptor den for {q3281}.\nC\t\t3281\t\t\nS\t\t\t\nI\t\tCollect five Intact Raptor Horns from Sunscale Scytheclaws for {q865}.\nC\t\t865\t\t\nS\t\t\t\nI\t\tReturn by the cleared roads to the Crossroads.\nS\t\t\t\nT\t\t877\t\nA\t\t880\t\nS\t\t\t\nT\t\t905\t\nA\t\t3261\t\nS\t\t\t\nT\t\t3281\t\nS\t\t\t\nI\t\tReturn to Ratchet by road.\nS\t\t\t\nA\t\t959\t\nS\t\t\t\nT\t\t865\t\nA\t\t1491\t\nS\t\t\t\nT\t\t851\t\nA\t\t852\t\nS\t\t\t\nI\t\tGo south to the Lushwater Oasis for the altered turtles.\nS\t\t\t\nI\t\tCollect eight Altered Snapjaw Shells from the oasis turtles for {q880}, pulling to cleared banks.\nC\t\t880\t\t\nS\t\t\t\nI\t\tDefeat Hezrul Bloodmark and his bodyguards near the Lushwater Oasis for {q852}.\nC\t\t852\t\t\nS\t\t\t\nT\t\t852\t\nA\t\t4021\t\nS\t\t\t\nI\t\tReturn to the Crossroads.\nS\t\t\t\nT\t\t880\t\nA\t\t1489\t\nS\t\t\t\nI\t\tFollow the Gold Road south to Camp Taurajo, keeping clear of quilboar camps.\nS\t\t\t\nG\t\tThe Barrens\t44.45\t59.15\t\t\t\nI\t\tTake the flight point.\nP\t\tCamp Taurajo\t\nS\t\t\t\nT\t\t3261\t\nA\t\t882\t\nS\t\t\t\nI\t\tTake the western road through Mulgore to Thunder Bluff. Use the lifts to reach the city.\nS\tTauren\t\t\nT\t\t98435\t\nS\t\t\t\nT\t\t1489\t\nA\t\t1490\t\nS\t\t\t\nT\t\t1490\t\nA\t\t914\t\nS\t\t\t\nA\t\t5722\t\nA\t\t5723\t\nS\t\t\t\nA\t\t962\t\nS\tOrc Warrior/Troll Warrior/Undead Warrior\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one- and two-handed Maces, Staves or Guns.\nV\t\ttrainer\t\nS\tOrc Hunter/Troll Hunter/Undead Hunter\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: Staves or Guns.\nV\t\ttrainer\t\nS\tOrc Paladin/Troll Paladin/Undead Paladin\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one- and two-handed Maces.\nV\t\ttrainer\t\nS\tOrc Rogue/Troll Rogue/Undead Rogue\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one-handed Maces or Guns.\nV\t\ttrainer\t\nS\tOrc Shaman/Troll Shaman/Undead Shaman\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: two-handed Maces.\nV\t\ttrainer\t\nS\tOrc Priest/Troll Priest/Undead Priest\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: one-handed Maces or Staves.\nV\t\ttrainer\t\nS\tOrc Warlock/Troll Warlock/Undead Warlock\t\tcompletewith=next\nG\t\tThunder Bluff\t40.93\t62.73\t\t\t\nI\t\tAt Ansekhwa, learn missing skills for weapons you plan to use: Staves.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair and restock for Ragefire Chasm; retain the Wailing Caverns quests for 19.\nV\t\tvendor\t\nS\t\t\t\nG\t\tThunder Bluff\t47.0\t49.83\t\t\t\nI\t\tTake the flight point on the central tower.\nP\t\tThunder Bluff\t\nS\t\t\t\nI\t\tReach level 15 before Ragefire Chasm. If short, fly to the Crossroads and hunt isolated level 14-15 wildlife, then return to Thunder Bluff.\nX\t\t\t15\t\t\t\nS\t\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\t\t\t\nA\t\t5761\t\nS\t\t\tcompletewith=next\nI\t\tBefore the clear, accept an eligible share of {q5725} from a party member; keep its books for the Undercity visit.\nA\t\t5725\t\nS\t\t\t\nI\t\tRepair, restock and clear bags for Ragefire Chasm.\nV\t\tvendor\t\nS\tHunter/Warlock\t\t\nI\t\tTurn off pet taunts while another player tanks.\nS\t\t\t\nI\t\tAt Ragefire Chasm's Cleft of Shadow entrance, join a five-player party with a tank and healer.\nS\t\t\t\nG\t\tOrgrimmar\t52.6\t49.0\t\t\t\nI\t\tEnter Ragefire Chasm from the Cleft of Shadow with the party. Complete one clear through Bazzalan and Jergosh.\nS\t\t\t\nI\t\tKill eight Ragefire Troggs and eight Shaman during the clear for {q5723}.\nC\t\t5723\t\t\nS\t\t\t\nI\t\tFind Maur Grimtotem's corpse in the trogg section and search it. Turn in {q5722}, then accept {q5724} from Maur's corpse.\nT\t\t5722\t\nA\t\t5724\t\nS\t\t\t\nI\t\tDefeat Taragaman the Hungerer and loot his heart for {q5761}.\nC\t\t5761\t\t\nS\t\t\t\nI\t\tDefeat Jergosh the Invoker and Bazzalan for {q5728}. Clear their guards separately.\nC\t\t5728\t\t\nS\t\t\tcompletewith=next\nI\t\tLoot Spells of Shadow and Incantations from the Nether while the quest is active for {q5725}.\nC\t\t5725\t\t\nS\t\t\t\nI\t\tLeave through the cleared entrance.\nS\t\t\t\nT\t\t5761\t\nS\t\t\t\nT\t\t5728\t\nA\t\t5729\t\nS\t\t\t\nT\t\t5729\t\nA\t\t5730\t\nS\t\t\t\nT\t\t5730\t\nS\t\t\t\nI\t\tReach level 16 before training. If short, return to the outer Witchwing camps before training.\nX\t\t\t16\t\t\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Life Tap II and Unending Breath; learn Voidwalker Sacrifice I. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Heroic Strike III, Mocking Blow I and Shield Block.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Cure Poison, Lightning Shield II and Rockbiter Weapon III.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Pick Lock, Feint I and Eviscerate III.\nV\t\ttrainer\t\nS\tRogue\t\t\nA\t\t2379\t\nS\tRogue\t\t\nI\t\tTurn in {q2379}, then accept {q2382} for the level-18 practice trip.\nT\t\t2379\t\nA\t\t2382\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t42.09\t49.48\t\t\t\nI\t\tBuy Thieves' Tools from Rekkul and keep them in your bags.\nV\t\tvendor\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Heal I and Mind Blast II.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tFly to Thunder Bluff for Paladin training.\nF\t\tThunder Bluff\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Retribution Aura I.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tFly back to Orgrimmar before continuing.\nF\t\tOrgrimmar\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Arcane Missiles II and Flamestrike I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Immolation Trap I, Mongoose Bite I and Raptor Strike III.\nV\t\ttrainer\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tFly to Thunder Bluff for Aquatic Form.\nF\t\tThunder Bluff\t\nS\tDruid\t\t\nG\t\tThunder Bluff\t76.48\t27.22\t\t\t\nI\t\tAt Turak Runetotem, learn Moonfire III, Rejuvenation III and Swipe I.\nV\t\ttrainer\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tAccept {q27} from Turak Runetotem.\nA\t\t27\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid/Tauren Druid\t\t\nT\t\t27\t\nA\t\t28\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tDive into Lake Elune'ara and loot a Shrine Bauble from a Bauble Container.\nK\t\t15877\t1\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tUse the bauble at the Shrine of Remulos for {q28}.\nU\t\t15877\t\nC\t\t28\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tTurn in {q28} to Tajarri, then accept {q30}.\nT\t\t28\t\nA\t\t30\t\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff; fly to the Crossroads.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tTake the northern road to the Sludge Fen and dive into its pool for the Half Pendant of Aquatic Agility in the Strange Lockbox.\nK\t\t15883\t1\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tReturn by road to Orgrimmar and take the Tirisfal zeppelin; enter Undercity by its main lifts.\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tUndercity\t63.25\t48.56\t\t\t\nI\t\tTake the flight point on arrival.\nP\t\tUndercity\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tFollow the western Tirisfal road into northern Silverpine Forest for the western coastal lockbox dive.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tSwim west from the northern wreck and dive to the Strange Lockbox for the Half Pendant of Aquatic Endurance. Use the nearby air bubbles between dives.\nK\t\t15882\t1\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tCombine the two pendant halves beside the Shrine of Remulos for {q30}.\nU\t\t15883\t\nC\t\t30\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nT\t\t30\t\nA\t\t31\t\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the flight to Thunder Bluff.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tTurn in {q31} and learn Aquatic Form from Turak.\nT\t\t31\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tFly back to Orgrimmar for the northern Barrens departure.\nF\t\tOrgrimmar\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tLeave Orgrimmar by the western gate and follow the road into the northern Barrens.\nS\t\t\t\nA\t\t858\t\nS\t\t\t\nI\t\tDefeat Supervisor Lugwizzle and loot the Ignition Key for {q858}.\nC\t\t858\t\t\nS\t\t\t\nT\t\t858\t\nS\t\t\t\nA\t\t863\t\nS\t\t\t\nI\t\tEscort Wizzlecrank out of the fen and protect the shredder through its ambush for {q863}.\nC\t\t863\t\t\nS\t\t\t\nI\t\tCollect six Harpy Lieutenant Rings from Witchwing Slayers in the inner harpy camps for {q875}.\nC\t\t875\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise return south by road.\nH\t\tHearth to The Crossroads\nS\tOrc Hunter/Troll Hunter\t\t\nG\t\tThe Barrens\t51.74\t29.66\t\t\t\nI\t\tStable your crocolisk with Sikwa for a Bite upgrade.\nS\tOrc Hunter/Troll Hunter\t\t\nG\t\tThe Barrens\t46.23\t38.34\t\t\t\nI\t\tTame an Oasis Snapjaw at the Lushwater Oasis and use Bite II until learned for Beast Training.\nS\tOrc Hunter/Troll Hunter\t\t\nG\t\tThe Barrens\t51.74\t29.66\t\t\t\nI\t\tReturn to Sikwa, release the training tame and retrieve your crocolisk. Open Beast Training and teach Bite II.\nS\t\t\t\nT\t\t875\t\nA\t\t876\t\nS\t\t\t\nI\t\tClear Serena Bloodfeather's guards and take her head for {q876}.\nC\t\t876\t\t\nS\t\t\t\nT\t\t876\t\nA\t\t1060\t\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: HEZRUL_BLOODMARK\nS\t\t\t\nI\t\tGuide migration: Defeat Hezrul Bloodmark and his bodyguards near the Lushwater Oasis for {q852}.\nC\t\t852\t\t\nS\t\t\t\nI\t\tGuide migration: Turn in {q852}, then accept {q4021}.\nT\t\t852\t\nA\t\t4021\t\nS\t\t\t\nI\t\t-- MIGRATION END: HEZRUL_BLOODMARK\nS\t\t\t\nI\t\tAt Regthar's camp, form a party for the Krom'zar defense before speaking to Regthar.\nS\t\t\t\nI\t\tSpeak to Regthar when the party is ready, defend the camp and defeat Warlord Krom'zar. Loot the Piece of Krom'zar's Banner for {q4021}.\nC\t\t4021\t\t\nS\t\t\t\nT\t\t4021\t\nS\t\t\t\nI\t\tReach level 17 before the eastern and southern circuits. If short, hunt isolated level 16-17 raptors outside the cleared camps.\nX\t\t\t17\t\t\t\nS\t\t\t\nI\t\tReturn to Ratchet.\nS\t\t\t\nA\t\t891\t\nS\t\t\t\nT\t\t863\t\nS\t\t\t\nI\t\tReach level 18 before Northwatch and Wailing Caverns preparation; finish on isolated level 17-18 wildlife outside Ratchet if needed.\nX\t\t\t18\t\t\t\nS\t\t\t\nI\t\tFly to Orgrimmar for level-18 training.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Bane of Agony II, Create Soulstone and Searing Pain; learn Imp Firebolt III and Voidwalker Consume Shadows I. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Disarm and Thunder Clap II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Flame Shock II, Flametongue Weapon II, Healing Wave IV, Stoneclaw Totem II and Tremor Totem.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Ambush I, Gouge II and Poised.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Dispel Magic I, Power Word: Shield III and Shadow Word: Pain III.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tFly to Thunder Bluff for Paladin training.\nF\t\tThunder Bluff\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Blessing of Freedom, Divine Protection II, Seal of Fury II and Seal of Righteousness III.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Fireball IV and Remove Lesser Curse.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aspect of the Hawk II, Multi-Shot I, Serpent Sting III and Track Undead.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Great Stamina III, Natural Armor III. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Entangling Roots II, Faerie Fire I, Hibernate I, Maul II, Nature's Grasp II and Regrowth II.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tFly to Ratchet.\nF\t\tRatchet\t\nS\tRogue\t\t\nT\t\t2382\t\nA\t\t2381\t\nS\tRogue\t\t\nG\t\tThe Barrens\t63.12\t36.32\t\t\t\nI\t\tUse Wrenix's Gizmotronic Apparatus to obtain E.C.A.C. and Thieves' Tools before leaving Ratchet.\nS\tRogue\t\t\nG\t\tThe Barrens\t65.08\t45.42\t\t\t\nI\t\tBoard the pirate ship south of Ratchet from its projecting bow. Go one level below deck, clear nearby enemies and practice Pick Lock on the Buccaneer's Strongboxes until 80 Lockpicking.\nS\tRogue\t\t\nI\t\tContinue to the lowest hold and open The Jewel of the Southsea to summon Polly. Use E.C.A.C. on the parrot, defeat it and take the Southsea Treasure for {q2381}.\nU\t\t7970\t\nC\t\t2381\t\t\nS\t\t\t\nI\t\tFollow the coastal approach to Northwatch Hold; clear each tower staircase for the medals and Gilthares's rescue.\nS\t\t\t\nI\t\tCollect ten Theramore Medals and defeat Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe for {q891}.\nC\t\t891\t\t\nS\t\t\t\nI\t\tFind Gilthares in the hold after clearing the escort route and accept {q898}.\nA\t\t898\t\nS\t\t\t\nI\t\tEscort Gilthares safely back to Ratchet for {q898}; stay with him through the road ambushes.\nC\t\t898\t\t\nS\t\t\t\nT\t\t891\t\nT\t\t898\t\nS\tRogue\t\t\nT\t\t2381\t\nS\t\t\t\nI\t\tTravel north from Ratchet to Ishamuhale's dead tree.\nS\t\t\t\nI\t\tKill a nearby Zhevra for its Fresh Zhevra Carcass, carry it to the dead tree northeast of Ratchet and use it to summon Ishamuhale. Defeat him and take his fang for {q882}.\nC\t\t882\t\t\nS\t\t\t\nI\t\tReturn west to the Crossroads, then follow the Gold Road south to Camp Taurajo.\nS\t\t\t\nT\t\t882\t\nA\t\t907\t\nS\t\t\t\nI\t\tCollect three Thunder Lizard Blood from level 18-19 thunder lizards on the open southern grassland for {q907}.\nC\t\t907\t\t\nS\t\t\t\nT\t\t907\t\nA\t\t913\t\nS\t\t\t\nG\t\tThe Barrens\t46.76\t50.95\t\t\t\nI\t\tCollect one Thunderhawk Wing from an isolated level 18-19 Thunderhawk for {q913}; leave level 20 targets until later.\nC\t\t913\t\t\nS\t\t\t\nT\t\t913\t\nA\t\t874\t\nS\t\t\t\nI\t\tFly to the Crossroads for Wailing Caverns.\nF\t\tThe Crossroads\t\nS\t\t\t\nI\t\tReach level 19 before Wailing Caverns; finish on isolated level 18-19 wildlife on the southern grassland if needed.\nX\t\t\t19\t\t\t\nS\t\t\t\nI\t\tRepair and restock, then travel to Wailing Caverns west of the Crossroads.\nV\t\tvendor\t\nS\t\t\t\nI\t\tReach Nalpak on the ledge above the cavern mouth by its outside path and accept {q1486}; do not jump from the roof.\nA\t\t1486\t\nS\t\t\t\nA\t\t1487\t\nS\t\t\t\nI\t\tAt the cavern mouth, join a five-player Wailing Caverns party with a tank and healer; include Mad Magglish in the outer approach.\nS\t\t\t\nG\t\tThe Barrens\t46.0\t36.4\t\t\t\nI\t\tEnter the cave together. Find Mad Magglish in the outer cavern before the instance portal.\nS\t\t\t\nI\t\tDefeat Mad Magglish with the party and loot the 99-Year-Old Port for {q959}.\nC\t\t959\t\t\nS\t\t\t\nI\t\tEnter Wailing Caverns and complete one clear through the four Fanglords and Mutanus.\nS\t\t\t\nI\t\tCollect twenty Deviate Hides during the cave and instance clear for {q1486}.\nC\t\t1486\t\t\nS\t\t\t\nI\t\tKill seven each of Deviate Ravagers, Vipers, Shamblers and Dreadfangs during the clear for {q1487}.\nC\t\t1487\t\t\nS\t\t\t\nI\t\tGather ten Serpentbloom plants along the cleared passages for {q962}.\nC\t\t962\t\t\nS\t\t\t\nI\t\tCollect six Wailing Essence from the ectoplasm creatures for {q1491}.\nC\t\t1491\t\t\nS\t\t\t\nI\t\tLoot the Gems of Cobrahn, Anacondra, Pythas and Serpentis from the four Fanglords for {q914}.\nC\t\t914\t\t\nS\t\t\t\nI\t\tAfter all four Fanglords, return to the Disciple of Naralex near the entrance. Speak when ready, protect his ritual and defeat Mutanus.\nS\t\t\tcompletewith=next\nI\t\tIf you receive the Glowing Shard from Mutanus, use it to accept {q6981}.\nA\t\t6981\t\nS\t\t\t\nI\t\tLeave by the cleared entrance.\nS\t\t\t\nT\t\t1486\t\nS\t\t\t\nT\t\t1487\t\nS\t\t\t\nI\t\tReturn to Ratchet by road.\nS\t\t\t\nT\t\t1491\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t62.98\t37.22\t\t\t\nI\t\tIf you have the shard, ask Sputtervalve about it for {q6981}.\nC\t\t6981\t\t\nS\t\t\t\nT\t\t959\t\nS\t\t\t\nT\t\t874\t\nS\t\t\t\nG\t\tThe Barrens\t48.18\t32.78\t\t\t\nT\t\t6981\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t48.18\t32.78\t\t\t\nA\t\t3369\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise take the road west.\nH\t\tHearth to The Crossroads\nS\t\t\t\nI\t\tFly for the Fanglord and Serpentbloom deliveries.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t962\t\nS\t\t\t\nT\t\t5724\t\nT\t\t5723\t\nS\t\t\t\nG\t\tThunder Bluff\t78.62\t28.56\t\t\t\nT\t\t3369\t\nS\t\t\t\nT\t\t914\t\nS\t\t\t\nI\t\tFly to Orgrimmar. Keep Letter to Jin'Zil and any Power to Destroy books.\nF\t\tOrgrimmar\t" },
  { name = "14-19 The Barrens (Horde)", title = "14-19 The Barrens", group = "Bethink's Guide 1-20", faction = "Horde", lo = 14, hi = 19, next = "19-21 Silverpine Forest (Horde)", defaultFor = "", cond = "Horde Skyborne", bethink = true,
    about = "Skyborne route through the Barrens, Ragefire Chasm at 16 and Wailing Caverns at 19. Ends in Orgrimmar for the Undercity zeppelin.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 14 after Zephras Isle, carrying Hidden Enemies. Keep your Orgrimmar binding until the Crossroads.\nX\t\t\t14\t\t\t\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t34.18\t84.58\t\t\t\nI\t\tTrain Journeyman First Aid with Arnok (50 skill); skip if not ready.\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t57.4\t53.96\t\t\t\nI\t\tTrain Journeyman Cooking with Zamja (50 skill); skip if not ready.\nS\t\t\tcompletewith=next\nG\t\tOrgrimmar\t69.8\t29.21\t\t\t\nI\t\tTrain Journeyman Fishing with Lumak (50 skill); skip if not ready.\nS\t\t\t\nI\t\tFollow the Durotar road south to Razor Hill.\nS\t\t\t\nA\t\t840\t\nS\t\t\t\nI\t\tFollow the road west across the bridge into the Barrens.\nS\t\t\t\nT\t\t840\t\nA\t\t842\t\nS\t\t\t\nI\t\tFollow the road southwest to the Crossroads.\nS\t\t\t\nG\t\tThe Barrens\t51.99\t29.89\t\t\t\nI\t\tBind with Boorand.\nB\t\tSet your hearthstone to The Crossroads\nS\t\t\t\nT\t\t842\t\nA\t\t844\t\nS\t\t\t\nA\t\t870\t\nS\t\t\t\nA\t\t867\t\nS\t\t\t\nG\t\tThe Barrens\t51.5\t30.34\t\t\t\nI\t\tTake the wind rider point.\nP\t\tThe Crossroads\t\nS\t\t\t\nA\t\t848\t\nA\t\t1492\t\nS\t\t\t\nI\t\tCollect seven Plainstrider Beaks from Greater and Fleeting Plainstriders on the northern grassland for {q844}.\nC\t\t844\t\t\nS\t\t\t\nT\t\t844\t\nA\t\t845\t\nS\t\t\t\nA\t\t855\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t43.57\t23.4\t20\t0\t\nG\t\tThe Barrens\t53.06\t41.74\t20\t0\t\nG\t\tThe Barrens\t46.04\t41.14\t\t\t\nI\t\tCollect fifteen Centaur Bracers during the Kolkar quests.\nK\t\t5030\t15\t\t\nS\t\t\t\nA\t\t850\t\nS\t\t\t\nI\t\tCollect four Zhevra Hooves from Zhevra Runners on the grassland west of the Crossroads for {q845}.\nC\t\t845\t\t\nS\t\t\t\nI\t\tInvestigate the bubbling water at the Forgotten Pools and gather four Fungal Spores from the banks for {q870} and {q848}.\nC\t\t870\t\t\nC\t\t848\t\t\nS\t\t\t\nI\t\tDefeat Barak Kodobane and take his head for {q850}.\nC\t\t850\t\t\nS\t\t\t\nT\t\t850\t\nA\t\t851\t\nS\t\t\t\nI\t\tReturn east to the Crossroads.\nS\t\t\t\nT\t\t848\t\nS\t\t\t\nT\t\t845\t\nA\t\t903\t\nS\t\t\t\nT\t\t870\t\nA\t\t877\t\nS\t\t\t\nI\t\tCollect seven Prowler Claws from Savannah Prowlers on the western grassland for {q903}.\nC\t\t903\t\t\nS\t\t\t\nI\t\tContinue north to the outer Witchwing camps. Collect eight Witchwing Talons from level 14-15 Witchwing Harpies for {q867}; avoid the stronger types and Sister Rathtalon.\nC\t\t867\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise take the road southeast.\nH\t\tHearth to The Crossroads\nS\t\t\t\nT\t\t867\t\nA\t\t875\t\nS\t\t\t\nT\t\t903\t\nA\t\t881\t\nS\t\t\t\nI\t\tClear around the bones, use the Horn of Echeyakee and defeat Echeyakee and collect his hide for {q881}.\nC\t\t881\t\t\nS\t\t\t\nT\t\t881\t\nA\t\t905\t\nS\t\t\t\nI\t\tFollow the road southeast to Ratchet.\nS\t\t\t\nA\t\t865\t\nS\t\t\t\nA\t\t895\t\nS\t\t\t\nG\t\tThe Barrens\t63.08\t37.16\t\t\t\nI\t\tTake the flight point.\nP\t\tRatchet\t\nS\t\t\t\nI\t\tAccept {q959}; keep it for Wailing Caverns.\nA\t\t959\t\nS\t\t\t\nT\t\t1492\t\nS\t\t\t\nA\t\t891\t\nS\t\t\t\nI\t\tReach level 15 before the Stagnant Oasis quests.\nX\t\t\t15\t\t\t\nS\t\t\t\nI\t\tFollow the grassland west to the Stagnant Oasis and use the Dried Seeds at the Bubbling Fissure for {q877}.\nC\t\t877\t\t\nS\t\t\t\nI\t\tDefeat centaur around the oasis until Verog appears, then take his head for {q851}.\nC\t\t851\t\t\nS\t\t\t\nI\t\tCollect five Intact Raptor Horns and Sunscale Feathers from the Scytheclaws. Use a feather on each Blue, Yellow and Red nest for {q905} and {q865}.\nC\t\t905\t\t\nC\t\t865\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise follow the road north.\nH\t\tHearth to The Crossroads\nS\t\t\t\nT\t\t905\t\nA\t\t3261\t\nS\t\t\t\nT\t\t877\t\nA\t\t880\t\nS\t\t\t\nT\t\t851\t\nA\t\t852\t\nS\t\t\t\nI\t\tCollect eight Altered Snapjaw Shells from the oasis turtles for {q880}.\nC\t\t880\t\t\nS\t\t\t\nI\t\tDefeat Hezrul Bloodmark and his bodyguards near the Lushwater Oasis for {q852}.\nC\t\t852\t\t\nS\t\t\t\nT\t\t852\t\nA\t\t4021\t\nS\t\t\t\nT\t\t880\t\nA\t\t1489\t\nS\t\t\t\nI\t\tFollow the Gold Road south to Camp Taurajo, keeping clear of the quilboar camps.\nS\t\t\t\nT\t\t3261\t\nA\t\t882\t\nS\t\t\t\nG\t\tThe Barrens\t44.45\t59.15\t\t\t\nI\t\tTake the flight point.\nP\t\tCamp Taurajo\t\nS\t\t\t\nI\t\tFly to Thunder Bluff for dungeon preparation.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t1489\t\nA\t\t1490\t\nS\t\t\t\nT\t\t1490\t\nA\t\t914\t\nS\t\t\t\nA\t\t5722\t\nA\t\t5723\t\nS\t\t\t\nI\t\tReach level 16 before training and Ragefire Chasm.\nX\t\t\t16\t\t\t\nS\tDruid\t\t\nG\t\tThunder Bluff\t76.48\t27.22\t\t\t\nI\t\tAt Turak Runetotem, learn Moonfire III, Rejuvenation III and Swipe I.\nV\t\ttrainer\t\nS\tSkyborne Druid\t\t\nA\t\t27\t\nS\tSkyborne Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid\t\t\nT\t\t27\t\nA\t\t28\t\nS\tSkyborne Druid\t\t\nI\t\tDive into Lake Elune'ara and take a Shrine Bauble from a Bauble Container.\nK\t\t15877\t1\t\t\nS\tSkyborne Druid\t\t\nI\t\tUse the bauble at the Shrine of Remulos for {q28}.\nU\t\t15877\t\nC\t\t28\t\t\nS\tSkyborne Druid\t\t\nT\t\t28\t\nA\t\t30\t\nS\tSkyborne Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tSkyborne Druid\t\t\nI\t\tFly to the Crossroads, then take the northern road to the Sludge Fen.\nF\t\tThe Crossroads\t\nS\tSkyborne Druid\t\t\nI\t\tDive into the fen pool and take the Half Pendant of Aquatic Agility from the Strange Lockbox.\nK\t\t15883\t1\t\t\nS\tSkyborne Druid\t\t\nG\t\tDurotar\t50.8\t13.6\t\t\t\nI\t\tFollow the road northeast into Orgrimmar, leave by its main gate and take the Tirisfal zeppelin. Enter Undercity by the main lifts.\nS\tSkyborne Druid\t\t\nG\t\tUndercity\t63.25\t48.56\t\t\t\nI\t\tTake the flight point.\nP\t\tUndercity\t\nS\tSkyborne Druid\t\t\nI\t\tFollow the western Tirisfal road into northern Silverpine Forest, avoiding Sons of Arugal, for the lockbox dive at the northern wreck.\nS\tSkyborne Druid\t\t\nI\t\tDive west of the wreck for the Half Pendant of Aquatic Endurance. Use the nearby air bubbles.\nK\t\t15882\t1\t\t\nS\tSkyborne Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid\t\t\nI\t\tCombine the two halves beside the Shrine of Remulos for {q30}.\nU\t\t15883\t\nC\t\t30\t\t\nS\tSkyborne Druid\t\t\nT\t\t30\t\nA\t\t31\t\nS\tSkyborne Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the flight to Thunder Bluff.\nS\tSkyborne Druid\t\t\nI\t\tTurn in {q31} and learn Aquatic Form from Turak Runetotem.\nT\t\t31\t\nS\t\t\t\nI\t\tEnter the Pools of Vision cave beneath Spirit Rise to reach Apothecary Zamah, then accept {q962}.\nA\t\t962\t\nS\t\t\t\nI\t\tRepair, restock and train chosen professions before the dungeon journey.\nV\t\tvendor\t\nS\t\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Heroic Strike III, Mocking Blow I and Shield Block.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Cure Poison, Lightning Shield II and Rockbiter Weapon III.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Immolation Trap I, Mongoose Bite I and Raptor Strike III.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Pick Lock, Feint I and Eviscerate III.\nV\t\ttrainer\t\nS\tRogue\t\t\nA\t\t2379\t\nS\tRogue\t\t\nT\t\t2379\t\nA\t\t2382\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t42.09\t49.48\t\t\t\nI\t\tBuy Thieves' Tools from Rekkul.\nV\t\tvendor\t\nS\t\t\t\nA\t\t5761\t\nS\t\t\tcompletewith=next\nI\t\tAccept an eligible share of {q5725} before the clear; keep its books for the next Undercity visit.\nA\t\t5725\t\nS\t\t\t\nI\t\tAt Ragefire Chasm's Cleft of Shadow entrance, join a five-player party with a tank and healer.\nS\tHunter/Warlock\t\t\nI\t\tTurn off pet taunts while another player tanks.\nS\t\t\t\nG\t\tOrgrimmar\t52.6\t49.0\t\t\t\nI\t\tEnter Ragefire Chasm with the party and complete one clear through Bazzalan and Jergosh.\nS\t\t\t\nI\t\tKill eight Ragefire Troggs and eight Ragefire Shaman during the clear for {q5723}.\nC\t\t5723\t\t\nS\t\t\t\nI\t\tFind Maur Grimtotem's corpse in the trogg section and search it. Turn in {q5722}, then accept {q5724}.\nT\t\t5722\t\nA\t\t5724\t\nS\t\t\t\nI\t\tDefeat Taragaman the Hungerer and take his heart for {q5761}.\nC\t\t5761\t\t\nS\t\t\t\nI\t\tDefeat Jergosh the Invoker and Bazzalan for {q5728}.\nC\t\t5728\t\t\nS\t\t\tcompletewith=next\nI\t\tIf the quest is active, collect Spells of Shadow and Incantations from the Nether for {q5725}.\nC\t\t5725\t\t\nS\t\t\t\nI\t\tLeave by the cleared entrance.\nS\t\t\t\nT\t\t5761\t\nS\t\t\t\nT\t\t5728\t\nA\t\t5729\t\nS\t\t\t\nT\t\t5729\t\nA\t\t5730\t\nS\t\t\t\nT\t\t5730\t\nS\t\t\t\nI\t\tFly to the Crossroads.\nF\t\tThe Crossroads\t\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: HEZRUL_BLOODMARK\nS\t\t\t\nI\t\tGuide migration: Defeat Hezrul Bloodmark and his bodyguards near the Lushwater Oasis for {q852}.\nC\t\t852\t\t\nS\t\t\t\nI\t\tGuide migration: Turn in {q852}, then accept {q4021}.\nT\t\t852\t\nA\t\t4021\t\nS\t\t\t\nI\t\t-- MIGRATION END: HEZRUL_BLOODMARK\nS\t\t\t\nT\t\t855\t\nS\t\t\t\nI\t\tReach level 17 before Krom'zar and Serena Bloodfeather.\nX\t\t\t17\t\t\t\nS\t\t\t\nI\t\tAt Regthar's camp, form a party for the Krom'zar defense before speaking to Regthar.\nS\t\t\t\nI\t\tSpeak to Regthar when the party is ready. Defend the camp, defeat Warlord Krom'zar and take the Piece of Krom'zar's Banner for {q4021}.\nC\t\t4021\t\t\nS\t\t\t\nT\t\t4021\t\nS\t\t\t\nI\t\tCollect six Harpy Lieutenant Rings from Witchwing Slayers in the inner camps for {q875}. Avoid Sister Rathtalon.\nC\t\t875\t\t\nS\t\t\t\nT\t\t875\t\nA\t\t876\t\nS\t\t\t\nI\t\tDefeat Serena Bloodfeather and take her head for {q876}.\nC\t\t876\t\t\nS\t\t\t\nI\t\tTurn in {q876}, then accept {q1060}; keep it for the later Stonetalon journey.\nT\t\t876\t\nA\t\t1060\t\nS\t\t\t\nA\t\t858\t\nS\t\t\t\nI\t\tDefeat Supervisor Lugwizzle and loot the Ignition Key for {q858}.\nC\t\t858\t\t\nS\t\t\t\nT\t\t858\t\nS\t\t\t\nA\t\t863\t\nS\t\t\t\nI\t\tEscort Wizzlecrank out of the fen and protect the shredder through its ambush for {q863}.\nC\t\t863\t\t\nS\t\t\t\nI\t\tFollow the road southeast to Ratchet.\nS\t\t\t\nT\t\t863\t\nS\t\t\t\nT\t\t865\t\nA\t\t1491\t\nS\t\t\t\nI\t\tReach level 18 before training and Northwatch Hold.\nX\t\t\t18\t\t\t\nS\t\t\tcompletewith=next\nI\t\tFly to Orgrimmar for training if needed.\nF\t\tOrgrimmar\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Disarm and Thunder Clap II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Flame Shock II, Flametongue Weapon II, Healing Wave IV, Stoneclaw Totem II and Tremor Totem.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Ambush I, Gouge II and Poised.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aspect of the Hawk II, Multi-Shot I, Serpent Sting III and Track Undead.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Great Stamina III and Natural Armor III. Open Beast Training and teach the usable ranks to your pet as its level and training points allow.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Entangling Roots II, Faerie Fire I, Hibernate I, Maul II, Nature's Grasp II and Regrowth II.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tFly to Ratchet.\nF\t\tRatchet\t\nS\tRogue\t\t\nT\t\t2382\t\nA\t\t2381\t\nS\tRogue\t\t\nG\t\tThe Barrens\t63.12\t36.32\t\t\t\nI\t\tUse Wrenix's Gizmotronic Apparatus to obtain E.C.A.C. and Thieves' Tools.\nS\tRogue\t\t\nG\t\tThe Barrens\t65.08\t45.42\t\t\t\nI\t\tBoard the pirate ship from its projecting bow and go one level below deck. Practice Pick Lock on the Buccaneer's Strongboxes until 80 Lockpicking.\nS\tRogue\t\t\nI\t\tOpen The Jewel of the Southsea in the lowest hold. Use E.C.A.C. on Polly, defeat the parrot and take the Southsea Treasure for {q2381}.\nU\t\t7970\t\nC\t\t2381\t\t\nS\t\t\t\nI\t\tDefeat Baron Longshore and his guards and take his head for {q895}.\nC\t\t895\t\t\nS\t\t\t\nI\t\tFollow the coastal approach south to Northwatch Hold and clear each tower staircase.\nS\t\t\t\nI\t\tCollect ten Theramore Medals and defeat Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe for {q891}.\nC\t\t891\t\t\nS\t\t\t\nI\t\tFind Gilthares in the hold after clearing the escort route and accept {q898}.\nA\t\t898\t\nS\t\t\t\nI\t\tEscort Gilthares to Ratchet through the road ambushes for {q898}.\nC\t\t898\t\t\nS\t\t\t\nT\t\t891\t\nT\t\t898\t\nS\tRogue\t\t\nT\t\t2381\t\nS\t\t\t\nT\t\t895\t\nS\t\t\t\nI\t\tKill a nearby Zhevra Charger for a Fresh Zhevra Carcass. Use it at the dead tree, defeat Ishamuhale and take his fang for {q882}.\nC\t\t882\t\t\nS\t\t\t\nI\t\tFollow the road west to the Crossroads, then the Gold Road south to Camp Taurajo.\nS\t\t\t\nT\t\t882\t\nA\t\t907\t\nS\t\t\t\nI\t\tCollect three Thunder Lizard Blood from level 18-19 Stormsnouts northeast of Camp Taurajo for {q907}.\nC\t\t907\t\t\nS\t\t\t\nT\t\t907\t\nA\t\t913\t\nS\t\t\t\nG\t\tThe Barrens\t46.76\t50.95\t\t\t\nI\t\tCollect a Thunderhawk Wing from an isolated level 18-19 Thunderhawk Hatchling for {q913}.\nC\t\t913\t\t\nS\t\t\t\nT\t\t913\t\nA\t\t874\t\nS\t\t\t\nI\t\tReach level 19 before leaving Camp Taurajo for Wailing Caverns. If short, hunt isolated level 18-19 Stormsnouts northeast of camp, then return.\nX\t\t\t19\t\t\t\nS\t\t\t\nI\t\tFly to the Crossroads for Wailing Caverns.\nF\t\tThe Crossroads\t\nS\t\t\t\nI\t\tRepair, restock and make bag space, then travel west to Wailing Caverns.\nV\t\tvendor\t\nS\t\t\t\nI\t\tUse the northern hillside and descend the outside ledges to Nalpak's cave above the entrance, then accept {q1486}.\nA\t\t1486\t\nS\t\t\t\nA\t\t1487\t\nS\t\t\t\nI\t\tAt the cavern mouth, join a five-player Wailing Caverns party with a tank and healer.\nS\t\t\t\nG\t\tThe Barrens\t46.0\t36.4\t\t\t\nI\t\tEnter the outer cavern with the party and find Mad Magglish before the instance portal.\nS\t\t\t\nI\t\tDefeat Mad Magglish and take the 99-Year-Old Port for {q959}.\nC\t\t959\t\t\nS\t\t\t\nI\t\tEnter Wailing Caverns and complete one clear through the four Fanglords and Mutanus.\nS\t\t\t\nI\t\tCollect twenty Deviate Hides during the clear for {q1486}.\nC\t\t1486\t\t\nS\t\t\t\nI\t\tKill seven each of Deviate Ravagers, Vipers, Shamblers and Dreadfangs during the clear for {q1487}.\nC\t\t1487\t\t\nS\t\t\t\nI\t\tGather ten Serpentbloom plants along the cleared passages for {q962}.\nC\t\t962\t\t\nS\t\t\t\nI\t\tCollect six Wailing Essence from the ectoplasm creatures for {q1491}.\nC\t\t1491\t\t\nS\t\t\t\nI\t\tLoot the Gems of Cobrahn, Anacondra, Pythas and Serpentis from the four Fanglords for {q914}.\nC\t\t914\t\t\nS\t\t\t\nI\t\tAfter all four Fanglords, return to the Disciple of Naralex near the entrance. Protect his ritual and defeat Mutanus.\nS\t\t\tcompletewith=next\nI\t\tIf you receive the Glowing Shard, use it to accept {q6981}.\nA\t\t6981\t\nS\t\t\t\nI\t\tLeave by the cleared entrance.\nS\t\t\t\nT\t\t1486\t\nS\t\t\t\nT\t\t1487\t\nS\t\t\t\nI\t\tReturn to Ratchet by road.\nS\t\t\t\nT\t\t1491\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t62.98\t37.22\t\t\t\nI\t\tIf carrying the shard, ask Sputtervalve about it for {q6981}.\nC\t\t6981\t\t\nS\t\t\t\nT\t\t959\t\nS\t\t\t\nT\t\t874\t\nS\t\t\t\nG\t\tThe Barrens\t48.18\t32.78\t\t\t\nT\t\t6981\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t48.18\t32.78\t\t\t\nA\t\t3369\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Crossroads if ready; otherwise follow the road west.\nH\t\tHearth to The Crossroads\nS\t\t\t\nI\t\tFly to Thunder Bluff for the dungeon rewards.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t962\t\nS\t\t\t\nT\t\t5724\t\nT\t\t5723\t\nS\t\t\t\nG\t\tThunder Bluff\t78.62\t28.56\t\t\t\nT\t\t3369\t\nS\t\t\t\nT\t\t914\t\nS\t\t\t\nI\t\tFly to Orgrimmar. Keep Letter to Jin'Zil and any Power to Destroy books.\nF\t\tOrgrimmar\t" },
  { name = "19-21 Silverpine Forest (Horde)", title = "19-21 Silverpine Forest", group = "Bethink's Guide 1-20", faction = "Horde", lo = 19, hi = 21, next = "21-24 Hillsbrad Foothills (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "The Sepulcher and Undercity, one Ruins of Lordaeron clear at 20, then Ambermill and Beren’s Peril. Ends at the Sepulcher.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 19. Keep Letter to Jin'Zil for the later Kalimdor return.\nX\t\t\t19\t\t\t\nS\t\t\t\nI\t\tLeave Orgrimmar for its zeppelin tower. Take the Tirisfal Glades zeppelin; confirm the destination before boarding. Enter Undercity by the main gates and lifts.\nS\t\t\t\nG\t\tUndercity\t63.25\t48.56\t\t\t\nI\t\tCollect Michael Garrett's flight point.\nP\t\tUndercity\t\nS\t\t\t\nA\t\t92421\t\nS\t\t\t\nG\t\tUndercity\t56.25\t92.2\t\t\t\nT\t\t5725\t\nS\t\t\t\nI\t\tAccept {q1013}; keep it for the upcoming Shadowfang Keep clear.\nA\t\t1013\t\nS\tOrc Warrior/Orc Hunter/Troll Warrior/Troll Hunter/Tauren Warrior/Tauren Hunter/Skyborne Warrior/Skyborne Hunter\t\tcompletewith=next\nG\t\tUndercity\t57.31\t32.77\t\t\t\nI\t\tAt Archibald, learn missing skills for weapons you plan to use: one- and two-handed Swords or Crossbows.\nV\t\ttrainer\t\nS\tOrc Rogue/Troll Rogue/Tauren Rogue/Skyborne Rogue\t\tcompletewith=next\nG\t\tUndercity\t57.31\t32.77\t\t\t\nI\t\tAt Archibald, learn missing skills for weapons you plan to use: one-handed Swords or Crossbows.\nV\t\ttrainer\t\nS\tOrc Mage/Orc Warlock/Troll Mage/Troll Warlock/Tauren Mage/Tauren Warlock/Skyborne Mage/Skyborne Warlock\t\tcompletewith=next\nG\t\tUndercity\t57.31\t32.77\t\t\t\nI\t\tAt Archibald, learn missing skills for weapons you plan to use: one-handed Swords.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tLeave Undercity by the main lifts and follow the eastern road to Deathguard Linnea.\nS\tOrc/Troll/Tauren/Skyborne\t\t\nA\t\t356\t\nS\tOrc/Troll/Tauren/Skyborne\t\t\nI\t\tKill eight Bleeding Horrors and eight Wandering Spirits around Balnir Farmstead for {q356}.\nC\t\t356\t\t\nS\tOrc/Troll/Tauren/Skyborne\t\t\nT\t\t356\t\nS\t\t\t\nA\t\t99156\t\nS\t\t\t\nI\t\tFind Riptear on his patrol near Venomweb Vale, defeat him and take his heart for {q99156}.\nC\t\t99156\t\t\nS\t\t\t\nT\t\t99156\t\nS\t\t\t\nA\t\t92422\t\nS\tMage\t\tcompletewith=next\nG\t\tTirisfal Glades\t59.4\t52.3\t\t\t\nI\t\tIf you have not delivered The Apothecary's Metaphysical Primer, take it from the shelf beside Apothecary Johaan in Brill's alchemy shop; keep it for Owen Thadd.\nK\t\t208185\t1\t\t\nS\t\t\t\nI\t\tFollow the road through Brill and west into Silverpine, then south to the Sepulcher. Avoid patrolling Sons of Arugal and remain on the road.\nS\t\t\t\nG\t\tSilverpine Forest\t45.62\t42.6\t\t\t\nI\t\tTake the flight point before entering the cemetery.\nP\t\tThe Sepulcher\t\nS\t\t\t\nG\t\tSilverpine Forest\t42.8\t40.86\t\t\t\nI\t\tTurn in {q445} if carrying Johaan's findings from Tirisfal Glades.\nT\t\t445\t\nS\t\t\t\nA\t\t447\t\nS\t\t\t\nG\t\tSilverpine Forest\t43.18\t41.28\t\t\t\nI\t\tBind with Bates; repair and restock.\nB\t\tSet your hearthstone to The Sepulcher\nS\tHunter\t\t\nG\t\tSilverpine Forest\t43.45\t41.18\t\t\t\nI\t\tStable your companion with Sarah Goode, keeping a free slot for the training tame.\nS\tHunter\t\t\nG\t\tSilverpine Forest\t45.92\t79.34\t\t\t\nI\t\tTake the southern road, staying clear of Sons of Arugal. Tame a Bloodsnout Worg; use Bite III in combat until the learning message appears.\nS\tHunter\t\t\nG\t\tSilverpine Forest\t43.45\t41.18\t\t\t\nI\t\tReturn to Sarah Goode, release the training tame and retrieve your companion. Open Beast Training and teach Bite III when its level and training points allow.\nS\t\t\t\nA\t\t437\t\nS\t\t\t\nA\t\t421\t\nS\t\t\t\nA\t\t477\t\nS\t\t\t\nA\t\t92401\t\nS\t\t\t\nI\t\tCollect six Grizzled Bear Hearts from bears and six samples of Skittering Blood from spiders around the Skittering Dark for {q447}.\nC\t\t447\t\t\nS\t\t\t\nI\t\tClear rot hide gnolls at the Dead Fields until Nightlash appears; defeat her and loot her essence for {q437}.\nC\t\t437\t\t\nS\t\t\t\nI\t\tKill five Moonrage Whitescalps on the northern farm approach for {q421}. Watch for Sons of Arugal and move away from their patrols.\nC\t\t421\t\t\nS\t\t\t\nI\t\tReturn south to the Sepulcher by road.\nS\t\t\t\nT\t\t421\t\nA\t\t422\t\nS\t\t\t\nT\t\t437\t\nA\t\t438\t\nS\t\t\t\nI\t\tRecover the Remedy of Arugal from the farmhouse chest for {q422}; clear its entrance before going upstairs.\nC\t\t422\t\t\nS\t\t\t\nI\t\tSearch the boat at the Decrepit Ferry, then turn in {q438}.\nT\t\t438\t\nS\t\t\t\nA\t\t439\t\nS\t\t\t\nI\t\tReturn to the Sepulcher.\nS\t\t\t\nT\t\t422\t\nA\t\t423\t\nS\t\t\t\nT\t\t439\t\nA\t\t440\t\nA\t\t443\t\nS\t\t\t\nI\t\tCollect six Glutton Shackles and three Darksoul Shackles from the western Moonrage camps for {q423}. Avoid the rare elites.\nC\t\t423\t\t\nS\t\t\t\nI\t\tCollect eight Rot Hide Ichor from the gnolls on the northeastern shore for {q443}, avoiding the Fenris keep for now.\nC\t\t443\t\t\nS\t\t\t\nT\t\t423\t\nA\t\t424\t\nS\t\t\t\nT\t\t443\t\nA\t\t444\t\nS\t\t\t\nI\t\tEnter Deep Elem Mine through its mouth for Grimson; keep the exit clear.\nS\t\t\t\nI\t\tClear to Grimson the Pale in the mine and loot his head for {q424}.\nC\t\t424\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise leave through the cleared entrance and follow the road.\nH\t\tHearth to The Sepulcher\nS\t\t\t\nT\t\t424\t\nA\t\t99\t\nS\t\t\t\nI\t\tFly to Undercity for training and deliveries.\nF\t\tUndercity\t\nS\t\t\t\nT\t\t447\t\nA\t\t450\t\nS\t\t\t\nT\t\t444\t\nA\t\t446\t\nS\t\t\t\nI\t\tReach level 20 before class training and Ruins of Lordaeron. If short, hunt isolated level 19-20 Ravenclaw undead outside Beren's Peril then return to Undercity.\nX\t\t\t20\t\t\t\nS\tWarrior/Hunter/Paladin/Druid\t\tcompletewith=next\nG\t\tUndercity\t57.31\t32.77\t\t\t\nI\t\tAt Archibald, learn Polearms if needed for a weapon you plan to use (1 gold before discounts).\nV\t\ttrainer\t\nS\tWarlock\t\t\nG\t\tUndercity\t86.21\t15.93\t\t\t\nI\t\tAt Kaal Soulreaper, learn Demon Armor, Shadow Bolt IV, Immolate III, Curse of the Elements I, Rain of Fire, Health Funnel II and Ritual of Summoning; learn Voidwalker Torment II. Buy and use the listed demon grimoires from Martha Strain nearby.\nV\t\ttrainer\t\nS\tWarlock\t\t\nI\t\tLeave Undercity by its main lifts and take the Orgrimmar zeppelin for Gan'rul Bloodeye in the Cleft of Shadow.\nS\tWarlock\t\t\nA\t\t1507\t\nS\tWarlock\t\t\nI\t\tTurn in {q1507} to Cazul, then accept {q1508}.\nT\t\t1507\t\nA\t\t1508\t\nS\tWarlock\t\t\nI\t\tTurn in {q1508} to Zankaja, then accept {q1509}.\nT\t\t1508\t\nA\t\t1509\t\nS\tWarlock\t\t\nI\t\tFly to the Crossroads.\nF\t\tThe Crossroads\t\nS\tWarlock\t\t\nI\t\tTurn in {q1509} to Gazrog, then accept {q1510}.\nT\t\t1509\t\nA\t\t1510\t\nS\tWarlock\t\t\nI\t\tFollow the western road into Stonetalon and visit Ken'zigla in Malaka'jin.\nS\tWarlock\t\t\nT\t\t1510\t\nA\t\t1511\t\nS\tWarlock\t\t\nI\t\tReturn to the Crossroads and fly to Camp Taurajo.\nF\t\tCamp Taurajo\t\nS\tWarlock\t\t\nI\t\tTurn in {q1511} to Grunt Logmar, then accept {q1515}.\nT\t\t1511\t\nA\t\t1515\t\nS\tWarlock\t\t\nI\t\tReach Dogran's quilboar camp north of Camp Taurajo; avoid the rare elite Swinegart Spearhide.\nS\tWarlock\t\t\nI\t\tClear the camp then turn in {q1515} to Grunt Dogran and accept {q1512}.\nT\t\t1515\t\nA\t\t1512\t\nS\tWarlock\t\t\nI\t\tReturn to Camp Taurajo and fly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nI\t\tTurn in {q1512} to Gan'rul, then accept {q1513}.\nT\t\t1512\t\nA\t\t1513\t\nS\tWarlock\t\t\nI\t\tUse Dogran's Pendant at the summoning circle in the Cleft of Shadow and subdue the Succubus for {q1513}.\nC\t\t1513\t\t\nS\tWarlock\t\t\nI\t\tTurn in {q1513} to learn Summon Succubus.\nT\t\t1513\t\nS\tWarlock\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise take the Tirisfal zeppelin and enter Undercity by its main lifts.\nH\t\tHearth to The Sepulcher\nS\tWarlock\t\tcompletewith=next\nI\t\tIf in the Sepulcher, fly to Undercity before continuing.\nS\tWarrior\t\t\nG\t\tUndercity\t47.4\t17.29\t\t\t\nI\t\tAt Baltus Fowler, learn Cleave I, Dual Wield, Rend III, Retaliation, Slam I and Victory Rush.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tTirisfal Glades\t60.9\t58.7\t\t\t\nI\t\tLeave Undercity by its main lifts and take the Orgrimmar zeppelin for Shaman training.\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Ghost Wolf, Totemic Recall, Call of the Elements, Frost Shock I, Frostbrand Weapon I, Lesser Healing Wave I, Lightning Bolt IV and Searing Totem II.\nV\t\ttrainer\t\nS\tShaman\t\t\nA\t\t1528\t\nS\tShaman\t\t\nI\t\tFly to Ratchet, then follow the coast south to Islen Waterseer.\nF\t\tRatchet\t\nS\tShaman\t\t\nT\t\t1528\t\nA\t\t1530\t\nS\tShaman\t\t\nI\t\tFollow the roads through the Crossroads and Camp Taurajo, take the hillside path to Brine's hut in the southern Barrens and turn in {q1530}, then accept {q1535}.\nT\t\t1530\t\nA\t\t1535\t\nS\tShaman\t\t\nI\t\tFill the brown waterskin in the watering hole below Brine's hut for {q1535}.\nU\t\t7766\t\nC\t\t1535\t\t\nS\tShaman\t\t\nT\t\t1535\t\nA\t\t1536\t\nS\tShaman\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise return to Camp Taurajo, fly to Orgrimmar, take the Tirisfal zeppelin and fly from Undercity to the Sepulcher.\nH\t\tHearth to The Sepulcher\nS\tShaman\t\t\nG\t\tSilverpine Forest\t45.62\t42.6\t\t\t\nI\t\tFollow the road south through Silverpine and east into Hillsbrad. Keep clear of Southshore and follow the northern road to Tarren Mill.\nS\tShaman\t\t\nI\t\tFill the red waterskin at Tarren Mill's well for {q1536}.\nU\t\t7768\t\nC\t\t1536\t\t\nS\tShaman\t\t\nG\t\tHillsbrad Foothills\t60.14\t18.62\t\t\t\nI\t\tTake the flight point.\nP\t\tTarren Mill\t\nS\tShaman\t\t\nI\t\tFly to Undercity.\nF\t\tUndercity\t\nS\tShaman\t\t\nI\t\tLeave by the main lifts and take the Orgrimmar zeppelin.\nS\tShaman\t\t\nI\t\tFly to Camp Taurajo and follow the southern road to Brine's hillside path.\nF\t\tCamp Taurajo\t\nS\tShaman\t\t\nT\t\t1536\t\nA\t\t1534\t\nS\tShaman\t\t\nI\t\tFollow the road north through the Crossroads and Mor'shan Rampart into Ashenvale. Fill the blue waterskin at the Ruins of Stardust for {q1534}, staying outside Astranaar.\nU\t\t7767\t\nC\t\t1534\t\t\nS\tShaman\t\t\nI\t\tReturn south along the same roads to Brine's hut. Turn in {q1534}, then accept {q220}.\nT\t\t1534\t\nA\t\t220\t\nS\tShaman\t\t\nI\t\tReturn by the road through the Crossroads and Ratchet to Islen Waterseer. Turn in {q220}, then accept {q63}.\nT\t\t220\t\nA\t\t63\t\nS\tShaman\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise return to Ratchet, fly to Orgrimmar, take the Tirisfal zeppelin and fly from Undercity to the Sepulcher.\nH\t\tHearth to The Sepulcher\nS\tShaman\t\t\nG\t\tSilverpine Forest\t45.62\t42.6\t\t\t\nI\t\tTake the western path down to the corrupted water shrine on the shore.\nS\tShaman\t\t\nG\t\tSilverpine Forest\t38.78\t44.26\t\t\t\nI\t\tReach the corrupted water shrine for the purification.\nS\tShaman\t\t\nI\t\tDrink the Water Sapta, defeat the level-22 Corrupt Minor Manifestation of Water and loot its bracers for {q63}.\nU\t\t6637\t\nC\t\t63\t\t\nS\tShaman\t\t\nI\t\tPlace the bracers and Remaining Drops of Purest Water at the Brazier of Everfount, then turn in {q63}.\nT\t\t63\t\nS\tShaman\t\t\nA\t\t100\t\nS\tShaman\t\t\nI\t\tTurn in {q100} to the friendly Minor Manifestation of Water that appears, then accept {q96}.\nT\t\t100\t\nA\t\t96\t\nS\tShaman\t\t\nI\t\tReturn to the Sepulcher and fly to Undercity.\nF\t\tUndercity\t\nS\tShaman\t\t\nI\t\tLeave by the main lifts and take the Orgrimmar zeppelin.\nS\tShaman\t\t\nI\t\tFly to Ratchet and follow the coast south.\nF\t\tRatchet\t\nS\tShaman\t\t\nI\t\tReturn to Islen, then turn in {q96}. Receive your Water Totem and learn Healing Stream Totem I; keep the totem in your bags.\nT\t\t96\t\nS\tShaman\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise return to Ratchet, fly to Orgrimmar and take the Tirisfal zeppelin into Undercity.\nH\t\tHearth to The Sepulcher\nS\tShaman\t\tcompletewith=next\nI\t\tIf in the Sepulcher, fly to Undercity before continuing.\nF\t\tUndercity\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Stealth II, Backstab III and Rupture I.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Fear Ward, Devouring Plague I, Flash Heal I, Holy Fire I, Inner Fire II, Mind Soothe I, Renew III, Shackle Undead I and Fade II.\nV\t\ttrainer\t\nS\tUndead Priest\t\t\nI\t\tAccept {q5679}, then turn in {q5679} and learn Dark Sacrifice from Aelthalyste.\nS\tTroll Priest\t\t\nA\t\t5643\t\nS\tTroll Priest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Hex of Weakness II.\nV\t\ttrainer\t\nS\tTroll Priest\t\t\nI\t\tLeave by the main lifts and take the Orgrimmar zeppelin for Shadowguard.\nS\tTroll Priest\t\t\nI\t\tTurn in {q5643} and learn Shadowguard from Ur'kyo.\nT\t\t5643\t\nS\tTroll Priest\t\tcompletewith=next\nI\t\tAccept {q5680} if Ur'kyo offers the lesson.\nA\t\t5680\t\nS\tTroll Priest\t\tcompletewith=next\nI\t\tTurn in {q5680} and learn Shadowguard.\nT\t\t5680\t\nS\tTroll Priest\t\t\nI\t\tTake the Tirisfal zeppelin back and return through the Undercity lifts before continuing.\nS\tUndead Priest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Touch of Weakness II.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Blessing of Kings, Consecration I, Flash of Light I, Exorcism I, Holy Strike III and Devotion Aura III.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t85.14\t10.03\t\t\t\nI\t\tAt Anastasia Hartwell, learn Blink, Evocation, Blizzard I, Mana Shield I, Frostbolt IV, Conjure Water III and Polymorph II.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t84.19\t15.58\t\t\t\nI\t\tAt Lexington Mortaim, learn Teleport: Undercity.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t82.78\t15.83\t\t\t\nI\t\tBuy Runes of Teleportation from Hannah Akeley.\nV\t\tvendor\t\nS\tMage\t\tcompletewith=next\nG\t\tUndercity\t73.19\t33.41\t\t\t\nI\t\tBring The Apothecary's Metaphysical Primer to Owen Thadd in the inner ring of the Magic Quarter, then accept {q79095}.\nA\t\t79095\t\nS\tMage\t\tcompletewith=next\nG\t\tUndercity\t73.19\t33.41\t\t\t\nI\t\tTurn in {q79095} with the book and learn Study.\nT\t\t79095\t\nS\tMage\t\tcompletewith=next\nG\t\tUndercity\t73.19\t33.41\t\t\t\nI\t\tUse Study in the library with a Light Feather. Open the Bundle of Scrolls; use Comprehend Scroll on eligible untranslated scrolls.\nS\tHunter\t\t\nI\t\tLeave Undercity by the main lifts and take the Orgrimmar zeppelin for Hunter training.\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aimed Shot I, Arcane Shot III, Aspect of the Cheetah, Disengage I, Distracting Shot II, Dual Wield, Freezing Trap I and Mend Pet II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Growl III. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\tHunter\t\t\nI\t\tTake the Tirisfal zeppelin back and return through the Undercity lifts before continuing.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tLeave Undercity by the main lifts, take the Orgrimmar zeppelin and fly to Thunder Bluff.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tAccept {q98340} from Turak Runetotem.\nA\t\t98340\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tCast Teleport: Moonglade.\nS\tSkyborne Druid/Tauren Druid\t\t\nT\t\t98340\t\nS\tSkyborne Druid\t\t\nA\t\t98341\t\nS\tTauren Druid\t\t\nA\t\t98405\t\nS\tSkyborne Druid\t\t\nI\t\tTurn in {q98341} to the Avatar of Saeyleenan.\nT\t\t98341\t\nS\tTauren Druid\t\t\nI\t\tTurn in {q98405} to the Great Cat Spirit.\nT\t\t98405\t\nS\tSkyborne Druid\t\t\nA\t\t98404\t\nS\tTauren Druid\t\t\nA\t\t98342\t\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tMoonglade\t71.7\t61.9\t\t\t\nI\t\tFollow the path to the Stormrage Barrow Den entrance. Use the Great Cat Spirit Statue for its temporary stealth blessing.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tFollow the den passages under the blessing and collect the Relic of the Fang.\nK\t\t280502\t1\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tContinue through the den passages for the Relic of the Claw. Renew the blessing at the entrance when needed.\nK\t\t280679\t1\t\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tCollect the Relic of the Silent Shadow from its separate chamber, then leave through the den entrance.\nK\t\t280680\t1\t\t\nS\tSkyborne Druid\t\t\nI\t\tRecover the three relics for {q98404}.\nC\t\t98404\t\t\nS\tTauren Druid\t\t\nI\t\tRecover the three relics for {q98342}.\nC\t\t98342\t\t\nS\tSkyborne Druid\t\t\nT\t\t98404\t\nS\tTauren Druid\t\t\nT\t\t98342\t\nS\tSkyborne Druid\t\t\nA\t\t98738\t\nS\tTauren Druid\t\t\nA\t\t98739\t\nS\tSkyborne Druid\t\t\nT\t\t98738\t\nS\tTauren Druid\t\t\nT\t\t98739\t\nS\tSkyborne Druid/Tauren Druid\t\t\nA\t\t98362\t\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the flight to Thunder Bluff.\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tTurn in {q98362} and learn Cat Form.\nT\t\t98362\t\nS\tSkyborne Druid/Tauren Druid\t\t\nG\t\tThunder Bluff\t76.48\t27.22\t\t\t\nI\t\tLearn Demoralizing Roar II, Shred I, Rebirth I, Mark of the Wild III, Healing Touch IV, Starfire I and Omen of Clarity.\nV\t\ttrainer\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tSkyborne Druid/Tauren Druid\t\t\nI\t\tBuy Maple Seeds from Hagrus at 45.99,45.68 for Rebirth, then take the Tirisfal zeppelin and return through the main lifts to Undercity.\nS\t\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise fly there.\nH\t\tHearth to The Sepulcher\nF\t\tThe Sepulcher\t\nS\t\t\t\nG\t\tSilverpine Forest\t47.41\t73.99\t\t\t\nI\t\tAt Pyrewood's approach, form a party for the shackles and Berard's journal.\nS\t\t\t\nI\t\tCollect six Pyrewood Shackles from the village with the party for {q99}. Clear buildings from their entrances and stop runners.\nC\t\t99\t\t\nS\t\t\t\nI\t\tClear the inn by its stairs and retrieve Berard's Journal from the bookshelf in the upstairs right-hand room for {q450}. Wait until everyone has collected the journal before leaving.\nC\t\t450\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise follow the cleared road north.\nH\t\tHearth to The Sepulcher\nS\t\t\t\nT\t\t450\t\nA\t\t451\t\nS\t\t\t\nT\t\t99\t\nS\t\t\t\nI\t\tSwim to the Dawning Isles east of Fenris Isle. Collect six Lake Creeper Moss and six Lake Skulker Moss from lake elementals, and a Hardened Tumor from Vile Fin murlocs, for {q451}. Stay outside Fenris Keep; the moss can take many kills.\nC\t\t451\t\t\nS\t\t\t\nI\t\tReturn to the Sepulcher along the lake's western shore.\nS\t\t\t\nI\t\tFly to Undercity for the plague delivery.\nF\t\tUndercity\t\nS\t\t\t\nT\t\t451\t\nS\t\t\t\nA\t\t95216\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tLeave through the main lifts and visit Brill before the dungeon.\nS\t\t\t\nT\t\t440\t\nA\t\t441\t\nS\t\t\t\nI\t\tRepair, restock and clear bags before traveling to the Ruins of Lordaeron entrance.\nV\t\tvendor\t\nS\t\t\t\nI\t\tAt the ruined capital's dungeon entrance, join a five-player party with a tank and healer for the Ruins of Lordaeron.\nS\t\t\t\nG\t\tTirisfal Glades\t63.4\t67.4\t\t\t\nI\t\tEnter the Ruins of Lordaeron beneath the ruined capital with the party. Complete one clear through Rath'mael.\nS\t\t\t\nI\t\tInvestigate Edward Heartweaver's corpse in the graveyard near Rath'mael for {q92401}.\nC\t\t92401\t\t\nS\t\t\t\nI\t\tCollect twenty-five Intact Limbs from the dungeon creatures for {q92421}.\nC\t\t92421\t\t\nS\t\t\t\nI\t\tDefeat Witherfang and loot the Highly Toxic Strain for {q95216}.\nC\t\t95216\t\t\nS\t\t\t\nI\t\tDefeat Rath'mael with the party for {q92422}.\nC\t\t92422\t\t\nS\t\t\tcompletewith=next\nI\t\tIf the Baron drops an Abominable Head for you, use it to accept {q97288}.\nA\t\t97288\t\nS\t\t\tcompletewith=next\nI\t\tIf you receive the Crest of Lordaeron, use it to accept {q95204}.\nA\t\t95204\t\nS\t\t\t\nI\t\tLeave through the cleared entrance.\nS\t\t\t\nT\t\t92422\t\nS\t\t\t\nI\t\tReturn through the Undercity lifts for ready deliveries.\nS\t\t\t\nG\t\tUndercity\t73.06\t32.85\t\t\t\nT\t\t95204\t\nS\t\t\t\nT\t\t441\t\nS\t\t\t\nT\t\t92421\t\nS\t\t\t\nT\t\t95216\t\nS\t\t\t\nG\t\tUndercity\t48.82\t69.28\t\t\t\nT\t\t97288\t\nS\t\t\tcompletewith=next\nG\t\tUndercity\t48.82\t69.28\t\t\t\nI\t\tAccept {q97289} if offered after your Unending Torment head delivery.\nA\t\t97289\t\nS\t\t\t\nG\t\tUndercity\t45.77\t61.95\t\t\t\nI\t\tBring the head to Othmar's body, then turn in {q97289}.\nT\t\t97289\t\nS\t\t\tcompletewith=next\nG\t\tUndercity\t45.77\t61.95\t\t\t\nA\t\t97290\t\nS\t\t\t\nG\t\tUndercity\t48.82\t69.28\t\t\t\nT\t\t97290\t\nS\t\t\tcompletewith=next\nG\t\tUndercity\t48.82\t69.28\t\t\t\nA\t\t97291\t\nS\t\t\t\nG\t\tUndercity\t75.2\t51.18\t\t\t\nI\t\tBuy one Essence of Agony from Ezekiel Graves in the Rogues' Quarter for {q97291}.\nC\t\t97291\t3\t\nS\t\t\t\nG\t\tUndercity\t65.19\t49.84\t\t\t\nI\t\tObtain the Toxic Skullcap from Tawny Grisette, who patrols the upper inner ring of the Trade Quarter, for {q97291}.\nC\t\t97291\t1\t\nS\t\t\t\nI\t\tCollect Blisterweed from the barrel behind the Herbalism trainers for {q97291}.\nC\t\t97291\t2\t\nS\t\t\t\nG\t\tUndercity\t48.82\t69.28\t\t\t\nT\t\t97291\t\nS\t\t\tcompletewith=next\nG\t\tUndercity\t48.82\t69.28\t\t\t\nA\t\t97292\t\nS\t\t\t\nG\t\tUndercity\t47.0\t60.0\t\t\t\nI\t\tGo upstairs above Othmar's body and use the Hissing Serum from your bags for {q97292}, then return to Faranell.\nC\t\t97292\t\t\nS\t\t\t\nG\t\tUndercity\t48.82\t69.28\t\t\t\nT\t\t97292\t\nS\t\t\t\nI\t\tFly to the Sepulcher.\nF\t\tThe Sepulcher\t\nS\t\t\t\nA\t\t516\t\nS\t\t\t\nT\t\t446\t\nA\t\t448\t\nA\t\t493\t\nS\t\t\t\nT\t\t448\t\nA\t\t442\t\nS\t\t\t\nT\t\t92401\t\nS\t\t\t\nI\t\tSearch the Dalaran crate south of Ambermill after clearing its guards, then turn in {q477}.\nT\t\t477\t\nS\t\t\t\nA\t\t478\t\nS\t\t\tcompletewith=next\nI\t\tHearth to the Sepulcher if ready; otherwise follow the cleared road north.\nH\t\tHearth to The Sepulcher\nS\t\t\t\nT\t\t478\t\nA\t\t481\t\nS\t\t\t\nT\t\t481\t\nA\t\t482\t\nS\t\t\t\nT\t\t482\t\nA\t\t479\t\nS\t\t\t\nG\t\tSilverpine Forest\t65.71\t23.67\t\t\t\nI\t\tAt the Fenris Isle shore, form a party for Thule Ravenclaw; cross to the keep together.\nS\t\t\t\nI\t\tCross to Fenris Isle together, enter the keep by its stairs and defeat Thule Ravenclaw and take his head for {q442}.\nC\t\t442\t\t\nS\t\t\t\nI\t\tLeave the lake by its southern shore and follow the road toward Ambermill.\nS\t\t\t\nI\t\tCollect eight Dalaran Pendants from the Ambermill outskirts for {q479}. Pull around corners into cleared ground.\nC\t\t479\t\t\nS\t\t\t\nG\t\tSilverpine Forest\t60.34\t74.01\t\t\t\nI\t\tKill six Ravenclaw Drudgers and six Guardians in Beren's Peril for {q516}; clear the cave entrance before advancing.\nC\t\t516\t\t\nS\t\t\t\nI\t\tReturn north by road to the Sepulcher.\nS\t\t\t\nT\t\t442\t\nS\t\t\t\nT\t\t516\t\nT\t\t479\t\nA\t\t480\t\nS\t\t\t\nI\t\tReturn to Ambermill, clear Ataeric's tower by the stairs and take his staff for {q480}.\nC\t\t480\t\t\nS\t\t\t\nT\t\t480\t\nS\t\t\t\nI\t\tReach level 21 before Hillsbrad. If short, hunt isolated level 20-21 Ravenclaw undead outside Beren's Peril, then return to the Sepulcher.\nX\t\t\t21\t\t\t\nS\t\t\t\nI\t\tKeep the Hillsbrad letter and Book of Ur; the next chapter begins at the Sepulcher." },
  { name = "21-24 Hillsbrad Foothills (Horde)", title = "21-24 Hillsbrad Foothills", group = "Bethink's Guide 20-40", faction = "Horde", lo = 21, hi = 24, next = "24-27 Ashenvale (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Tarren Mill and the western farms, Deadmines at 22 and Shadowfang Keep at 24. Ends in Orgrimmar for Ashenvale.",
    steps = "S\t\t\t\nI\t\tStart at the Sepulcher at 21 with Journey to Hillsbrad and The Book of Ur.\nX\t\t\t21\t\t\t\nS\tRogue\t\t\nI\t\tFly to Undercity.\nF\t\tUndercity\t\nS\tRogue\t\t\nI\t\tLeave by the main lifts and take the Orgrimmar zeppelin.\nS\tRogue\t\t\nA\t\t2460\t\nS\tRogue\t\t\nI\t\tWait for Shenthul's salute, then target him and /salute for {q2460}.\nC\t\t2460\t\t\nS\tRogue\t\t\nT\t\t2460\t\nA\t\t2458\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t42.09\t49.48\t\t\t\nI\t\tBuy Dust of Decay and Empty Vials from Rekkul for Instant Poison I; keep your Thieves' Tools ready.\nV\t\tvendor\t\nS\tRogue\t\t\nF\t\tCrossroads\t\nS\tRogue\t\t\nG\t\tThe Barrens\t55.44\t5.56\t\t\t\nI\t\tTravel north to the Sludge Fen tower. Fire the Flare Gun twice near Taskmaster Fizzule from a distance, then approach and /salute; wait for him to become friendly.\nU\t\t8051\t\nS\tRogue\t\t\nT\t\t2458\t\nA\t\t2478\t\nS\tRogue\t\t\nG\t\tThe Barrens\t54.8\t5.97\t\t\t\nI\t\tAt the tower approach, form a party for the tower clear.\nS\tRogue\t\t\nI\t\tUse Stealth and Pick Pocket on Foreman Silixiz before combat to obtain his tower key for {q2478}.\nC\t\t2478\t5\t\nS\tRogue\t\t\nI\t\tClear the tower with the party: defeat two Mutated Venture Co. Drones, two Venture Co. Lookouts and two Venture Co. Patrollers for {q2478}, {q2478}, and {q2478}.\nC\t\t2478\t1\t\nC\t\t2478\t2\t\nC\t\t2478\t3\t\nS\tRogue\t\t\nI\t\tDefeat Grand Foreman Puzik Gallywix upstairs and take his head for {q2478}.\nC\t\t2478\t4\t\nS\tRogue\t\t\nI\t\tUse Pick Lock on Gallywix's Lockbox upstairs and take the Cache of Zanzil's Altered Mixture for {q2478} before leaving.\nC\t\t2478\t6\t\nS\tRogue\t\t\nI\t\tReturn south by the road to the Crossroads and fly to Orgrimmar.\nS\tRogue\t\t\nI\t\tTurn in {q2478}. Keep Recipe: Thistle Tea; learn it when your Cooking allows.\nT\t\t2478\t\nS\tRogue\t\t\nA\t\t2479\t\nS\tRogue\t\t\nI\t\tTake the Tirisfal zeppelin, enter Undercity by the lifts and fly to the Sepulcher before continuing.\nS\t\t\t\nA\t\t1014\t\nS\t\t\t\nA\t\t1098\t\nS\t\t\t\nI\t\tTake the southern road into Hillsbrad. Stay north of Southshore and follow the road northeast to Tarren Mill.\nS\t\t\t\nA\t\t494\t\nS\t\t\t\nG\t\tHillsbrad Foothills\t60.14\t18.62\t\t\t\nI\t\tTake the flight point on arrival.\nP\t\tTarren Mill\t\nS\tRogue\t\t\nT\t\t2479\t\nA\t\t2480\t\nS\tRogue\t\t\nI\t\tWait beside Serge Hinott while he prepares the cure for {q2480}.\nC\t\t2480\t\t\nS\tRogue\t\t\nI\t\tTurn in {q2480} to learn Poisons, then use Hinott's Oil to remove the Touch of Zanzil.\nT\t\t2480\t\nS\tRogue\t\t\nI\t\tMake Instant Poison I with the ingredients bought in Orgrimmar and apply it to your weapons.\nS\t\t\t\nT\t\t493\t\nA\t\t496\t\nA\t\t501\t\nS\t\t\t\nT\t\t494\t\nA\t\t527\t\nS\t\t\t\nA\t\t549\t\nS\t\t\t\nA\t\t498\t\nS\t\t\t\nG\t\tHillsbrad Foothills\t62.78\t19.03\t\t\t\nI\t\tBind with Shay; repair and restock.\nB\t\tSet your hearthstone to Tarren Mill\nS\t\t\t\nI\t\tHunt on open ground north of the roads; avoid the Yeti cave and higher Alterac camps for now.\nS\t\t\t\nG\t\tHillsbrad Foothills\t64.05\t8.55\t\t\t\nI\t\tCollect ten Gray Bear Tongues and Creeper Ichor from isolated level 21-22 bears and Forest Moss Creepers for {q496}.\nC\t\t496\t\t\nS\t\t\t\nT\t\t496\t\nA\t\t499\t\nS\t\t\t\nI\t\tTurn in {q499} to Umpi beside Lydon with the Elixir of Suffering.\nT\t\t499\t\nS\t\t\t\nG\t\tHillsbrad Foothills\t75.33\t41.5\t\t\t\nI\t\tEnter Durnholde through its gate for the prisoner rescue.\nS\t\t\t\nI\t\tEnter Durnholde, defeat the jailors and take their keys and free Drull and Tog'thar at their separate ball-and-chain sites for {q498}.\nC\t\t498\t\t\nS\t\t\t\nI\t\tKill ten Syndicate Rogues and ten Watchmen in the farm camps north of Durnholde for {q549}.\nC\t\t549\t\t\nS\t\t\t\nI\t\tKill six Farmers, six Farmhands, Farmer Ray and Farmer Getz at Hillsbrad Fields for {q527}. Keep clear of Southshore and its road patrols.\nC\t\t527\t\t\nS\t\t\t\nI\t\tCollect ten Mountain Lion Blood from Starving Mountain Lions across the Hillsbrad fields for {q501}. Avoid Feral and Hulking Mountain Lions.\nC\t\t501\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready; otherwise take the road northeast.\nH\t\tHearth to Tarren Mill\nS\t\t\t\nT\t\t498\t\nS\t\t\t\nT\t\t549\t\nT\t\t527\t\nA\t\t528\t\nS\t\t\t\nA\t\t546\t\nS\t\t\tcompletewith=next\nI\t\tCollect thirty Hillsbrad Human Skulls from the Hillsbrad village and farm enemies.\nK\t\t3692\t30\t\t\nS\t\t\t\nT\t\t501\t\nA\t\t502\t\nS\t\t\t\nI\t\tFly to Undercity for training and the Stranglethorn zeppelin.\nF\t\tUndercity\t\nS\t\t\t\nI\t\tReach level 22 before class training and the dungeon trip. If short, fly to Tarren Mill and hunt isolated level 21-22 bears or lions, then return to Undercity.\nX\t\t\t22\t\t\t\nS\tWarlock\t\t\nG\t\tUndercity\t86.21\t15.93\t\t\t\nI\t\tAt Kaal Soulreaper, learn Drain Life II, Create Healthstone II, Curse of Weakness III and Eye of Kilrogg.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tUndercity\t47.4\t17.29\t\t\t\nI\t\tAt Baltus Fowler, learn Battle Shout III, Intimidating Shout and Sunder Armor II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tTirisfal Glades\t60.9\t58.7\t\t\t\nI\t\tLeave Undercity by its main lifts and take the Orgrimmar zeppelin for Shaman training.\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Cure Disease, Fire Nova II, Poison Cleansing Totem, Totemic Call and Water Breathing. Keep a few Shiny Fish Scales for Water Breathing.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Vanish I, Distract, Garrote II and Sinister Strike IV. Keep Flash Powder for Vanish.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Crippling Poison I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t75.2\t51.18\t\t\t\nI\t\tBuy ingredients and Flash Powder from Ezekiel Graves.\nV\t\tvendor\t\nS\tPriest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Heal II, Mind Blast III, Resurrection II and Smite IV.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Concentration Aura, Holy Light IV, Seal of Justice, Blessing of Might III and Seal of the Crusader III.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t85.14\t10.03\t\t\t\nI\t\tAt Anastasia Hartwell, learn Conjure Food III, Fire Blast III, Frost Ward I and Scorch I.\nV\t\ttrainer\t\nS\tHunter\t\t\nI\t\tLeave Undercity by the main lifts and take the Orgrimmar zeppelin for Hunter training.\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Hunter's Mark II and Scorpid Sting I.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Moonfire IV, Rejuvenation IV, Soothe Animal I and Wrath IV.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tDruid\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\tShaman/Hunter/Druid\t\t\nG\t\tDurotar\t50.8\t13.6\t\t\t\nI\t\tTake the Grom'gol zeppelin outside Orgrimmar.\nS\t\t\tcompletewith=next\nI\t\tIf not already in Grom'gol, leave Undercity by the main lifts and take the Grom'gol zeppelin.\nS\t\t\t\nI\t\tFollow the main road north from Grom'gol toward Duskwood; avoid enemy camps and towns.\nS\t\t\t\nI\t\tCross into Duskwood on its main road, turn west toward the Westfall bridge, then take the Westfall road south to Moonbrook. Bypass Sentinel Hill and Alliance patrols.\nS\t\t\t\nG\t\tWestfall\t42.55\t71.53\t\t\t\nI\t\tAt Moonbrook's mine entrance, join a five-player Deadmines party with a tank and healer. Follow the main tunnels to the instance portal.\nS\t\t\t\nI\t\tContinue through the forge and foundry, defeat the ship's bosses and VanCleef, then leave by the rear exit.\nS\t\t\tcompletewith=next\nG\t\tUndercity\t63.25\t48.56\t\t\t\nI\t\tHearth to Tarren Mill if ready; otherwise return by road to Grom'gol, take the Tirisfal zeppelin, enter Undercity and fly to Tarren Mill.\nH\t\tHearth to Tarren Mill\nF\t\tTarren Mill\t\nS\t\t\t\nI\t\tKill fifteen Hillsbrad Peasants in the village for {q528}.\nC\t\t528\t\t\nS\t\t\t\nI\t\tFeed the Elixir of Pain to Stanley at the northern farm, then turn in {q502}; be ready to defeat the transformed dog.\nT\t\t502\t\nS\t\t\t\nI\t\tReturn northeast to Tarren Mill.\nS\t\t\t\nT\t\t528\t\nA\t\t529\t\nS\t\t\t\nI\t\tReach level 23 before the blacksmith clear. If short, hunt isolated level 22-23 lions on open ground.\nX\t\t\t23\t\t\t\nS\t\t\t\nI\t\tClear the blacksmith building; kill Verringtan and four Apprentices, then recover the Shipment of Iron for {q529}.\nC\t\t529\t\t\nS\t\t\t\nI\t\tFinish collecting thirty Hillsbrad Human Skulls from the village and farm enemies for {q546}.\nC\t\t546\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready; otherwise return by the northern road.\nH\t\tHearth to Tarren Mill\nS\t\t\t\nI\t\tTurn in {q529}, then accept {q532}; keep the town hall assault for the return at 29.\nT\t\t529\t\nA\t\t532\t\nS\t\t\t\nT\t\t546\t\nS\t\t\t\nI\t\tReach level 24 before Shadowfang Keep. If short, hunt isolated level 23-24 wildlife outside the Hillsbrad farms.\nX\t\t\t24\t\t\t\nS\tHunter\t\t\nG\t\tHillsbrad Foothills\t62.31\t19.7\t\t\t\nI\t\tStable your companion with Theodore Mont Claire, keeping a free slot for the training tame.\nS\tHunter\t\t\nG\t\tHillsbrad Foothills\t90.16\t41.38\t\t\t\nI\t\tTake the eastern road to the woods outside Durnholde; stay outside the keep. Tame a level-24 Giant Moss Creeper; use Bite IV in combat until the learning message appears.\nS\tHunter\t\t\nG\t\tHillsbrad Foothills\t62.31\t19.7\t\t\t\nI\t\tReturn to Theodore Mont Claire, release the training tame and retrieve your companion. Open Beast Training and teach Bite IV when its level and training points allow.\nS\t\t\t\nI\t\tFly to the Sepulcher, then travel south by road.\nF\t\tThe Sepulcher\t\nS\t\t\t\nI\t\tRepair and clear bags at the Sepulcher before leaving.\nV\t\tvendor\t\nS\t\t\t\nG\t\tSilverpine Forest\t44.8\t67.8\t\t\t\nI\t\tTake the uphill path above Pyrewood to Shadowfang Keep's entrance. Join a five-player party with a tank and healer, then enter together.\nS\t\t\t\nI\t\tComplete one clear through Arugal. Speak to Deathstalker Adamant in the courtyard and use his dialogue to open the way.\nS\t\t\t\nI\t\tFind Deathstalker Adamant and Deathstalker Vincent during the courtyard section; turn in {q1098} to Vincent.\nT\t\t1098\t\nS\t\t\t\nI\t\tRecover The Book of Ur from the bookshelf in the room with Fenrus for {q1013}. Clear the room before searching.\nC\t\t1013\t\t\nS\t\t\t\nI\t\tDefeat Arugal and loot his head for {q1014}. Use line of sight during his teleports.\nC\t\t1014\t\t\nS\t\t\t\nI\t\tLeave through the cleared entrance; return north to the Sepulcher.\nS\t\t\t\nT\t\t1014\t\nS\t\t\t\nI\t\tFly to Undercity for the book delivery and training.\nF\t\tUndercity\t\nS\t\t\t\nT\t\t1013\t\nS\tWarlock\t\t\nG\t\tUndercity\t86.21\t15.93\t\t\t\nI\t\tAt Kaal Soulreaper, learn Corruption III, Drain Soul II, Drain Mana and Sense Demons; learn Shadowburn when talented. Learn Imp Fire Shield II and Voidwalker Sacrifice II / Suffering I. Buy and use the listed demon grimoires from Martha Strain nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tUndercity\t47.4\t17.29\t\t\t\nI\t\tAt Baltus Fowler, learn Demoralizing Shout II, Execute I, Heroic Strike IV and Revenge II.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Detect Traps, Eviscerate IV and Shank I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Mind-numbing Poison I (100 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Holy Fire II, Mana Burn I, Power Word: Fortitude III and Power Word: Shield IV.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Hammer of Justice II, Blessing of Protection II, Blessing of Wisdom II, Redemption II and Turn Undead I.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t85.14\t10.03\t\t\t\nI\t\tAt Anastasia Hartwell, learn Counterspell, Fireball V, Arcane Missiles III and Flamestrike II.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tTake the Orgrimmar zeppelin from the tower outside Undercity. Enter Orgrimmar through the main gate.\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Ancestral Spirit II, Earth Shock IV, Frost Resistance Totem I, Healing Wave V, Lightning Shield III, Rockbiter Weapon IV, Stoneskin Totem III and Strength of Earth Totem II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Beast Lore, Raptor Strike IV and Track Hidden.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Great Stamina IV, Natural Armor IV. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tAccept {q95697} from Borstan for the Excavation Site clear at 29.\nA\t\t95697\t\nS\t\t\t\nI\t\tRepair, restock and train chosen professions. Keep Battle of Hillsbrad and Letter to Jin'Zil for their later circuits.\nV\t\tvendor\t" },
  { name = "24-27 Ashenvale (Horde)", title = "24-27 Ashenvale", group = "Bethink's Guide 20-40", faction = "Horde", lo = 24, hi = 27, next = "27-29 Thousand Needles (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Stonetalon preparation, Zoram Strand and Splintertree, Blackfathom Deeps at 26 and the Ashenvale Hunt. Ends in Thunder Bluff.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 24 with Letter to Jin'Zil and Changing Tastes. Keep Changing Tastes for later.\nX\t\t\t24\t\t\t\nS\t\t\t\nI\t\tFly to Thunder Bluff for the Sacred Flame preparation.\nF\t\tThunder Bluff\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Ferocious Bite I, Rake I, Regrowth III, Remove Curse, Revive II, Swipe II and Thorns III.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nA\t\t1195\t\nS\t\t\t\nI\t\tFly to the Crossroads, then take the western road into Stonetalon.\nF\t\tThe Crossroads\t\nS\t\t\t\nT\t\t1060\t\nS\t\t\t\nI\t\tFollow the canyon road northwest to Sun Rock Retreat, keeping clear of the Venture Co. logging camp.\nS\t\t\t\nA\t\t6562\t\nA\t\t6393\t\nS\t\t\t\nG\t\tStonetalon Mountains\t47.47\t62.13\t\t\t\nI\t\tBind with Jayka for the Charred Vale returns.\nB\t\tSet your hearthstone to Sun Rock Retreat\nS\t\t\t\nA\t\t6282\t\nS\t\t\t\nG\t\tStonetalon Mountains\t45.12\t59.84\t\t\t\nI\t\tTake the flight point.\nP\t\tSun Rock Retreat\t\nS\t\t\t\nA\t\t6301\t\nS\t\t\tcompletewith=next\nG\t\tStonetalon Mountains\t49.18\t57.18\t\t\t\nI\t\tClimb the path east-northeast of Sun Rock Retreat's largest tent to Hgarth. Learn Expert Enchanting (level 20, 125 Enchanting); skip if not ready.\nS\t\t\t\nI\t\tFollow the northern road to Stonetalon Peak's outer grove, staying outside the Alliance outpost.\nS\t\t\t\nI\t\tGather ten Gaea Seeds along the northern woodland road for {q6301}.\nC\t\t6301\t\t\nS\t\t\t\nI\t\tReturn south by road to Sun Rock Retreat.\nS\t\t\t\nT\t\t6301\t\nA\t\t6381\t\nS\t\t\t\nI\t\tAt the Charred Vale's canyon entrance south of Sun Rock, clear each ridge before advancing for the harpies, seeds and Incendrites.\nS\t\t\t\nI\t\tKill seven Bloodfury Harpies, seven Roguefeathers, seven Slayers and seven Ambushers for {q6282}.\nC\t\t6282\t\t\nS\t\t\t\nI\t\tUse the Enchanted Gaea Seeds on ten Gaea Dirt Mounds in the cleared Charred Vale for {q6381}; keep the remaining seeds for Tammra.\nC\t\t6381\t\t\nS\t\t\t\nI\t\tCollect the requested Incendrites from the fire elementals in the Charred Vale for {q6393}.\nC\t\t6393\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Sun Rock Retreat if ready; otherwise return by the canyon path.\nH\t\tHearth to Sun Rock Retreat\nS\t\t\t\nI\t\tTake the uphill path to Tsunaman above the inn, then turn in {q6393}.\nT\t\t6393\t\nS\t\t\t\nT\t\t6282\t\nA\t\t6283\t\nS\t\t\t\nT\t\t6381\t\nS\t\t\t\nG\t\tStonetalon Mountains\t30.75\t61.91\t\t\t\nI\t\tAt the Charred Vale approach, form a party for the Bloodfury Ripper.\nS\t\t\t\nG\t\tStonetalon Mountains\t30.75\t61.91\t\t\t\nI\t\tReturn with the party, clear to the Bloodfury Ripper on her high ledge and take her remains for {q6283}. Use the ridge path instead of climbing the cliff.\nC\t\t6283\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Sun Rock Retreat if ready; otherwise return by the canyon path.\nH\t\tHearth to Sun Rock Retreat\nS\t\t\t\nT\t\t6283\t\nS\t\t\t\nI\t\tFollow the road southeast toward Windshear Crag, then take Talondeep Path through the mountains into Ashenvale. Turn west, bypass Astranaar and follow the road to Zoram Strand.\nS\t\t\t\nG\t\tAshenvale\t12.24\t33.8\t\t\t\nI\t\tTake the flight point before visiting the outpost.\nP\t\tZoram'gar Outpost\t\nS\t\t\t\nT\t\t6562\t\nS\t\t\t\nI\t\tReach level 25 before the Zoram Strand quests. If short, return through Talondeep Path to hunt isolated level 24-25 harpies on the cleared Charred Vale approaches, then return to Zoram'gar.\nX\t\t\t25\t\t\t\nS\t\t\t\nA\t\t6563\t\nA\t\t6921\t\nS\t\t\t\nA\t\t6462\t\nS\t\t\t\nA\t\t6442\t\nS\t\t\t\nA\t\t216\t\nS\t\t\t\nG\t\tAshenvale\t12.06\t34.63\t\t\t\nI\t\tAt Muglash, form a party for Vorsha's waves before starting the escort.\nS\t\t\t\nI\t\tHave everyone confirm they're ready before speaking to Muglash and accepting {q6641}.\nA\t\t6641\t\nS\t\t\t\nI\t\tEscort Muglash to the brazier, extinguish it when instructed and defend him through the naga waves and Vorsha for {q6641}. Stay with the party. Collect Wrathtail Heads along the way.\nC\t\t6641\t\t\nS\t\t\t\nG\t\tAshenvale\t6.62\t16.17\t\t\t\nI\t\tFinish collecting twenty Wrathtail Heads from the naga on Zoram Strand for {q6442}. Pull to cleared sand and avoid underwater packs.\nC\t\t6442\t\t\nS\t\t\t\nG\t\tAshenvale\t14.5\t14.2\t\t\t\nI\t\tTravel north along Zoram Strand to the ruins entrance. Form a party for the Sapphires of Aku'mai and Damp Note in the outer cave.\nS\t\t\tcompletewith=next\nI\t\tWhile The Essence of Aku'mai is active, use a personally looted Damp Note from a Blackfathom Tide Priestess as soon as obtained to accept {q6564}.\nU\t\t16790\t\nA\t\t6564\t\nS\t\t\t\nI\t\tWith the party, collect twenty Sapphires of Aku'mai from wall crystals in the outer cave for {q6563}, watching for the Damp Note during the same outing.\nC\t\t6563\t\t\nS\t\t\t\nI\t\tLeave the outer cave by its entrance and return south to Zoram'gar for the ready turn-ins.\nS\t\t\t\nT\t\t6442\t\nS\t\t\t\nT\t\t6641\t\nS\t\t\t\nT\t\t6563\t\nS\t\t\t\nT\t\t6564\t\nS\t\t\tcompletewith=next\nI\t\tAccept {q6565}; keep the Lorgus Jett assignment for the later dungeon clear.\nA\t\t6565\t\nS\t\t\t\nI\t\tTravel east around Astranaar to Thistlefur Village. Clear the approach and enter the cave by its mouth.\nS\t\t\t\nI\t\tKill eight Thistlefur Avengers and eight Shaman at the village and cave for {q216}.\nC\t\t216\t\t\nS\t\t\t\nI\t\tCollect eight Troll Charms from baskets inside the cleared Thistlefur cave for {q6462}.\nC\t\t6462\t\t\nS\t\t\t\nI\t\tFind Ruul in his cage after clearing the surrounding cave and accept {q6482}.\nA\t\t6482\t\nS\t\t\t\nI\t\tEscort Ruul out of Thistlefur and protect him through the ambushes for {q6482}.\nC\t\t6482\t\t\nS\t\t\t\nI\t\tFollow the main road east to Splintertree Post; avoid the Warsong Lumber Camp for now.\nS\t\t\t\nG\t\tAshenvale\t73.18\t61.59\t\t\t\nI\t\tTake the flight point.\nP\t\tSplintertree Post\t\nS\t\t\t\nA\t\t6503\t\nS\t\t\t\nA\t\t6383\t\nT\t\t6383\t\nS\t\t\t\nT\t\t6482\t\nS\t\t\t\nA\t\t25\t\nS\t\t\t\nA\t\t6441\t\nS\t\t\t\nI\t\tKill nine hidden Ashenvale Outrunners south of Splintertree for {q6503}. Advance slowly on open ground.\nC\t\t6503\t\t\nS\t\t\t\nI\t\tReach Torek and speak with him to begin the assault.\nS\t\t\t\nA\t\t6544\t\nS\t\t\t\nI\t\tEscort Torek through the Silverwing assault and defeat Duriel Moonfire for {q6544}. Stay with Torek until the assault completes.\nC\t\t6544\t\t\nS\t\t\t\nI\t\tAt the moonwell south of Mystral Lake, use the Etched Phial to fill it for {q1195}. Clear its guardians.\nC\t\t1195\t\t\nS\t\t\t\nI\t\tKill twelve Befouled Water Elementals around Mystral Lake and stand beneath the island gazebo's light beam to scout it for {q25}. Loot a Befouled Water Globe from Tideress if encountered.\nC\t\t25\t\t\nS\t\t\tcompletewith=next\nI\t\tUse a personally looted Befouled Water Globe to accept {q1918}; keep its delivery for Mastok.\nU\t\t16408\t\nA\t\t1918\t\nS\t\t\t\nI\t\tReturn to Splintertree by road.\nS\t\t\t\nT\t\t6503\t\nS\t\t\t\nT\t\t6544\t\nS\t\t\t\nT\t\t25\t\nS\t\t\t\nG\t\tAshenvale\t73.67\t60.0\t\t\t\nT\t\t1918\t\nS\t\t\tcompletewith=next\nG\t\tAshenvale\t73.67\t60.0\t\t\t\nA\t\t824\t\nS\t\t\t\nI\t\tCollect sixteen Satyr Horns at Satyrnaar for {q6441}. Pull casters into cleared ground and stop runners.\nC\t\t6441\t\t\nS\t\t\t\nI\t\tReturn to Splintertree.\nS\t\t\t\nT\t\t6441\t\nS\t\t\t\nI\t\tReach level 26 before Blackfathom Deeps. If short, hunt isolated level 25-26 satyrs on the cleared camp edges.\nX\t\t\t26\t\t\t\nS\t\t\t\nI\t\tFly to Orgrimmar for training.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Life Tap III, Searing Pain II, Curse of Tongues and Detect Invisibility I; learn Imp Blood Pact III and Voidwalker Consume Shadows II. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Challenging Shout, Charge II and Mocking Blow II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Far Sight, Flametongue Weapon III, Lightning Bolt V, Magma Totem I and Mana Spring Totem I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Cheap Shot, Kick II, Ambush II and Expose Armor II.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Flash Heal II, Renew IV and Shadow Word: Pain IV.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tFly to Thunder Bluff for Paladin training.\nF\t\tThunder Bluff\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Seal of Fury III, Seal of Righteousness IV, Flash of Light II and Retribution Aura II.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Cone of Cold I, Frost Nova II and Frostbolt V.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.68\t85.41\t\t\t\nI\t\tAt Thuul, learn Teleport: Orgrimmar.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t45.43\t56.55\t\t\t\nI\t\tBuy Runes of Teleportation from Horthus.\nV\t\tvendor\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Immolation Trap II, Rapid Fire, Serpent Sting IV and Track Elementals.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Abolish Poison, Dash I, Healing Touch V, Maul III and Starfire II.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tFly to Zoram'gar.\nF\t\tZoram'gar Outpost\t\nS\t\t\t\nT\t\t216\t\nA\t\t6621\t\nS\t\t\t\nT\t\t6462\t\nS\t\t\t\nG\t\tAshenvale\t11.56\t34.29\t\t\t\nT\t\t824\t\nS\t\t\t\nI\t\tRestock and prepare for the underwater approach.\nV\t\tvendor\t\nS\tWarlock\t\t\nI\t\tUse Unending Breath for the flooded passages.\nS\t\t\t\nG\t\tAshenvale\t14.5\t14.2\t\t\t\nI\t\tReturn to the ruins entrance and join a five-player Blackfathom Deeps party with a tank and healer. Follow the flooded cave approach together and complete one clear through Aku'mai.\nS\t\t\t\nI\t\tAfter the turtle room, reach Argent Guard Thaelrid on the side island and accept {q6561} directly from him before proceeding toward Kelris.\nA\t\t6561\t\nS\t\t\t\nI\t\tClear around the underwater Fathom Stone beneath the Moonshrine Ruins walkway, then loot the Fathom Core for {q6921}; this summons Baron Aquanis.\nC\t\t6921\t\t\nS\t\t\t\nI\t\tDefeat Baron Aquanis with the party, loot his Strange Water Globe and use it to accept {q6922}.\nU\t\t16782\t\nA\t\t6922\t\nS\t\t\tcompletewith=next\nI\t\tDefeat Lorgus Jett with the party when Allegiance to the Old Gods is active for {q6565}.\nC\t\t6565\t\t\nS\t\t\t\nI\t\tDefeat Twilight Lord Kelris and loot his head for {q6561}.\nC\t\t6561\t\t\nS\t\t\t\nI\t\tDefeat Old Serra'kis during the underwater sweep. After Kelris, activate one brazier at a time, defeat each wave and recover before the next. Defeat Aku'mai beyond the door and avoid the poison clouds.\nS\t\t\t\nI\t\tLeave by the cleared passages; return south to Zoram'gar.\nS\t\t\t\nT\t\t6921\t\nT\t\t6922\t\nS\t\t\t\nG\t\tAshenvale\t11.56\t34.29\t\t\t\nT\t\t6565\t\nS\t\t\t\nI\t\tClear each named beast's surroundings before the pull.\nS\t\t\t\nG\t\tAshenvale\t39.76\t65.21\t\t\t\nI\t\tDefeat Ursangous loot his paw and use it to accept {q23}.\nA\t\t23\t\nS\t\t\t\nG\t\tAshenvale\t56.5\t63.5\t\t\t\nI\t\tReach the Foulweald Totem Mound and form a party for the banner defense.\nS\t\t\t\nI\t\tTravel to the Foulweald Totem Mound with the party. Place Karang's Banner, protect it through the waves, then defeat Chief Murgut and take his totem for {q6621}.\nC\t\t6621\t\t\nS\t\t\t\nG\t\tAshenvale\t57.5\t56.05\t\t\t\nI\t\tDefeat Shadumbra, loot her head and use it to accept {q24}.\nA\t\t24\t\nS\t\t\t\nG\t\tAshenvale\t74.98\t70.06\t\t\t\nI\t\tDefeat Sharptalon, loot his claw and use it to accept {q2}.\nA\t\t2\t\nS\t\t\t\nI\t\tReturn to Splintertree.\nS\t\t\t\nT\t\t23\t\nT\t\t24\t\nT\t\t2\t\nA\t\t247\t\nS\t\t\t\nT\t\t247\t\nS\t\t\t\nI\t\tFly to Zoram'gar for the Foulweald reward.\nF\t\tZoram'gar Outpost\t\nS\t\t\t\nT\t\t6621\t\nS\t\t\t\nI\t\tFly to Thunder Bluff for the dungeon and Sacred Flame deliveries.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t6561\t\nS\t\t\t\nT\t\t1195\t\nS\t\t\t\nI\t\tReach level 27 before the Thousand Needles journey. If short, fly back to Ashenvale and hunt isolated level 26-27 wildlife outside the cleared Foulweald camps, then return to Thunder Bluff.\nX\t\t\t27\t\t\t\nS\t\t\t\nA\t\t1196\t\nS\t\t\t\nA\t\t1131\t\nS\t\t\t\nI\t\tKeep the Filled Etched Phial, Steelsnap, Changing Tastes and Battle of Hillsbrad for the next circuits." },
  { name = "27-29 Thousand Needles (Horde)", title = "27-29 Thousand Needles", group = "Bethink's Guide 20-40", faction = "Horde", lo = 27, hi = 29, next = "29-31 Hillsbrad Foothills (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Southern Barrens, Freewind Post and the canyon plateaus. Ends in Orgrimmar for the Eastern Kingdoms return.",
    steps = "S\t\t\t\nI\t\tStart in Thunder Bluff at 27, carrying the Sacred Flame phial and Steelsnap.\nX\t\t\t27\t\t\t\nS\t\t\t\nI\t\tFly to Camp Taurajo.\nF\t\tCamp Taurajo\t\nS\t\t\t\nA\t\t893\t\nS\t\t\t\nA\t\t843\t\nS\t\t\t\nI\t\tKill fifteen Bael'dun Excavators and five Foremen at the dig, then take Khazgorm's Journal for {q843}.\nC\t\t843\t\t\nS\t\t\t\nT\t\t843\t\nA\t\t846\t\nS\t\t\t\nI\t\tClear the upper Bael Modan compound; collect six each of Nitroglycerin, Wood Pulp and Sodium Nitrate for {q846}.\nC\t\t846\t\t\nS\t\t\t\nT\t\t846\t\nA\t\t849\t\nS\t\t\t\nI\t\tReturn to the cleared flying machine and use Gann's Explosive to destroy it for {q849}.\nC\t\t849\t\t\nS\t\t\t\nT\t\t849\t\nS\t\t\t\nI\t\tCollect a Razormane Backstabber, Charred Razormane Wand and Razormane War Shield from the southern Razormane camps for {q893}.\nC\t\t893\t\t\nS\t\t\t\nI\t\tReturn to Camp Taurajo by road.\nS\t\t\t\nT\t\t893\t\nA\t\t1153\t\nS\t\t\t\nI\t\tFollow the Gold Road south to the Great Lift. Ride the lift down; do not jump.\nS\t\t\t\nA\t\t4542\t\nS\t\t\t\nI\t\tFollow the canyon road to the base of Freewind Post; use its lifts to reach the mesa.\nS\t\t\t\nA\t\t4767\t\nS\t\t\t\nG\t\tThousand Needles\t45.14\t49.11\t\t\t\nI\t\tTake the flight point.\nP\t\tFreewind Post\t\nS\t\t\t\nA\t\t4821\t\nS\t\t\t\nT\t\t4542\t\nA\t\t4841\t\nS\t\t\t\nG\t\tThousand Needles\t46.07\t51.52\t\t\t\nI\t\tBind with Abeqwa for the canyon returns.\nB\t\tSet your hearthstone to Freewind Post\nS\t\t\t\nT\t\t1196\t\nA\t\t1197\t\nS\t\t\t\nA\t\t5147\t\nS\t\t\t\nI\t\tKill twelve Galak Scouts, ten Wranglers and six Windchasers in the camps below Freewind for {q4841}. Pull from their edges and stop runners.\nC\t\t4841\t\t\nS\t\t\t\nI\t\tCollect the Alien Egg from its guarded nest east of Freewind for {q4821}; clear its approach.\nC\t\t4821\t\t\nS\t\t\t\nI\t\tReturn using the Freewind lifts.\nS\t\t\t\nT\t\t4841\t\nA\t\t5064\t\nS\t\t\t\nT\t\t4821\t\nA\t\t4865\t\nS\t\t\t\nI\t\tTravel west along the canyon floor to Whitereach Post; avoid taking cliff shortcuts.\nS\t\t\t\nA\t\t5151\t\nS\t\t\t\nT\t\t4865\t\nA\t\t5062\t\nS\t\t\t\nI\t\tCollect an Unrefined Ore Sample from Gravelsnout Diggers or Surveyors in the western canyon for {q1153}.\nC\t\t1153\t\t\nS\t\t\t\nI\t\tClear Steelsnap and his hyena companions, then loot his rib for {q1131}.\nC\t\t1131\t\t\nS\t\t\t\nG\t\tThousand Needles\t22.76\t24.62\t\t\t\nI\t\tAt the Galak patrol route, form a party for the Messenger and escorts.\nS\t\t\t\nI\t\tWith the party, defeat the Galak Messenger and his escorts; recover the Hypercapacitor Gizmo and Panther Cage Key for {q5151}.\nC\t\t5151\t\t\nS\t\t\t\nG\t\tThousand Needles\t17.57\t42.25\t\t\t\nI\t\tFollow Highperch's path up to the eggs and Pao'ka.\nS\t\t\t\nI\t\tUse the Highperch path to reach the nests and gather ten Wyvern Eggs for {q4767}.\nC\t\t4767\t\t\nS\t\t\t\nI\t\tSpeak to Pao'ka Swiftmountain and accept {q4770}.\nA\t\t4770\t\nS\t\t\t\nI\t\tEscort Pao'ka down the Highperch path for {q4770}. Stay with him through the ambushes.\nC\t\t4770\t\t\nS\t\t\t\nT\t\t4770\t\nS\t\t\t\nT\t\t5151\t\nS\t\t\t\nI\t\tGather ten Incendia Agave from the canyon floor and lower slopes on the way east for {q5062}.\nC\t\t5062\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Freewind Post if ready; otherwise return by the canyon road and lifts.\nH\t\tHearth to Freewind Post\nS\t\t\t\nI\t\tFly to Thunder Bluff for the Sacred Fire and Steelsnap deliveries.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t1131\t\nS\t\t\t\nT\t\t5062\t\nS\t\t\t\nI\t\tReach level 28 before class training and Darkcloud Pinnacle. If short, fly to Freewind Post and hunt isolated level 27-28 canyon wildlife, then return to Thunder Bluff.\nX\t\t\t28\t\t\t\nS\t\t\t\nA\t\t5088\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Holy Strike IV, Exorcism II and Shadow Resistance Aura I.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Nature's Grasp III, Challenging Roar, Cower I, Entangling Roots III, Moonfire V, Rejuvenation V and Rip II.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tFly for level-28 training.\nF\t\tOrgrimmar\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Shadow Bolt V, Bane of Agony III and Banish; learn Imp Firebolt IV. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Overpower II, Shield Wall and Thunder Clap III. Keep Shield Wall ready for heavy incoming damage while using a shield.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Fire Resistance Totem I, Flame Shock III, Flametongue Totem I, Frostbrand Weapon II, Lesser Healing Wave II, Stoneclaw Totem III and Water Walking. Keep a few Fish Oil for Water Walking.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Sap II, Backstab IV, Feint II and Rupture II.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Instant Poison II (120 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Devouring Plague II, Heal III, Mind Blast IV and Psychic Scream II.\nV\t\ttrainer\t\nS\tTroll Priest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Shadowguard II.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Arcane Intellect III, Conjure Mana Agate and Blizzard II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aimed Shot II, Arcane Shot IV, Aspect of the Hawk III, Frost Trap and Mend Pet III.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nA\t\t2841\t\nS\t\t\t\nA\t\t2842\t\nS\t\t\t\nI\t\tFly to Camp Taurajo.\nF\t\tCamp Taurajo\t\nS\t\t\t\nT\t\t1153\t\nS\t\t\t\nI\t\tFly to Freewind Post after the city preparation.\nF\t\tFreewind Post\t\nS\t\t\t\nI\t\tRide down and approach Darkcloud Pinnacle by its winding western footpath. Follow the ramps and bridges; do not climb or jump between mesas.\nS\t\t\t\nI\t\tHave the Incendia Powder ready before climbing Darkcloud Pinnacle.\nS\t\t\t\nI\t\tRecover Secret Notes #1, #2 and #3 from their separate chests on the plateau for {q5064}.\nC\t\t5064\t\t\nS\t\t\t\nI\t\tClear to Arnak Grimtotem and loot his hoof for {q5147}.\nC\t\t5147\t\t\nS\t\t\t\nI\t\tRecover the Cloven Hoof from the plateau chest for {q1197}.\nC\t\t1197\t\t\nS\t\t\t\nI\t\tForm a party at the Sacred Fire of Life for Arikara, then use the Incendia Powder, defeat Arikara with the party and loot her skin for {q5088}.\nC\t\t5088\t\t\nS\t\t\t\nI\t\tClear Lakota's return path before speaking to her and accepting {q4904} to start her escort.\nA\t\t4904\t\nS\t\t\t\nI\t\tEscort Lakota down the pinnacle for {q4904}, staying with her through every ambush.\nC\t\t4904\t\t\nS\t\t\t\nI\t\tReturn by the cleared ramps and canyon road to Whitereach.\nS\t\t\t\nT\t\t5088\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Freewind Post if ready; otherwise return by the canyon road and lifts.\nH\t\tHearth to Freewind Post\nS\t\t\t\nT\t\t1197\t\nS\t\t\t\nT\t\t4904\t\nS\t\t\t\nT\t\t5064\t\nT\t\t5147\t\nS\t\t\t\nT\t\t4767\t\nS\t\t\t\nI\t\tReach level 29 before the next dungeon journey; finish on isolated level 28-29 canyon wildlife if needed.\nX\t\t\t29\t\t\t\nS\t\t\t\nI\t\tFly to the Crossroads for Korran's silithid report.\nF\t\tThe Crossroads\t\nS\t\t\t\nA\t\t1145\t\nS\t\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\t\t\t\nT\t\t1145\t\nA\t\t1146\t\nS\t\t\t\nI\t\tKeep Changing Tastes, Battle of Hillsbrad, Rig Wars and Chief Engineer Scooty." },
  { name = "29-31 Hillsbrad Foothills (Horde)", title = "29-31 Hillsbrad Foothills", group = "Bethink's Guide 20-40", faction = "Horde", lo = 29, hi = 31, next = "31-33 Stranglethorn Vale (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Excavation Site at 29, the Hillsbrad village finale and City of Dalaran at 30. Ends in Undercity for the Grom’gol zeppelin.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 29 with Changing Tastes, Battle of Hillsbrad, Rig Wars and Chief Engineer Scooty.\nX\t\t\t29\t\t\t\nS\t\t\t\nI\t\tTake the Tirisfal zeppelin outside Orgrimmar; enter Undercity by its main lifts, then fly to Tarren Mill.\nS\t\t\t\nI\t\tFly to Tarren Mill.\nF\t\tTarren Mill\t\nS\t\t\t\nA\t\t509\t\nS\t\t\t\nA\t\t567\t\nS\t\t\t\nA\t\t547\t\nS\t\t\t\nG\t\tHillsbrad Foothills\t62.78\t19.03\t\t\t\nI\t\tBind with Shay for both dungeon returns.\nB\t\tSet your hearthstone to Tarren Mill\nS\t\t\t\nI\t\tFollow the road east through Hillsbrad into Arathi; turn northeast to Hammerfall, avoiding Alliance Refuge Pointe.\nS\t\t\t\nG\t\tArathi Highlands\t73.02\t32.7\t\t\t\nI\t\tTake the flight point on arrival.\nP\t\tHammerfall\t\nS\t\t\t\nA\t\t95663\t\nS\t\t\t\nI\t\tTravel south through Arathi and across the Thandol Span into Wetlands. Keep clear of Stromgarde and Alliance camps. Follow the Wetlands road toward Thelgen Rock.\nS\t\t\t\nG\t\tWetlands\t47.7\t56.2\t\t\t\nI\t\tApproach through Thelgen Rock, then follow the uphill road southeast of Whelgar's Excavation to the blue mist beneath the large tree. Find the Deathstalker Agent outside the entrance.\nS\t\t\t\nT\t\t95663\t\nA\t\t95682\t\nS\t\t\t\nI\t\tAt the Excavation Site entrance, join a five-player party with a tank and healer for the dungeon clear.\nS\t\t\t\nI\t\tEnter together and complete one Excavation Site clear through Saltspine, Shadetooth and the Relic Guardian.\nS\t\t\t\nI\t\tDefeat the Dragonmaw forces and recover the Dragonmaw Dispatch during the clear for {q95682}.\nC\t\t95682\t\t\nS\t\t\t\nI\t\tCollect four Thicket Raptor Meat for {q95697} before leaving the thicket.\nC\t\t95697\t\t\nS\t\t\tcompletewith=next\nI\t\tIf you receive a Titan Relic from the Relic Guardian, use it to accept {q95664}; keep it for Thunder Bluff.\nA\t\t95664\t\nS\t\t\t\nI\t\tLeave by the cleared entrance.\nS\t\t\t\nI\t\tReport to the Deathstalker Agent outside, then turn in {q95682}.\nT\t\t95682\t\nS\t\t\tcompletewith=next\nG\t\tArathi Highlands\t73.02\t32.7\t\t\t\nI\t\tHearth to Tarren Mill if ready; otherwise return across the Thandol Span to Hammerfall and fly.\nH\t\tHearth to Tarren Mill\nF\t\tTarren Mill\t\nS\t\t\t\nI\t\tClear the town hall by its entrance. Defeat Clerk Horrace Whitesteed, Magistrate Burnside and five Councilmen, destroy the Hillsbrad Proclamation and recover the Town Registry for {q567} and {q532}.\nC\t\t567\t1\t\nC\t\t532\t\t\nS\t\t\t\nI\t\tDefeat Citizen Wilkes in the village for {q567}.\nC\t\t567\t2\t\nS\t\t\t\nI\t\tDefeat Farmer Kalaba at the farm for {q567}; keep Miner Hackett for the mine circuit.\nC\t\t567\t4\t\nS\t\t\t\nI\t\tReturn to Tarren Mill.\nS\t\t\t\nT\t\t532\t\nA\t\t539\t\nS\t\t\t\nI\t\tEnter the Hillsbrad mine, kill ten Miners and defeat Foreman Bonds and Miner Hackett for {q539} and {q567}. Leave by the cleared tunnel, then return to Tarren Mill.\nC\t\t539\t\t\nC\t\t567\t3\t\nS\t\t\t\nT\t\t567\t\nT\t\t539\t\nA\t\t541\t\nS\t\t\t\nI\t\tTake the southeastern road to Dun Garok and form a party at the fortress approach for the dwarf objectives. Clear the fortress stairs; kill eight Mountaineers, four Riflemen, two Priests and Captain Ironhill, collecting Humbert's Sword from the dwarves for {q541} and {q547} before leaving.\nC\t\t541\t\t\nC\t\t547\t\t\nS\t\t\t\nI\t\tGather six Mudsnout Blossoms at the farm east of the central river for {q509}; clear its gnoll guards.\nC\t\t509\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready; otherwise return by the northern road, avoiding Southshore.\nH\t\tHearth to Tarren Mill\nS\t\t\t\nT\t\t547\t\nS\t\t\t\nT\t\t541\t\nA\t\t550\t\nS\t\t\t\nT\t\t509\t\nA\t\t513\t\nS\t\t\t\nI\t\tFly for training and ready deliveries.\nF\t\tUndercity\t\nS\t\t\t\nT\t\t550\t\nS\t\t\t\nT\t\t513\t\nS\t\t\t\nI\t\tReach level 30 before class training and Dalaran. If short, fly to Tarren Mill and hunt isolated level 29-30 coastal enemies east of Southshore, then return to Undercity.\nX\t\t\t30\t\t\t\nS\t\t\t\nI\t\tAccept {q515}. Accept {q1109}; keep it for Razorfen Kraul at 34.\nA\t\t515\t\nA\t\t1109\t\nS\t\t\t\nA\t\t96988\t\nS\t\t\t\nI\t\tBuy one Strong Troll's Blood Potion from the Auction House for Lydon; keep it with the Mudsnout Mixture.\nK\t\t3388\t1\t\t\nS\tWarlock\t\t\nG\t\tUndercity\t86.21\t15.93\t\t\t\nI\t\tAt Kaal Soulreaper, learn Demon Armor II, Immolate IV, Drain Life III, Curse of the Elements II, Create Soulstone II, Subjugate Demon and Hellfire; learn Voidwalker Torment III. Buy and use the listed demon grimoires from Martha Strain nearby.\nV\t\ttrainer\t\nS\tWarlock\t\t\nI\t\tAccept {q3001} from Carendin Halgar.\nA\t\t3001\t\nS\tWarlock\t\t\nI\t\tLeave Undercity by its main lifts and take the Orgrimmar zeppelin.\nS\tWarlock\t\t\nI\t\tEnter Orgrimmar and fly to Ratchet for Strahad Farsan north of town.\nF\t\tRatchet\t\nS\tWarlock\t\t\nT\t\t3001\t\nA\t\t1801\t\nS\tWarlock\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready and fly to Undercity; otherwise fly from Ratchet to Orgrimmar, take the Tirisfal zeppelin and enter Undercity by its main lifts.\nH\t\tHearth to Tarren Mill\nS\tWarlock\t\t\nI\t\tTurn in {q1801} to Jorah Annison, then accept {q1803}; keep the book collection for the Hillsbrad return.\nT\t\t1801\t\nA\t\t1803\t\nS\tWarrior\t\t\nG\t\tUndercity\t47.4\t17.29\t\t\t\nI\t\tAt Baltus Fowler, learn Cleave II, Rend IV and Slam II.\nV\t\ttrainer\t\nS\tWarrior\t\t\nA\t\t1718\t\nS\tWarrior\t\t\nG\t\tTirisfal Glades\t60.9\t58.7\t\t\t\nI\t\tLeave by Undercity's main lifts and take the Orgrimmar zeppelin.\nS\tWarrior\t\t\nI\t\tEnter Orgrimmar by its main gate and fly to Ratchet.\nF\t\tRatchet\t\nS\tWarrior\t\t\nG\t\tThe Barrens\t66.0\t48.0\t\t\t\nI\t\tFollow the coast south from Ratchet to the shallow crossing, then swim out to Fray Island.\nS\tWarrior\t\t\nT\t\t1718\t\nA\t\t1719\t\nS\tWarrior\t\t\nG\t\tThe Barrens\t68.62\t49.16\t\t\t\nI\t\tHave food and bandages ready for The Affray.\nS\tWarrior\t\t\nI\t\tStep onto the grate to begin. Defeat the challengers, recover before engaging level-33 Big Will, then defeat him for {q1719}.\nC\t\t1719\t\t\nS\tWarrior\t\t\nI\t\tTurn in {q1719} to Klannoc Macleod. Learn Berserker Stance and Intercept.\nT\t\t1719\t\nS\tWarrior\t\t\nI\t\tReturn along the coast to Ratchet and fly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Berserker Rage.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tDurotar\t50.8\t13.6\t\t\t\nI\t\tTake the Tirisfal zeppelin back and enter Undercity by its main lifts before continuing.\nS\tShaman\t\t\nG\t\tTirisfal Glades\t60.9\t58.7\t\t\t\nI\t\tLeave Undercity by its main lifts and take the Orgrimmar zeppelin for Shaman training.\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Astral Recall, Call of the Ancestors, Grounding Totem, Healing Stream Totem II, Nature Resistance Totem I, Reincarnation, Searing Totem III and Windfury Weapon I. Keep an Ankh for Reincarnation.\nV\t\ttrainer\t\nS\tShaman\t\t\nA\t\t1531\t\nS\tShaman\t\t\nI\t\tFly to Freewind Post in Thousand Needles.\nF\t\tFreewind Post\t\nS\tShaman\t\t\nG\t\tThousand Needles\t54.0\t44.0\t\t\t\nI\t\tTake the narrow mountain path beside the totem pole up to the Weathered Nook.\nS\tShaman\t\t\nI\t\tFollow the mountain trail up to Prate Cloudseer, then turn in {q1531}. Receive your Air Totem; keep it in your bags.\nT\t\t1531\t\nS\tShaman\t\t\nI\t\tReturn by the trail to Freewind Post and fly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t45.99\t45.68\t\t\t\nI\t\tBuy a few Ankhs from Hagrus for Reincarnation.\nV\t\tvendor\t\nS\tShaman\t\t\nG\t\tDurotar\t50.8\t13.6\t\t\t\nI\t\tTake the Tirisfal zeppelin back and enter Undercity by its main lifts before continuing.\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Disarm Trap, Kidney Shot I, Garrote III and Sinister Strike V.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Deadly Poison I (130 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t75.2\t51.18\t\t\t\nI\t\tBuy ingredients for your usable poisons and Flash Powder from Ezekiel Graves.\nV\t\tvendor\t\nS\tPriest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Divine Spirit I, Fade III, Holy Fire III, Inner Fire III, Mind Control I, Power Word: Shield V, Prayer of Healing I, Shadow Protection I and Smite V.\nV\t\ttrainer\t\nS\tUndead Priest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Touch of Weakness III and Dark Sacrifice II.\nV\t\ttrainer\t\nS\tTroll Priest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Hex of Weakness III.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Seal of Light I, Consecration II, Holy Light V, Lay on Hands II, Devotion Aura IV and Divine Intervention.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t82.78\t15.83\t\t\t\nI\t\tBuy Symbols of Divinity from Hannah Akeley for Divine Intervention.\nV\t\tvendor\t\nS\tMage\t\t\nG\t\tUndercity\t85.14\t10.03\t\t\t\nI\t\tAt Anastasia Hartwell, learn Ice Armor I, Fireball VI, Fire Blast IV and Conjure Water IV.\nV\t\ttrainer\t\nS\tMage\t\t\nI\t\tAccept {q1947} from your Mage trainer; keep the introduction for Tabetha.\nA\t\t1947\t\nS\tHunter\t\t\nI\t\tLeave Undercity by the main lifts and take the Orgrimmar zeppelin for Hunter training.\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aspect of the Beast, Distracting Shot III, Feign Death, Mongoose Bite II and Scare Beast II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Growl IV, Great Stamina V, Natural Armor V. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\tHunter\t\t\nI\t\tTake the Tirisfal zeppelin back and return through the Undercity lifts before continuing.\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Travel Form, Bash II, Faerie Fire II, Mark of the Wild IV, Rebirth II, Regrowth IV, Shred II, Tranquility I and Wrath V.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tDruid\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tDruid\t\t\nG\t\tOrgrimmar\t45.99\t45.68\t\t\t\nI\t\tBuy Stranglethorn Seeds from Hagrus for your new Rebirth rank.\nV\t\tvendor\t\nS\tDruid\t\t\nI\t\tTake the Tirisfal zeppelin outside Orgrimmar, then return through the main lifts to Undercity.\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tFly to Tarren Mill.\nF\t\tTarren Mill\t\nS\t\t\t\nA\t\t92434\t\nS\t\t\t\nA\t\t96986\t\nS\tWarlock\t\t\nI\t\tFollow the western Hillsbrad road toward Silverpine, staying clear of Southshore, for the Moldy Tome at the Western Strand murloc camps.\nS\tWarlock\t\t\nI\t\tClear the murlocs and collect the Moldy Tome from the ground for {q1803}.\nC\t\t1803\t1\t\nS\tWarlock\t\t\nI\t\tReturn to Tarren Mill and fly to Undercity.\nF\t\tUndercity\t\nS\tWarlock\t\t\nI\t\tTake the Orgrimmar zeppelin outside the main lifts.\nS\tWarlock\t\t\nI\t\tFly to Freewind Post, descend its lifts and follow the canyon road north to Splithoof Crag.\nF\t\tFreewind Post\t\nS\tWarlock\t\t\nG\t\tThousand Needles\t44.4\t36.9\t\t\t\nI\t\tEnter Splithoof Hold by its southern cave mouth. Keep right at the forks, following the upper passage past the stream.\nS\tWarlock\t\t\nI\t\tOpen the Damaged Chest in the upper passage and take the Tattered Manuscript for {q1803}.\nC\t\t1803\t2\t\nS\tWarlock\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready and fly to Undercity; otherwise leave by the cleared entrance, return to Freewind Post, fly to Orgrimmar, take the Tirisfal zeppelin and enter Undercity by its main lifts.\nH\t\tHearth to Tarren Mill\nS\tWarlock\t\t\nI\t\tTurn in {q1803} to Jorah, then accept {q1805}.\nT\t\t1803\t\nA\t\t1805\t\nS\tWarlock\t\t\nI\t\tFly to Hammerfall and follow the roads south across the Thandol Span into Wetlands. Stay clear of Alliance camps and continue south to the Angerfang Encampment.\nF\t\tHammerfall\t\nS\tWarlock\t\t\nI\t\tCollect three Rods of Channeling from Dragonmaw Bonewarders and Shadowwarders for {q1805}.\nC\t\t1805\t\t\nS\tWarlock\t\t\nI\t\tReturn across the Thandol Span to Hammerfall and fly to Undercity.\nF\t\tUndercity\t\nS\tWarlock\t\t\nI\t\tTake the Orgrimmar zeppelin outside the main lifts.\nS\tWarlock\t\t\nI\t\tEnter Orgrimmar and fly to Ratchet.\nF\t\tRatchet\t\nS\tWarlock\t\t\nI\t\tTurn in {q1805} to Strahad, then accept {q1795}.\nT\t\t1805\t\nA\t\t1795\t\nS\tWarlock\t\t\nI\t\tUse the Tome of the Cabal at Strahad's summoning circle and subdue the Felhunter for {q1795}.\nC\t\t1795\t\t\nS\tWarlock\t\t\nI\t\tTurn in {q1795} to learn Summon Felhunter.\nT\t\t1795\t\nS\tWarlock\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready; otherwise fly from Ratchet to Orgrimmar, take the Tirisfal zeppelin, enter Undercity by its main lifts and fly to Tarren Mill.\nH\t\tHearth to Tarren Mill\nS\t\t\t\nI\t\tCollect five Torn Fin Eyes from the Western Strand murlocs.\nK\t\t3510\t5\t\t\nS\t\t\t\nI\t\tGo inland around Southshore to the Eastern Strand and collect five Daggerspine Scales from the naga for {q515}; keep the potion and mixture for the delivery.\nC\t\t515\t\t\nS\t\t\t\nI\t\tReturn north to Tarren Mill.\nS\t\t\t\nT\t\t515\t\nA\t\t517\t\nS\t\t\t\nI\t\tReturn to Dun Garok's approach, form a party for the keg and recover the Keg of Shindigger Stout from the cleared fortress for {q517}.\nC\t\t517\t\t\nS\t\t\t\nI\t\tReturn to Tarren Mill.\nS\t\t\t\nT\t\t517\t\nA\t\t524\t\nS\t\t\t\nI\t\tPlace the Tainted Keg on the rug beside the captured farmers, then finish the dialogue to turn in {q524}.\nT\t\t524\t\nS\t\t\t\nI\t\tFollow the western Hillsbrad road to Lordamere Lake, then travel along the shore to Modera and the sewer gate. Stay outside Dalaran's surface streets and guards.\nS\t\t\t\nT\t\t92434\t\nA\t\t96984\t\nS\t\t\t\nI\t\tKeep the Dalaran Sewer Key provided with Heart of Disruption.\nS\t\t\t\nI\t\tAccept {q96987} from Rexxie Copperclutch near the sewer entrance.\nA\t\t96987\t\nS\t\t\t\nI\t\tAt Modera's sewer gate, join a five-player City of Dalaran party with a tank and healer.\nS\t\t\t\nI\t\tOpen the gate beside Modera, follow the sewer passage together and enter the dungeon portal.\nS\t\t\t\nI\t\tComplete one City of Dalaran clear from the Underbelly through Atrexis and the city bosses to the Shade of the Archmage in the Violet Citadel. Avoid beams and ground effects; spread for the final boss.\nS\t\t\t\nI\t\tDefeat Atrexis the Grave Knight in the Underbelly for {q96986}.\nC\t\t96986\t\t\nS\t\t\t\nI\t\tCollect six Cracked Sentry Cores from the constructs during the clear for {q96988}.\nC\t\t96988\t\t\nS\t\t\t\nI\t\tRecover The Founding of Dalaran for {q96987} before leaving its library area.\nC\t\t96987\t\t\nS\t\t\t\nI\t\tDefeat the Shade and personally loot the Arcane Mote for {q96984}.\nC\t\t96984\t\t\nS\t\t\t\nI\t\tReturn by the cleared dungeon passages to Rexxie at the sewer entrance, then turn in {q96987}.\nT\t\t96987\t\nS\t\t\t\nI\t\tLeave through the sewers with the party. Stay outside the outdoor city.\nS\t\t\tcompletewith=next\nI\t\tHearth to Tarren Mill if ready; otherwise return along the lakeshore and western road.\nH\t\tHearth to Tarren Mill\nS\t\t\t\nT\t\t96986\t\nS\t\t\t\nT\t\t96984\t\nS\t\t\t\nI\t\tAccept {q97287} from Magus Wordeen Voidglare.\nA\t\t97287\t\nS\t\t\t\nI\t\tFollow the western road to Lordamere Lake.\nS\t\t\t\nG\t\tAlterac Mountains\t14.3\t59.57\t\t\t\nI\t\tTurn in {q97287} to the Image of Archmage Modera outside Dalaran. Stay outside the surface city.\nT\t\t97287\t\nS\t\t\t\nI\t\tReturn along the road to Tarren Mill.\nS\t\t\t\nI\t\tFly to Undercity.\nF\t\tUndercity\t\nS\t\t\t\nT\t\t96988\t\nS\t\t\t\nI\t\tReach level 31 before Stranglethorn. If short, return to the level 30-31 eastern Hillsbrad coast and finish on isolated enemies, then fly back.\nX\t\t\t31\t\t\t\nS\t\t\t\nI\t\tKeep the Titan Relic if found, Changing Tastes, Going, Going, Guano, Rig Wars and Chief Engineer Scooty." },
  { name = "31-33 Stranglethorn Vale (Horde)", title = "31-33 Stranglethorn Vale", group = "Bethink's Guide 20-40", faction = "Horde", lo = 31, hi = 33, next = "33-35 Thousand Needles (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Arathi preparation, Gnomeregan at 31 via Scooty’s teleporter and northern jungle quests. Ends in Orgrimmar.",
    steps = "S\t\t\t\nI\t\tStart in Undercity at 31 with Rig Wars and Chief Engineer Scooty. Keep the later Kalimdor deliveries.\nX\t\t\t31\t\t\t\nS\t\t\t\nI\t\tFly to Hammerfall.\nF\t\tHammerfall\t\nS\t\t\t\nA\t\t677\t\nS\t\t\t\nA\t\t671\t\nS\t\t\t\nI\t\tCollect ten Bloodstone Amulets from the outer Syndicate camps at Northfold Manor for {q671}.\nC\t\t671\t\t\nS\t\t\t\nI\t\tKill ten Witherbark Axe Throwers, ten Headhunters and eight Witch Doctors in the southeastern camps for {q677}.\nC\t\t677\t\t\nS\t\t\t\nI\t\tReturn to Hammerfall.\nS\t\t\t\nT\t\t671\t\nS\t\t\t\nT\t\t677\t\nA\t\t678\t\nS\t\t\t\nI\t\tFly to Undercity. Keep Call to Arms for the return at 37.\nF\t\tUndercity\t\nS\t\t\t\nI\t\tLeave by the main lifts and take the Grom'gol zeppelin; confirm its destination before boarding.\nS\t\t\t\nG\t\tStranglethorn Vale\t32.54\t29.35\t\t\t\nI\t\tTake the flight point on arrival.\nP\t\tGrom'gol\t\nS\t\t\t\nI\t\tFollow the main road south to Booty Bay, staying clear of the roadside camps.\nS\t\t\t\nI\t\tArrive in Booty Bay and take the Horde flight point before the town circuit.\nS\t\t\t\nG\t\tStranglethorn Vale\t26.87\t77.1\t\t\t\nI\t\tTake Gringer's flight point.\nP\t\tBooty Bay\t\nS\t\t\t\nA\t\t213\t\nA\t\t189\t\nS\t\t\t\nA\t\t201\t\nS\t\t\t\nG\t\tStranglethorn Vale\t27.04\t77.31\t\t\t\nI\t\tBind with Skindle for the Gnomeregan return.\nB\t\tSet your hearthstone to Booty Bay\nS\t\t\t\nA\t\t605\t\nS\t\t\t\nA\t\t575\t\nS\t\t\t\nT\t\t2842\t\nA\t\t2843\t\nS\t\t\t\nI\t\tWait for Scooty to finish calibrating the Goblin Transponder for {q2843}.\nC\t\t2843\t\t\nS\t\t\t\nT\t\t2843\t\nS\t\t\t\nI\t\tRepair and restock.\nV\t\tvendor\t\nS\t\t\t\nI\t\tKeep the Goblin Transponder and use Scooty's teleporter to Gnomeregan. At the main portal, join a five-player party with a tank and healer for the clear.\nS\t\t\t\nI\t\tComplete one Gnomeregan clear through Thermaplugg. Protect Emi Shortfuse during the Grubbis event, defeat Viscous Fallout, and follow the ramps through the Clean Zone.\nS\t\t\t\nI\t\tStop mobile alarm-bots and assign the bomb buttons before fighting Thermaplugg. Defeat him and loot his Safe Combination, then open Thermaplugg's Safe on the room's outer ledge and take the Rig Blueprints for {q2841}.\nC\t\t2841\t\t\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: V106_GNOMEREGAN_RING_NOTICE\nS\t\t\tcompletewith=next\nI\t\tGuide migration: If carrying a Grime-Encrusted Ring, use it to accept {q2945} and clean it during the scheduled Gnomeregan clear. If that clear is already behind you, skip the unfinished ring quests instead of repeating the dungeon.\nU\t\t9326\t\nA\t\t2945\t\nS\t\t\t\nI\t\t-- MIGRATION END: V106_GNOMEREGAN_RING_NOTICE\nS\t\t\tcompletewith=next\nI\t\tUse your personally looted Grime-Encrusted Ring to accept {q2945}.\nU\t\t9326\t\nA\t\t2945\t\nS\t\t\t\nI\t\tReturn to the Clean Zone by the cleared ramps. Clean your quest ring at the Sparklematic 5200 for three silver, then turn in {q2945}.\nT\t\t2945\t\nS\t\t\tcompletewith=next\nI\t\tAccept {q2949}; keep the clean ring for Nogg in Orgrimmar.\nA\t\t2949\t\nS\t\t\t\nI\t\tFind Kernobee in the Dormitory beside the Clean Zone after clearing the return path. Confirm everyone is ready before waking him and accepting {q2904}.\nA\t\t2904\t\nS\t\t\t\nI\t\tEscort him straight to Clockwerk Run and stay inside the portal until his final dialogue grants credit for {q2904}.\nC\t\t2904\t\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Booty Bay if ready; otherwise leave by the cleared main entrance and use the transponder teleporter back to Booty Bay.\nH\t\tHearth to Booty Bay\nS\t\t\t\nT\t\t2904\t\nS\t\t\tcompletewith=next\nG\t\tStranglethorn Vale\t27.42\t77.16\t\t\t\nI\t\tIf ready at 125 Fishing, buy and use Expert Fishing - The Bass and You from Old Man Heming; skip otherwise.\nS\t\t\t\nI\t\tFollow the main road north to Nesingwary's camp, avoiding the Rebel Camp and its guards.\nS\t\t\t\nI\t\tVisit Nesingwary's camp and speak to the hunters for {q201}.\nC\t\t201\t\t\nS\t\t\t\nA\t\t583\t\nS\t\t\t\nT\t\t583\t\nA\t\t194\t\nS\t\t\t\nA\t\t185\t\nS\t\t\t\nA\t\t190\t\nS\t\t\t\nI\t\tKill ten Young Stranglethorn Tigers west of camp on open ground for {q185}.\nC\t\t185\t\t\nS\t\t\t\nI\t\tKill ten Young Panthers east of camp for {q190}.\nC\t\t190\t\t\nS\t\t\t\nT\t\t185\t\nA\t\t186\t\nS\t\t\t\nT\t\t190\t\nA\t\t191\t\nS\t\t\t\nI\t\tKill ten Stranglethorn Tigers on the northwestern slopes for {q186}. Avoid Sin'Dall's hill.\nC\t\t186\t\t\nS\t\t\t\nI\t\tKill ten Panthers on the northwestern slopes for {q191}.\nC\t\t191\t\t\nS\t\t\t\nI\t\tKill ten Stranglethorn Raptors on the western slopes for {q194}, avoiding the troll ruins and stronger coast.\nC\t\t194\t\t\nS\t\t\t\nT\t\t186\t\nA\t\t187\t\nS\t\t\t\nT\t\t191\t\nA\t\t192\t\nS\t\t\t\nT\t\t194\t\nA\t\t195\t\nS\t\t\t\nI\t\tReach level 32 before the stronger northern quests. If short, hunt isolated level 31-32 northern tigers and panthers.\nX\t\t\t32\t\t\t\nS\t\t\t\nI\t\tCollect two Large River Crocolisk Skins from the northern river crocolisks for {q575}.\nC\t\t575\t\t\nS\t\t\t\nG\t\tStranglethorn Vale\t34.68\t6.74\t\t\t\nI\t\tCollect ten Singing Crystal Shards from Stone Maw Basilisks on the northern ridge for {q605}. Reach it by the slope; do not climb the cliff.\nC\t\t605\t\t\nS\t\t\t\nI\t\tCollect eight Tumbled Crystals from Venture Co. Geologists in the northern mine for {q213}.\nC\t\t213\t\t\nS\t\t\t\nG\t\tStranglethorn Vale\t29.82\t19.1\t\t\t\nI\t\tCollect fifteen Bloodscalp Ears from the outer Bal'lal camps for {q189}; avoid the deeper ruins for now.\nC\t\t189\t\t\nS\t\t\t\nI\t\tKill ten Elder Stranglethorn Tigers on the central northern slopes for {q187}.\nC\t\t187\t\t\nS\t\t\t\nI\t\tKill ten Lashtail Raptors east of the main road for {q195}.\nC\t\t195\t\t\nS\t\t\t\nT\t\t187\t\nA\t\t188\t\nS\t\t\t\nT\t\t195\t\nA\t\t196\t\nS\t\t\t\nI\t\tReach Sin'Dall's hill by its slope defeat her and loot her paw for {q188}.\nC\t\t188\t\t\nS\t\t\t\nT\t\t188\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Booty Bay if ready; otherwise return south by the main road.\nH\t\tHearth to Booty Bay\nS\t\t\t\nT\t\t605\t\nA\t\t600\t\nS\t\t\t\nT\t\t189\t\nT\t\t213\t\nS\t\t\t\nT\t\t201\t\nS\t\t\t\nT\t\t575\t\nA\t\t577\t\nS\t\t\t\nI\t\tTake the Ratchet ship; confirm its destination at the dock.\nS\t\t\t\nI\t\tFly from Ratchet to Orgrimmar.\nF\t\tOrgrimmar\t\nS\t\t\t\nT\t\t2841\t\nS\t\t\t\nT\t\t95697\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Fear II, Shadow Ward and Curse of Weakness IV; learn Shadowburn when talented. Learn Voidwalker Sacrifice III. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Battle Shout IV, Execute II, Hamstring II, Heroic Strike V and Shield Bash II.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Chain Lightning I, Fire Nova III, Healing Wave VI, Lightning Bolt VI, Lightning Shield IV, Purge II and Windfury Totem I.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Gouge III and Eviscerate V.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Wound Poison I (140 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Abolish Disease, Flash Heal III, Mana Burn II, Renew V and Shadow Word: Death I.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Frostbolt VI, Conjure Food IV, Arcane Missiles IV and Flamestrike III.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Flare, Raptor Strike V and Track Demons.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tTurn in {q2949} to Nogg if carrying the clean ring.\nT\t\t2949\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tReach level 33 before the Shimmering Flats journey.\nX\t\t\t33\t\t\t\nS\t\t\t\nI\t\tKeep Going, Going, Guano, the Titan Relic if found, and the later jungle quests." },
  { name = "33-35 Thousand Needles (Horde)", title = "33-35 Thousand Needles", group = "Bethink's Guide 20-40", faction = "Horde", lo = 33, hi = 35, next = "35-37 Desolace (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Razorfen Kraul at 34, Shimmering Flats quests and deliveries. Ends in Thunder Bluff for Desolace.",
    steps = "S\t\t\t\nI\t\tStart in Orgrimmar at 33 with Going, Going, Guano and the later Stranglethorn quests.\nX\t\t\t33\t\t\t\nS\t\t\t\nI\t\tFly to Thunder Bluff for Razorfen Kraul preparation.\nF\t\tThunder Bluff\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Blessing of Might IV, Frost Resistance Aura I and Seal of the Crusader IV.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tThunder Bluff\t22.5\t16.91\t\t\t\nI\t\tAt Birgitte Cranston, learn Teleport: Thunder Bluff.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Demoralizing Roar III, Ferocious Bite II, Healing Touch VI, Poised, Ravage I and Track Humanoids.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tAccept {q1049}; keep it for Scarlet Monastery.\nA\t\t1049\t\nS\t\t\t\nA\t\t1102\t\nS\t\t\t\nI\t\tAccept {q1136}; keep it for the Alterac journey.\nA\t\t1136\t\nS\t\t\t\nG\t\tThunder Bluff\t71.06\t34.19\t\t\t\nT\t\t95664\t\nS\t\t\tcompletewith=next\nI\t\tAccept {q98823} from Bashana Runetotem if the relic delivery was completed.\nA\t\t98823\t\nS\t\t\t\nI\t\tLeave Thunder Bluff by its lifts and follow the Mulgore paths northwest to the Skywatcher Plateau.\nS\t\t\t\nI\t\tTurn in {q98823} to Muln Earthfury if carrying the relic.\nT\t\t98823\t\nS\t\t\t\nI\t\tAccept {q96774} from Mazu'kon.\nA\t\t96774\t\nS\t\t\t\nI\t\tReturn by the paths and lifts to Thunder Bluff.\nS\t\t\t\nI\t\tFly to Ratchet.\nF\t\tRatchet\t\nS\t\t\t\nA\t\t1221\t\nS\t\t\t\nG\t\tThe Barrens\t62.32\t37.61\t\t\t\nI\t\tTake the Crate with Holes, Snufflenose Command Stick and Owner's Manual beside Mebok. Read the manual and keep all three.\nS\t\t\t\nG\t\tThe Barrens\t62.05\t39.41\t\t\t\nI\t\tBind with Wiley for the flats return.\nB\t\tSet your hearthstone to Ratchet\nS\tMage\t\t\nI\t\tFollow the Gold Road south to the Dustwallow road, then follow the marsh paths to Tabetha; avoid Brackenwall Village.\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: V106_MAGE_MARSH_INTRODUCTION\nS\tMage\t\t\nI\t\tGuide migration: Before the scheduled Library clear, visit your Mage trainer in Undercity and accept {q1947}. If that clear is already behind you, skip this quest and its follow-ups.\nA\t\t1947\t\nS\tMage\t\t\nI\t\tGuide migration: Travel through Booty Bay and Ratchet to Tabetha in Dustwallow Marsh, then turn in {q1947}.\nT\t\t1947\t\nS\t\t\t\nI\t\t-- MIGRATION END: V106_MAGE_MARSH_INTRODUCTION\nS\tMage\t\t\nI\t\tTurn in {q1947}, then accept {q1948} and {q1949}. Keep Items of Power for the later Arathi visit.\nT\t\t1947\t\nA\t\t1948\t\nA\t\t1949\t\nS\tMage\t\t\nI\t\tReturn by the marsh road to the Gold Road before continuing south.\nS\t\t\t\nI\t\tFollow the Gold Road south through the Barrens and ride the Great Lift down; do not jump. Continue east across the canyon floor to the Shimmering Flats.\nS\tShaman\t\t\nI\t\tUse the Freewind Post lifts and accept {q79360} from Rau Cliffrunner, then return to the canyon floor and continue east.\nA\t\t79360\t\nS\t\t\t\nT\t\t1146\t\nA\t\t1147\t\nS\t\t\t\nA\t\t1110\t\nS\t\t\t\nA\t\t1111\t\nS\t\t\t\nA\t\t1104\t\nS\t\t\t\nA\t\t1105\t\nS\t\t\t\nA\t\t1175\t\nS\t\t\t\nA\t\t1176\t\nS\t\t\t\nI\t\tCollect six Salty Scorpid Venoms for {q1104}, nine Hardened Tortoise Shells for {q1105}, thirty Rocket Car Parts for {q1110} and ten Hollow Vulture Bones for {q1176}; kill ten Saltstone Basilisks, ten Saltstone Crystalhides and six Saltstone Gazers for {q1175}.\nC\t\t1104\t\t\nC\t\t1105\t\t\nC\t\t1110\t\t\nC\t\t1176\t\t\nC\t\t1175\t\t\nS\t\t\tcompletewith=next\nI\t\tUse a personally dropped Cracked Silithid Carapace as soon as obtained to accept {q1148}.\nU\t\t5877\t\nA\t\t1148\t\nS\t\t\tcompletewith=next\nG\t\tThousand Needles\t71.75\t86.01\t\t\t\nI\t\tIf active, collect one Silithid Heart, five Talons and three Intact Carapaces during the Silithid quests for {q1148}.\nC\t\t1148\t\t\nS\t\t\t\nI\t\tKill five Silithid Searchers and five Hive Drones around the hive, then enter by its mouth and kill five Invaders for {q1147}. Keep a retreat through the tunnels and finish Parts of the Swarm here if active.\nC\t\t1147\t\t\nS\t\t\t\nT\t\t1147\t\nS\t\t\t\nT\t\t1175\t\nS\t\t\t\nT\t\t1176\t\nA\t\t1178\t\nS\t\t\t\nT\t\t1110\t\nA\t\t5762\t\nS\t\t\t\nT\t\t1104\t\nS\t\t\t\nT\t\t1105\t\nS\t\t\t\nA\t\t1107\t\nS\t\t\t\nA\t\t1106\t\nS\tMage\t\t\nI\t\tTurn in {q1949} to Magus Tirth, then accept {q1950}.\nT\t\t1949\t\nA\t\t1950\t\nS\tMage\t\t\nI\t\tTarget Plucky Johnson, use /beckon and speak to him in human form for {q1950}.\nC\t\t1950\t\t\nS\tMage\t\t\nI\t\tTurn in {q1950}, then accept {q1951}; keep it for the Scarlet Monastery Library.\nT\t\t1950\t\nA\t\t1951\t\nS\t\t\t\nI\t\tFollow the southern pass to Gadgetzan on the road, avoiding desert camps.\nS\t\t\t\nG\t\tTanaris\t51.6\t25.44\t\t\t\nI\t\tTake the flight point on arrival.\nP\t\tGadgetzan\t\nS\t\t\tcompletewith=next\nG\t\tTanaris\t51.6\t25.44\t\t\t\nI\t\tHearth to Ratchet if ready; otherwise fly from Gadgetzan.\nH\t\tHearth to Ratchet\nF\t\tRatchet\t\nS\t\t\t\nT\t\t1111\t\nA\t\t1112\t\nS\t\t\t\nT\t\t1178\t\nA\t\t1180\t\nS\t\t\t\nI\t\tFly to the Crossroads for Korran's report.\nF\t\tThe Crossroads\t\nS\t\t\t\nG\t\tThe Barrens\t51.07\t29.63\t\t\t\nT\t\t1148\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t51.07\t29.63\t\t\t\nA\t\t1184\t\nS\t\t\t\nI\t\tFly for level-34 training.\nF\t\tOrgrimmar\t\nS\t\t\t\nG\t\tOrgrimmar\t75.23\t34.24\t\t\t\nT\t\t1184\t\nS\t\t\t\nI\t\tReach level 34 before class training and Razorfen Kraul. If short, return through Ratchet to hunt isolated level 33-34 flats wildlife, then return to Orgrimmar.\nX\t\t\t34\t\t\t\nS\tWarlock\t\t\nG\t\tOrgrimmar\t48.47\t45.43\t\t\t\nI\t\tAt Zevrost, learn Corruption IV, Create Healthstone III, Drain Mana II, Rain of Fire II and Searing Pain III; learn Imp Fire Shield III and Voidwalker Consume Shadows III. Buy and use the listed demon grimoires from Kurgul nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tOrgrimmar\t80.39\t32.38\t\t\t\nI\t\tAt Sorek, learn Demoralizing Shout III, Revenge III and Sunder Armor III.\nV\t\ttrainer\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Frost Shock II, Rockbiter Weapon V, Sentry Totem and Stoneskin Totem IV.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Blind, Sprint II and Ambush III. Keep Blinding Powder for Blind.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t43.05\t53.74\t\t\t\nI\t\tAt Shenthul, learn Blinding Powder (150 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tOrgrimmar\t55.9\t62.71\t\t\t\nI\t\tBuy Blinding Powder at the Auction House for Blind, or buy Fadeleaf and make it with your learned recipe.\nV\t\tvendor\t\nS\tPriest\t\t\nG\t\tOrgrimmar\t35.59\t87.82\t\t\t\nI\t\tAt Ur'kyo, learn Heal IV, Levitate, Mind Blast V, Resurrection III and Shadow Word: Pain V. Keep a few Light Feathers for Levitate.\nV\t\ttrainer\t\nS\tPaladin\t\t\nI\t\tFly to Thunder Bluff for Paladin training.\nF\t\tThunder Bluff\t\nS\tPaladin\t\t\nG\t\tThunder Bluff\t22.62\t19.91\t\t\t\nI\t\tAt Alodan the Hopeful, learn Divine Shield I, Flash of Light III, Blessing of Wisdom III, Seal of Fury IV and Seal of Righteousness V.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tOrgrimmar\t38.35\t85.56\t\t\t\nI\t\tAt Pephredo, learn Mage Armor I and Cone of Cold II.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Disengage II, Explosive Trap I and Serpent Sting V.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Maul IV, Moonfire VI, Rake II, Rejuvenation VI, Starfire III, Swipe III and Thorns IV. Learn Lacerate II when talented.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\tFly to Camp Taurajo and follow the Gold Road south.\nF\t\tCamp Taurajo\t\nS\t\t\t\nI\t\tRepair and restock before traveling to Razorfen Kraul.\nV\t\tvendor\t\nS\t\t\t\nG\t\tThe Barrens\t42.33\t89.91\t\t\t\nI\t\tTake the western thorn path off the Gold Road to Razorfen Kraul's entrance. Join a five-player party with a tank and healer, then enter together for one clear through Charlga Razorflank. Avoid the cauldron near Roogug; you can become stuck inside.\nS\t\t\t\nI\t\tCollect one Kraul Guano from the bats during the clear for {q1109}; keep it for Faranell.\nC\t\t1109\t\t\nS\t\t\tcompletewith=next\nI\t\tAfter clearing the lower passages, use the crate to summon a Snufflenose Gopher. Use the Command Stick near tuber patches and collect six Blueleaf Tubers for {q1221}; retain the crate and stick.\nC\t\t1221\t\t\nS\t\t\t\nI\t\tDefeat Charlga Razorflank and loot her heart for {q1102}.\nC\t\t1102\t\t\nS\tShaman\t\tcompletewith=next\nI\t\tLoot Charlga's information on the quilboar's plans for {q79360}.\nC\t\t79360\t\t\nS\t\t\t\nI\t\tLoot Charlga's Small Scroll and use it to accept {q6522}; keep the delivery for Varimathras.\nU\t\t17008\t\nA\t\t6522\t\nS\t\t\t\nI\t\tFind Willix near the rear huts after clearing his return path. Confirm everyone is ready before speaking to him and accepting {q1144}.\nA\t\t1144\t\nS\t\t\t\nI\t\tEscort Willix to the entrance with the party and speak to him at the end for {q1144}.\nC\t\t1144\t\t\nS\t\t\t\nT\t\t1144\t\nS\t\t\t\nI\t\tLeave by the cleared entrance.\nS\tShaman\t\t\nI\t\tReturn by the Great Lift and Freewind lifts to Rau Cliffrunner, then turn in {q79360}.\nT\t\t79360\t\nS\tShaman\t\t\nI\t\tFly from Freewind Post to Ratchet.\nF\t\tRatchet\t\nS\t\t\tcompletewith=next\nG\t\tThe Barrens\t44.45\t59.15\t\t\t\nI\t\tIf not already in Ratchet, hearth there if ready; otherwise follow the Gold Road north to Camp Taurajo and fly.\nH\t\tHearth to Ratchet\nF\t\tRatchet\t\nS\t\t\t\nT\t\t1221\t\nS\t\t\t\nI\t\tFly to Thunder Bluff.\nF\t\tThunder Bluff\t\nS\t\t\t\nT\t\t1102\t\nS\t\t\t\nI\t\tFly to Freewind Post.\nF\t\tFreewind Post\t\nS\t\t\t\nI\t\tUse the lifts to reach the canyon floor.\nS\t\t\t\nI\t\tFollow the mountain path beside the totem pole to Dorn Plainstalker's cave and accept {q1149}.\nA\t\t1149\t\nS\t\t\t\nI\t\tAfter Dorn teleports you, follow the stones to the wooden plank and leap from its end for {q1149}; the quest teleports you back before landing.\nC\t\t1149\t\t\nS\t\t\t\nT\t\t1149\t\nA\t\t1150\t\nS\t\t\t\nI\t\tAt Roguefeather Den's hillside entrance, form a party for the harpy waves.\nS\t\t\t\nI\t\tClear the cave to the foodstuffs. If Grenka is present, defeat her and loot her claw; otherwise disturb one food crate and defeat the waves through Grenka for {q1150}. Do not restart active waves by opening another crate.\nC\t\t1150\t\t\nS\t\t\t\nI\t\tLeave by the cleared cave entrance and return to Dorn. Turn in {q1150}, then accept {q1151}.\nT\t\t1150\t\nA\t\t1151\t\nS\t\t\t\nI\t\tForm a party for Rok'Alim the Pounder in the western canyon, defeat him and loot the fragments for {q1151}.\nC\t\t1151\t\t\nS\t\t\t\nI\t\tReturn to Dorn and turn in {q1151}, then accept {q1152}.\nT\t\t1151\t\nA\t\t1152\t\nS\t\t\t\nI\t\tReturn by the mountain path and Freewind lifts to the flight point.\nS\t\t\t\nI\t\tFly to Sun Rock Retreat.\nF\t\tSun Rock Retreat\t\nS\t\t\t\nI\t\tFollow the road southeast to Braug Dimspirit near the Talondeep Path entrance.\nS\t\t\t\nT\t\t1152\t\nA\t\t1154\t\nS\t\t\t\nI\t\tFollow the Talondeep Path into Ashenvale and the southern road east to Dor'danil Barrow Den.\nS\t\t\t\nI\t\tEnter the barrow and collect Legacy of the Aspects from the table in the lower chamber for {q1154}.\nC\t\t1154\t\t\nS\t\t\t\nI\t\tReturn by the cleared barrow, Ashenvale road and Talondeep Path to Braug.\nS\t\t\t\nI\t\tTurn in {q1154}, then accept {q6627}. Answer Neltharion for {q6627}, then turn in {q6627} and accept {q1159}.\nT\t\t1154\t\nA\t\t6627\t\nC\t\t6627\t\t\nT\t\t6627\t\nA\t\t1159\t\nS\t\t\t\nI\t\tReturn to Sun Rock Retreat.\nS\t\t\t\nI\t\tFly back to Thunder Bluff.\nF\t\tThunder Bluff\t\nS\t\t\t\nI\t\tReach level 35 before Desolace. If short, return through Freewind Post to hunt isolated level 34-35 flats wildlife outside the Silithid hive, then return to Thunder Bluff.\nX\t\t\t35\t\t\t\nS\t\t\t\nI\t\tKeep An Unholy Alliance, Compendium of the Fallen, Going, Going, Guano, Frostmaw, Kravel's Parts, the crate for Hemet, Goblin Sponsorship, Martek's letter and Encrusted Tail Fins." },
  { name = "35-37 Desolace (Horde)", title = "35-37 Desolace", group = "Bethink's Guide 20-40", faction = "Horde", lo = 35, hi = 37, next = "37-38 Arathi Highlands (Horde)", defaultFor = "", cond = "Horde", bethink = true,
    about = "Ghost Walker and Shadowprey circuits, Thunder Axe Fortress and Mannoroc Coven; Scarlet Monastery’s Graveyard and Library at 36. Ends in Undercity.",
    steps = "S\t\t\t\nI\t\tStart in Thunder Bluff at 35 with An Unholy Alliance, Compendium of the Fallen, Going, Going, Guano and Frostmaw. Keep the jungle and flats deliveries.\nX\t\t\t35\t\t\t\nS\t\t\t\nI\t\tLeave Thunder Bluff by its lifts and follow the northwest Mulgore paths to the Skywatcher Plateau.\nS\t\t\t\nI\t\tAccept {q97196} from Sutara Plainstalker; keep it for Razorfen Downs.\nS\t\t\t\nI\t\tReturn by the paths and lifts to Thunder Bluff.\nS\t\t\t\nI\t\tFly to Sun Rock Retreat, then follow the mountain road south into Desolace.\nF\t\tSun Rock Retreat\t\nS\t\t\t\nI\t\tKeep clear of Nijel's Point. Follow the northern road west to Ethel Rethor and the coastal wreck before the southern hubs.\nS\t\t\t\nA\t\t5741\t\nS\t\t\t\nI\t\tRead Rackmore's Log by the wreck, then accept {q6161}.\nA\t\t6161\t\nS\t\t\t\nI\t\tFollow the main road south to Ghost Walker Post.\nS\t\t\t\nA\t\t5386\t\nS\t\t\t\nA\t\t1365\t\nS\t\t\t\nA\t\t6134\t\nS\t\t\t\nI\t\tFollow the road southwest to Shadowprey Village.\nS\t\t\tcompletewith=next\nG\t\tDesolace\t26.17\t69.65\t\t\t\nI\t\tIf ready at 125 Cooking, buy and use Expert Cookbook from Wulan; skip otherwise.\nS\t\t\t\nA\t\t5381\t\nS\t\t\t\nG\t\tDesolace\t24.09\t68.21\t\t\t\nI\t\tBind with Sikewa; repair and restock.\nB\t\tSet your hearthstone to Shadowprey Village\nS\t\t\t\nA\t\t6142\t\nS\t\t\t\nA\t\t6143\t\nS\t\t\t\nI\t\tSpeak to Jinar'Zillen on Shadowprey's shore and obtain two Bloodbelly Fish for {q5386}; keep them for Nataka.\nC\t\t5386\t\t\nS\t\t\t\nG\t\tDesolace\t21.6\t74.13\t\t\t\nI\t\tTake Thalon's flight point on the pier.\nP\t\tShadowprey Village\t\nS\t\t\t\nI\t\tCollect Rackmore's Silver Key from Drysnaps south of Shadowprey for {q6161}.\nC\t\t6161\t1\t\nS\t\t\t\nI\t\tFollow the coast north and collect ten Soft-shelled Clam Meat from the clams for {q6142}.\nC\t\t6142\t\t\nS\t\t\t\nI\t\tClear Thunder Axe Fortress through its gate. Use the Demon Pick at the crystal and recover the Demon Box for {q5381}; do not leave the pick behind.\nC\t\t5381\t\t\nS\t\t\t\nI\t\tClimb the fortress tower by its stairs, defeat the Burning Blade Seer and take the Sceptre of Light for {q5741}.\nC\t\t5741\t\t\nS\t\t\tcompletewith=next\nI\t\tIf the fortress cultists drop a Flayed Demon Skin for you, use it to accept {q1480}.\nA\t\t1480\t\nS\t\t\t\nG\t\tDesolace\t52.25\t53.44\t\t\t\nI\t\tIf active, return to Ghost Walker Post and turn in {q1480}.\nT\t\t1480\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t52.25\t53.44\t\t\t\nA\t\t1481\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t72.65\t13.23\t\t\t\nI\t\tIf active, collect a Shadowstalker Scalp from Hatefury Shadowstalkers at Sargeron for {q1481}.\nC\t\t1481\t\t\nS\t\t\t\nG\t\tDesolace\t52.25\t53.44\t\t\t\nT\t\t1481\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t52.25\t53.44\t\t\t\nA\t\t1482\t\nS\t\t\t\nT\t\t5741\t\nA\t\t6027\t\nS\t\t\t\nI\t\tKill seven Slitherblade Myrmidons, seven Naga and five Sorceresses along the northern coast, collecting Rackmore's Golden Key from them for {q6143} and {q6161}.\nC\t\t6143\t\t\nC\t\t6161\t2\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t33.89\t10.15\t\t\t\nI\t\tIf active, collect an Oracle Crystal from a Slitherblade Oracle for {q1482}.\nC\t\t1482\t\t\nS\t\t\t\nI\t\tSwim to the northern island, use the Gem of the Serpent at the statue, then defeat Lord Kragaru and loot the Book of the Ancients for {q6027}.\nC\t\t6027\t\t\nS\t\t\t\nT\t\t6161\t\nS\t\t\t\nT\t\t6027\t\nS\t\t\t\nI\t\tReturn south by the central road to Ghost Walker Post.\nS\t\t\t\nG\t\tDesolace\t52.25\t53.44\t\t\t\nT\t\t1482\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t52.25\t53.44\t\t\t\nA\t\t1484\t\nS\t\t\t\nG\t\tDesolace\t52.57\t54.39\t\t\t\nT\t\t1484\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t52.57\t54.39\t\t\t\nA\t\t1488\t\nS\t\t\t\nT\t\t5386\t\nS\t\t\t\nI\t\tClear the eastern Kolkar camp and take Khan Dez'hepah's head for {q1365}.\nC\t\t1365\t\t\nS\t\t\t\nT\t\t1365\t\nA\t\t1366\t\nS\t\t\t\nI\t\tCollect fifteen Centaur Ears from the outer Kolkar camps for {q1366}.\nC\t\t1366\t\t\nS\t\t\t\nT\t\t1366\t\nS\t\t\t\nA\t\t5501\t\nS\t\t\t\nA\t\t5561\t\nS\t\t\t\nI\t\tUse the Kodo Kombobulator on an Aged, Dying or Ancient Kodo. Lead it to Smeed and speak to it there; repeat until five have been delivered for {q5561}.\nC\t\t5561\t\t\nS\t\t\t\nT\t\t5561\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Shadowprey if ready; otherwise follow the western road.\nH\t\tHearth to Shadowprey Village\nS\t\t\t\nT\t\t6142\t\nS\t\t\t\nT\t\t6143\t\nS\t\t\t\nT\t\t5381\t\nA\t\t5581\t\nS\t\t\t\nI\t\tReach level 36 before the southern quests. If short, hunt isolated level 35-36 centaurs on the central plains.\nX\t\t\t36\t\t\t\nS\t\t\t\nI\t\tAt the Valley of Spears, reach Melizza's cage and clear the nearby exit before speaking to her and accepting {q6132}.\nA\t\t6132\t\nS\t\t\t\nI\t\tEscort Melizza to safety for {q6132}, staying beside her through the ambushes.\nC\t\t6132\t\t\nS\t\t\t\nI\t\tCollect ten Kodo Bones at the graveyard, clearing room before each pickup; defeat the summoned apparitions for {q5501}.\nC\t\t5501\t\t\nS\t\t\t\nI\t\tAt Mannoroc Coven, use the quest hand on six portals and defeat their guardians for {q5581}. Avoid pulling several portals together.\nC\t\t5581\t\t\nS\t\t\tcompletewith=next\nG\t\tDesolace\t56.95\t75.74\t\t\t\nI\t\tIf active, form a party at the coven for Lord Azrethoc and Jugkar Grim'rod, then clear to them and defeat both for {q1488}.\nC\t\t1488\t\t\nS\t\t\t\nI\t\tAt the Valley of Bones, place the Crate of Ghost Magnets, step back and defeat the attracted spectres and collect eight Ghost-o-plasms for {q6134}.\nC\t\t6134\t\t\nS\t\t\t\nT\t\t6132\t\nT\t\t6134\t\nS\t\t\t\nT\t\t5501\t\nS\t\t\t\nG\t\tDesolace\t52.57\t54.39\t\t\t\nT\t\t1488\t\nS\t\t\tcompletewith=next\nI\t\tHearth to Shadowprey if ready; otherwise take the western road.\nH\t\tHearth to Shadowprey Village\nS\t\t\t\nT\t\t5581\t\nS\t\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\tShaman\t\t\nG\t\tOrgrimmar\t38.66\t35.92\t\t\t\nI\t\tAt Sagorne Creststrider, learn Ancestral Spirit III, Earth Shock V, Flametongue Weapon IV, Lesser Healing Wave III, Magma Totem II, Mana Spring Totem II and Windwall Totem I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.05\t18.53\t\t\t\nI\t\tAt Ormak Grimshot, learn Aimed Shot III, Arcane Shot V, Immolation Trap III, Mend Pet IV and Viper Sting I.\nV\t\ttrainer\t\nS\tHunter\t\t\nG\t\tOrgrimmar\t66.32\t14.81\t\t\t\nI\t\tAt Xao'tsu, learn Great Stamina VI, Natural Armor VI. Open Beast Training and teach the usable ranks to your active pet as its level and training points allow.\nV\t\ttrainer\t\nS\tDruid\t\t\nI\t\tCast Teleport: Moonglade for Druid training.\nS\tDruid\t\t\nG\t\tMoonglade\t52.53\t40.57\t\t\t\nI\t\tAt Loganaar, learn Frenzied Regeneration, Pounce I, Regrowth V, Revive III and Rip III.\nV\t\ttrainer\t\nS\tDruid\t\t\nG\t\tMoonglade\t44.28\t45.87\t\t\t\nI\t\tAsk Bunthen Plainswind for the Druid flight to Thunder Bluff.\nS\tDruid\t\t\nI\t\tFly to Orgrimmar.\nF\t\tOrgrimmar\t\nS\t\t\t\nI\t\tTake the Tirisfal zeppelin outside Orgrimmar and enter Undercity by its main lifts.\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: V106_TEST_OF_LORE_PREPARATION\nS\t\t\t\nI\t\tGuide migration: Before the scheduled Library clear, visit Dorn Plainstalker's cave by Freewind Post and accept {q1149}. If that clear is already behind you, skip this chain.\nA\t\t1149\t\nS\t\t\t\nI\t\tGuide migration: After Dorn teleports you, follow the stones to the wooden plank and leap from its end for {q1149}; the quest returns you before landing.\nC\t\t1149\t\t\nS\t\t\t\nI\t\tGuide migration: Turn in {q1149}, then accept {q1150}.\nT\t\t1149\t\nA\t\t1150\t\nS\t\t\t\nI\t\tGuide migration: At Roguefeather Den, form a party for the harpy waves. Clear to the foodstuffs, defeat Grenka if present or disturb one crate and defeat her waves for {q1150}. Do not open another crate during the event.\nC\t\t1150\t\t\nS\t\t\t\nI\t\tGuide migration: Return to Dorn, turn in {q1150} and accept {q1151}.\nT\t\t1150\t\nA\t\t1151\t\nS\t\t\t\nI\t\tGuide migration: Form a party for Rok'Alim in the western canyon. Defeat him and loot the fragments for {q1151}.\nC\t\t1151\t\t\nS\t\t\t\nI\t\tGuide migration: Return to Dorn, turn in {q1151} and accept {q1152}.\nT\t\t1151\t\nA\t\t1152\t\nS\t\t\t\nI\t\tGuide migration: Travel through Freewind Post and Sun Rock Retreat to Braug Dimspirit near Talondeep Path. Turn in {q1152}, then accept {q1154}.\nT\t\t1152\t\nA\t\t1154\t\nS\t\t\t\nI\t\tGuide migration: Follow Talondeep Path into Ashenvale and enter Dor'danil Barrow Den. Collect Legacy of the Aspects from the lower chamber for {q1154}.\nC\t\t1154\t\t\nS\t\t\t\nI\t\tGuide migration: Return to Braug, turn in {q1154} and accept {q6627}. Answer Neltharion for {q6627}, turn in {q6627} and accept {q1159}.\nT\t\t1154\t\nA\t\t6627\t\nC\t\t6627\t\t\nT\t\t6627\t\nA\t\t1159\t\nS\t\t\t\nI\t\tGuide migration: Return through Orgrimmar and the Tirisfal zeppelin to Parqual Fintallas in Undercity, then turn in {q1159}.\nT\t\t1159\t\nS\t\t\t\nI\t\t-- MIGRATION END: V106_TEST_OF_LORE_PREPARATION\nS\t\t\t\nI\t\tTurn in {q1159} to Parqual Fintallas, then accept {q1160}.\nT\t\t1159\t\nA\t\t1160\t\nS\t\t\t\nT\t\t1109\t\nA\t\t1113\t\nS\t\t\t\nI\t\tTurn in {q6522}, then accept {q6521}; keep it for the later Razorfen Downs outer camps. Accept {q1048}.\nT\t\t6522\t\nA\t\t6521\t\nA\t\t1048\t\nS\tWarlock\t\t\nG\t\tUndercity\t86.21\t15.93\t\t\t\nI\t\tAt Kaal Soulreaper, learn Shadow Bolt VI, Life Tap IV, Health Funnel IV, Create Firestone II and Create Spellstone; learn Voidwalker Suffering II. Buy and use the listed demon grimoires from Martha Strain nearby.\nV\t\ttrainer\t\nS\tWarrior\t\t\nG\t\tUndercity\t47.4\t17.29\t\t\t\nI\t\tAt Baltus Fowler, learn Mocking Blow III and Whirlwind.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Backstab V, Expose Armor III and Rupture III.\nV\t\ttrainer\t\nS\tRogue\t\t\nG\t\tUndercity\t84.88\t73.53\t\t\t\nI\t\tAt Gregory Charles, learn Instant Poison III (160 Poisons). Learn recipes as your Poisons skill allows; skip unavailable recipes.\nV\t\ttrainer\t\nS\tPriest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Devouring Plague III, Dispel Magic II, Holy Fire IV, Mind Soothe II, Power Word: Fortitude IV and Power Word: Shield VI.\nV\t\ttrainer\t\nS\tTroll Priest\t\t\nG\t\tUndercity\t49.26\t17.12\t\t\t\nI\t\tAt Aelthalyste, learn Shadowguard III.\nV\t\ttrainer\t\nS\tPaladin\t\t\nG\t\tUndercity\t47.08\t15.9\t\t\t\nI\t\tAt Garen Largo, learn Holy Strike V, Redemption III, Exorcism III, Fire Resistance Aura I and Retribution Aura III.\nV\t\ttrainer\t\nS\tMage\t\t\nG\t\tUndercity\t85.14\t10.03\t\t\t\nI\t\tAt Anastasia Hartwell, learn Fireball VII and Blizzard III.\nV\t\ttrainer\t\nS\t\t\t\nI\t\tRepair, restock and train available abilities and chosen professions.\nV\t\tvendor\t\nS\t\t\t\nI\t\t-- MIGRATION BEGIN: V106_MAGE_LIBRARY_PREPARATION\nS\tMage\t\t\nI\t\tGuide migration: Before the scheduled Library clear, visit your Mage trainer in Undercity and accept {q1947}. If that clear is already behind you, skip this quest and its follow-ups.\nA\t\t1947\t\nS\tMage\t\t\nI\t\tGuide migration: Travel through Booty Bay and Ratchet to Tabetha in Dustwallow Marsh, then turn in {q1947}.\nT\t\t1947\t\nS\tMage\t\t\nI\t\tGuide migration: At Tabetha, accept {q1948} and {q1949}.\nA\t\t1948\t\nA\t\t1949\t\nS\tMage\t\t\nI\t\tGuide migration: Visit Magus Tirth on the Shimmering Flats and turn in {q1949}, then accept {q1950}.\nT\t\t1949\t\nA\t\t1950\t\nS\tMage\t\t\nI\t\tGuide migration: Target Plucky Johnson, use /beckon and speak to him in human form for {q1950}.\nC\t\t1950\t\t\nS\tMage\t\t\nI\t\tGuide migration: Return to Magus Tirth, turn in {q1950} and accept {q1951}. Return through Ratchet and Booty Bay to Undercity before the Monastery journey.\nT\t\t1950\t\nA\t\t1951\t\nS\t\t\t\nI\t\t-- MIGRATION END: V106_MAGE_LIBRARY_PREPARATION\nS\t\t\t\nI\t\tLeave Undercity by the lifts, pass Brill and follow the northeastern road to Scarlet Monastery's entrance. Join a five-player party with a tank and healer for the Graveyard clear.\nS\t\t\t\nG\t\tTirisfal Glades\t84.8\t32.4\t\t\t\nI\t\tEnter the left-hand Graveyard portal together. Complete one clear through Interrogator Vishas and Bloodmage Thalnos.\nS\t\t\t\nI\t\tSpeak to Vorrel Sengutz in the cleared torture area and accept {q1051} for the Alterac circuit.\nA\t\t1051\t\nS\t\t\t\nI\t\tReturn to the vestibule and join a five-player party with a tank and healer for the right-hand Library portal. Complete one clear through Houndmaster Loksey and Arcanist Doan.\nS\t\t\tcompletewith=next\nI\t\tDefeat Houndmaster Loksey for {q1048}. Keep the remaining bosses for the later Armory and Cathedral visit.\nC\t\t1048\t4\t\nS\t\t\t\nI\t\tRecover the Compendium of the Fallen from the Library's final rooms for {q1049}.\nC\t\t1049\t\t\nS\t\t\t\nI\t\tCollect The Beginnings of the Undead Threat from the Library bookshelves for {q1160}.\nC\t\t1160\t\t\nS\t\t\t\nI\t\tCollect twenty Hearts of Zeal from Scarlet humanoids during the two clears for {q1113}; finish outside the monastery if the counters need more.\nC\t\t1113\t\t\nS\tMage\t\t\nI\t\tCollect Rituals of Power from the Library bookshelves for {q1951}.\nC\t\t1951\t\t\nS\t\t\t\nI\t\tAfter Doan, take The Scarlet Key from his strongbox and keep it for the Armory and Cathedral. Leave by the cleared vestibule.\nS\t\t\t\nI\t\tReturn by the road through Brill and the main Undercity lifts.\nS\t\t\t\nT\t\t1113\t\nS\t\t\t\nI\t\tTurn in {q1160} to Parqual, then accept {q6628}. Answer Ner'zhul for {q6628}, then turn in {q6628} and accept {q1394}.\nT\t\t1160\t\nA\t\t6628\t\nC\t\t6628\t\t\nT\t\t6628\t\nA\t\t1394\t\nS\t\t\t\nI\t\tReach level 37 before Arathi. If short, hunt isolated level 36-37 Scarlet humanoids outside the monastery, then return by the road.\nX\t\t\t37\t\t\t\nS\t\t\t\nI\t\tKeep An Unholy Alliance, the Scarlet Key, Into the Scarlet Monastery, Compendium of the Fallen, Frostmaw and Vorrel's Revenge." },
  { name = "37-38 Arathi Highlands (Horde)", title = "37-38 Arathi Highlands", group = "Bethink's Guide 20-40", faction = "Horde", lo = 37, hi = 38, next = "38-39 Dustwallow Marsh (Horde)", defaultFor = "", cond = "Horde", bethink = true,
